import { createHash } from "node:crypto";
import { z } from "zod";
import type { EventLog } from "../kernel/event-log";
import { defineEvent, type DomainEvent } from "../kernel/events";

/** Audit totality (E11.2): every side effect leaves exactly one AuditEvent with these fields. */
export const auditEventSchema = defineEvent("AuditEvent", {
  actor: z.string(),
  brainVersion: z.string(),
  modelVersion: z.string(),
  toolVersion: z.string(),
  inputsHash: z.string(),
  outputSummary: z.string(),
  approvalSource: z.enum(["policy", "owner", "none"]),
  financialImpactMinor: z.number().int(),
  rollbackRef: z.string().nullable(),
  sideEffectId: z.string(),
});

/** The caller-supplied audit fields: the payload plus the logical time `at`. */
export type AuditFields = {
  at: number;
  actor: string;
  brainVersion: string;
  modelVersion: string;
  toolVersion: string;
  inputsHash: string;
  outputSummary: string;
  approvalSource: "policy" | "owner" | "none";
  financialImpactMinor: number;
  rollbackRef: string | null;
  sideEffectId: string;
};

export function sha256Hex(input: string): string {
  return createHash("sha256").update(input).digest("hex");
}

/** JSON with sorted object keys at every level (§C3) so `inputsHash` is stable across key order. */
export function stableStringify(value: unknown): string {
  if (Array.isArray(value)) {
    return `[${value.map((item) => stableStringify(item)).join(",")}]`;
  }
  if (value !== null && typeof value === "object") {
    const entries = Object.entries(value as Record<string, unknown>).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
    return `{${entries.map(([key, item]) => `${JSON.stringify(key)}:${stableStringify(item)}`).join(",")}}`;
  }
  return JSON.stringify(value) ?? "null";
}

/** Validate (the schema throws on a missing field) and append one AuditEvent. */
export function emitAudit(log: EventLog, a: AuditFields): DomainEvent {
  const { at, ...payload } = a;
  auditEventSchema.omit({ id: true, seq: true }).parse({ ...payload, at, type: "AuditEvent" });
  return log.append({ ...payload, at, type: "AuditEvent" });
}

import type { EventLog } from "../kernel/event-log";

export type EffectClass = "internal" | "external";

/** Every event type the slice treats as a REAL side effect (money moved, branch applied, message sent, publish, escalation). */
export const EXTERNAL_EFFECT_TYPES: ReadonlySet<string> = new Set([
  "MoneyMoved",
  "ResultBranchApplied",
  "SupportTicketReplied",
  "LaunchPublished",
  "PluginInstalled",
  "AuthorityEscalationBlocked",
]);

export function classifyEffect(eventType: string): EffectClass {
  return EXTERNAL_EFFECT_TYPES.has(eventType) ? "external" : "internal";
}

/**
 * Totality of audit (E11.2): every external event has EXACTLY one AuditEvent whose sideEffectId is its id, and every
 * AuditEvent references an existing external event. Throws with a precise message on the first violation.
 */
export function assertAuditTotality(log: EventLog): void {
  const events = log.all();
  const externalIds = new Set(events.filter((e) => classifyEffect(e.type) === "external").map((e) => e.id));
  const auditsBySideEffect = new Map<string, number>();
  for (const event of events) {
    if (event.type !== "AuditEvent") {
      continue;
    }
    const sideEffectId = String(event.sideEffectId);
    if (!externalIds.has(sideEffectId)) {
      throw new Error(`audit without side effect: AuditEvent ${event.id} references "${sideEffectId}", which is not an external event`);
    }
    auditsBySideEffect.set(sideEffectId, (auditsBySideEffect.get(sideEffectId) ?? 0) + 1);
  }
  for (const event of events) {
    if (classifyEffect(event.type) !== "external") {
      continue;
    }
    const count = auditsBySideEffect.get(event.id) ?? 0;
    if (count !== 1) {
      throw new Error(`side effect without audit: ${event.type} ${event.id} has ${count} audit event(s), expected exactly 1`);
    }
  }
}

