import { z } from "zod";
import { type AuditFields, emitAudit } from "../audit/audit";
import type { EventLog } from "../kernel/event-log";
import { defineEvent } from "../kernel/events";
import { meetsMin, TRUST_ORDER, type Trust } from "../trust/trust";
import { type Capability, isValid } from "./capability";

export interface GateRequest {
  required: Trust;
  evidenceTrust: Trust;
  token: Capability | null;
  now: number;
  needMinor?: number;
}

export type GateResult = { ok: true } | { ok: false; reason: "under-trusted" | "no-token" | "expired" | "over-cap" };

/** Recorded whenever the gate refuses: a side effect into the approval queue (audited, E11.3). */
export const authorityEscalationBlockedEvent = defineEvent("AuthorityEscalationBlocked", {
  reason: z.enum(["under-trusted", "no-token", "expired", "over-cap"]),
  required: z.enum(TRUST_ORDER),
  evidenceTrust: z.enum(TRUST_ORDER),
  tokenId: z.string().nullable(),
  needMinor: z.number().int().nullable(),
});

/** Authority non-escalation (E2 / E11.3): trust, token validity and spend cap are all checked, in that order of certainty. */
export function checkGate(req: GateRequest): GateResult {
  if (req.token === null) {
    return { ok: false, reason: "no-token" };
  }
  if (!isValid(req.token, req.now)) {
    return { ok: false, reason: "expired" };
  }
  if (!meetsMin(req.evidenceTrust, req.required)) {
    return { ok: false, reason: "under-trusted" };
  }
  if (req.needMinor != null && req.token.minorUnits != null && req.needMinor > req.token.minorUnits) {
    return { ok: false, reason: "over-cap" };
  }
  return { ok: true };
}

/** Run the gate; on failure append an AuthorityEscalationBlocked event plus its audit, then return the failure. */
export function gateOrBlock(log: EventLog, req: GateRequest, blockAudit: Omit<AuditFields, "approvalSource">): GateResult {
  const result = checkGate(req);
  if (result.ok) {
    return result;
  }
  const blocked = log.append({
    type: "AuthorityEscalationBlocked",
    at: req.now,
    reason: result.reason,
    required: req.required,
    evidenceTrust: req.evidenceTrust,
    tokenId: req.token?.id ?? null,
    needMinor: req.needMinor ?? null,
  });
  emitAudit(log, { ...blockAudit, approvalSource: "none", sideEffectId: blocked.id });
  return result;
}

