    g.link({ from: a.id, to: b.id, sign: "supports", confidence: 1.5, freshnessAt: 0 });
    g.link({ from: a.id, to: b.id, sign: "contradicts", confidence: -0.2, freshnessAt: 0 });
    expect(g.edgesFrom(a.id).map((e) => e.confidence)).toEqual([1, 0]);
  });

  it("refuses edges to unknown nodes and hands out copies", () => {
    const g = makeEvidenceGraph(stubPrng());
    const a = g.addNode({ kind: "fact", trust: "benchmarked", label: "a" });
    expect(() => g.link({ from: a.id, to: "ghost", sign: "supports", confidence: 1, freshnessAt: 0 })).toThrow(RangeError);
    const b = g.addNode({ kind: "claim", trust: "benchmarked", label: "b" });
    g.link({ from: a.id, to: b.id, sign: "supports", confidence: 1, freshnessAt: 0 });
    g.edgesFrom(a.id).pop();
    expect(g.edgesFrom(a.id)).toHaveLength(1);
  });
});

import type { Trust } from "../trust/trust";

export type NodeKind = "fact" | "claim" | "score" | "thesis" | "forecast" | "decision" | "action";

export interface EvNode {
  id: string;
  kind: NodeKind;
  trust: Trust;
  label: string;
  data?: unknown;
}

export interface EvEdge {
  from: string;
  to: string;
  sign: "supports" | "contradicts";
  confidence: number;
  freshnessAt: number;
}

export interface EvidenceGraph {
  addNode(n: Omit<EvNode, "id">): EvNode;
  link(e: EvEdge): void;
  node(id: string): EvNode | undefined;
  edgesFrom(id: string): EvEdge[];
}

/** The id source the graph needs; S03's `Prng` satisfies it structurally (`nextId`). */
export interface Prng {
  nextId(prefix: string): string;
}

function clamp01(n: number): number {
  if (Number.isNaN(n)) {
    return 0;
  }
  return Math.min(1, Math.max(0, n));
}

/** Adjacency-map evidence graph: nodes by id, outgoing edges per source id. Every node/edge is reviewable (E11.6). */
export function makeEvidenceGraph(prng: Prng): EvidenceGraph {
  const nodes = new Map<string, EvNode>();
  const edges = new Map<string, EvEdge[]>();
  return {
    addNode(n) {
      const node: EvNode = { ...n, id: prng.nextId("ev") };
      nodes.set(node.id, node);
      return node;
    },
    link(e) {
      const missing = !nodes.has(e.from) ? e.from : !nodes.has(e.to) ? e.to : null;
      if (missing !== null) {
        throw new RangeError(`link: unknown node ${missing}`);
      }
      const edge: EvEdge = { ...e, confidence: clamp01(e.confidence) };
      const list = edges.get(e.from) ?? [];
      list.push(edge);
      edges.set(e.from, list);
    },
    node: (id) => nodes.get(id),
    edgesFrom: (id) => [...(edges.get(id) ?? [])],
  };
}

import { describe, expect, it } from "vitest";
import { type EvidenceGraph, makeEvidenceGraph, type Prng } from "../../src/evidence/graph";
import { traceGrounding } from "../../src/evidence/grounding";

function stubPrng(): Prng {
  let n = 0;
  return { nextId: (prefix) => `${prefix}-${(n += 1)}` };
}

function decisionWith(g: EvidenceGraph, facts: Array<{ trust: "web-scraped-untrusted" | "owner-stated" | "benchmarked" }>): string {
  const decision = g.addNode({ kind: "decision", trust: "owner-stated", label: "ship it" });
  for (const fact of facts) {
    const node = g.addNode({ kind: "fact", trust: fact.trust, label: fact.trust });
    g.link({ from: decision.id, to: node.id, sign: "supports", confidence: 1, freshnessAt: 0 });
  }
  return decision.id;
}

describe("grounding traversal", () => {
  it("a decision supported only by a web-scraped fact is not grounded for a first-party-verified gate", () => {
    const g = makeEvidenceGraph(stubPrng());
    const decision = decisionWith(g, [{ trust: "web-scraped-untrusted" }]);
    const result = traceGrounding(g, decision, "first-party-verified");
    expect(result.grounded).toBe(false);
    expect(result.weakestLeafTrust).toBe("web-scraped-untrusted");
    expect(result.leafIds).toHaveLength(1);
  });

  it("an owner-stated supporting fact grounds it; a web-scraped leaf still blocks a high gate", () => {
    const g = makeEvidenceGraph(stubPrng());
    const decision = decisionWith(g, [{ trust: "owner-stated" }]);
    expect(traceGrounding(g, decision, "first-party-verified").grounded).toBe(true);
    const mixed = decisionWith(g, [{ trust: "owner-stated" }, { trust: "web-scraped-untrusted" }]);
    expect(traceGrounding(g, mixed, "first-party-verified").grounded).toBe(false);
    expect(traceGrounding(g, mixed, "community-claim").grounded).toBe(false);
    expect(traceGrounding(g, mixed, "web-scraped-untrusted").grounded).toBe(true);
  });

  it("a cycle does not hang and contradicts edges are not followed", () => {
    const g = makeEvidenceGraph(stubPrng());
    const a = g.addNode({ kind: "decision", trust: "owner-stated", label: "a" });
    const b = g.addNode({ kind: "claim", trust: "benchmarked", label: "b" });
    const leaf = g.addNode({ kind: "fact", trust: "benchmarked", label: "leaf" });
    g.link({ from: a.id, to: b.id, sign: "supports", confidence: 1, freshnessAt: 0 });
    g.link({ from: b.id, to: a.id, sign: "supports", confidence: 1, freshnessAt: 0 });
    g.link({ from: b.id, to: leaf.id, sign: "supports", confidence: 1, freshnessAt: 0 });
    g.link({ from: a.id, to: g.addNode({ kind: "fact", trust: "web-scraped-untrusted", label: "against" }).id, sign: "contradicts", confidence: 1, freshnessAt: 0 });
    const result = traceGrounding(g, a.id, "benchmarked");
    expect(result.grounded).toBe(true);
    expect(result.leafIds).toEqual([leaf.id]);
  });

  it("a decision with no supporting leaves is never grounded", () => {
    const g = makeEvidenceGraph(stubPrng());
    const lonely = g.addNode({ kind: "decision", trust: "owner-stated", label: "lonely" });
    const result = traceGrounding(g, lonely.id, "adversarial-quarantined");
    expect(result.grounded).toBe(false);
    expect(result.leafIds).toEqual([]);
  });
});

import { meetsMin, TRUST_ORDER, type Trust, trustRank, weakest } from "../trust/trust";
import type { EvidenceGraph } from "./graph";

export interface GroundingResult {
  grounded: boolean;
  weakestLeafTrust: Trust;
  leafIds: string[];
}

const LOW_TRUST_LEAVES: ReadonlySet<Trust> = new Set<Trust>(["model-generated", "web-scraped-untrusted"]);

/**
 * Walk `supports` edges from the decision to its leaves (nodes with no outgoing supports edges; the decision itself
 * never counts as its own leaf). A decision with no supporting leaves is never grounded. Cycles are cut by a
 * visited set. Under-grounded → no high gate (E3 / E11.6 / V8.13).
 */
export function traceGrounding(g: EvidenceGraph, decisionId: string, required: Trust): GroundingResult {
  const visited = new Set<string>();
  const leafIds: string[] = [];
  const stack: string[] = [decisionId];
  while (stack.length > 0) {
    const id = stack.pop() as string;
    if (visited.has(id)) {
      continue;
    }
    visited.add(id);
    if (g.node(id) === undefined) {
      continue;
    }
    const supports = g.edgesFrom(id).filter((edge) => edge.sign === "supports");
    if (supports.length === 0) {
      if (id !== decisionId) {
        leafIds.push(id);
      }
      continue;
    }
    for (const edge of supports) {
      if (!visited.has(edge.to)) {
        stack.push(edge.to);
      }
    }
  }
  const leafTrusts = leafIds.map((id) => g.node(id)?.trust).filter((t): t is Trust => t !== undefined);
  if (leafTrusts.length === 0) {
    return { grounded: false, weakestLeafTrust: TRUST_ORDER[0], leafIds };
  }
  const weakestLeafTrust = leafTrusts.reduce((acc, t) => weakest(acc, t));
  const highGate = trustRank(required) >= trustRank("first-party-verified");
  const hasLowTrustLeaf = leafTrusts.some((t) => LOW_TRUST_LEAVES.has(t));
  const grounded = meetsMin(weakestLeafTrust, required) && !(highGate && hasLowTrustLeaf);
  return { grounded, weakestLeafTrust, leafIds };
}

