import { createHash } from "node:crypto";

/** A recorded model conversation: the model is a recorded dependency (V1 / E11.7). */
export interface BrainResponse {
  text: string;
  toolCalls: { name: string; argsJson: string }[];
  confidence: number;
}

export interface BrainTranscript {
  version: string;
  entries: Record<string /* promptFingerprint */, BrainResponse>;
}

export function sha256Hex(text: string): string {
  return createHash("sha256").update(text).digest("hex");
}

/** sha256 of the trimmed prompt — whitespace at the ends must not change the recording. */
export function fingerprintPrompt(prompt: string): string {
  return sha256Hex(prompt.trim());
}

/** Replay a recorded response; an unrecorded prompt is a bug, never a live call. */
export function replay(t: BrainTranscript, prompt: string): BrainResponse {
  const fingerprint = fingerprintPrompt(prompt);
  const entry = t.entries[fingerprint];
  if (!entry) {
    throw new Error(`no recorded transcript entry for prompt fingerprint ${fingerprint}`);
  }
  return { ...entry, toolCalls: entry.toolCalls.map((call) => ({ ...call })) };
}

