import { z } from "zod";
import type { EventLog } from "../kernel/event-log";
import { defineEvent } from "../kernel/events";
import type { BrainTranscript } from "./transcript";

export type BrainStatus = "active" | "candidate" | "standby" | "quarantined";

export interface Brain {
  version: string;
  transcript: BrainTranscript;
  status: BrainStatus;
  competence: Record<string, number>;
}

export interface BrainRegistry {
  active(): Brain;
  candidate(): Brain | null;
  promote(version: string, log: EventLog): void;
  failover(log: EventLog): void;
  setStatus(v: string, s: BrainStatus): void;
  list(): Brain[];
}

export const brainPromotedEvent = defineEvent("BrainPromoted", { from: z.string(), to: z.string() });
export const brainFailoverEvent = defineEvent("BrainFailover", { from: z.string(), to: z.string() });

/** Two-brain integrity: exactly one active brain at every moment; promotions and failovers are logged. */
export function makeBrainRegistry(initial: readonly Brain[], now: () => number): BrainRegistry {
  const brains = new Map<string, Brain>();
  for (const brain of initial) {
    if (brains.has(brain.version)) {
      throw new RangeError(`duplicate brain version ${brain.version}`);
    }
    brains.set(brain.version, { ...brain, competence: { ...brain.competence } });
  }
  const actives = [...brains.values()].filter((b) => b.status === "active");
  if (actives.length !== 1) {
    throw new RangeError(`registry needs exactly one active brain, got ${actives.length}`);
  }
  const require = (version: string): Brain => {
    const brain = brains.get(version);
    if (!brain) {
      throw new RangeError(`unknown brain version ${version}`);
    }
    return brain;
  };
  const active = (): Brain => {
    const found = [...brains.values()].find((b) => b.status === "active");
    if (!found) {
      throw new Error("invariant broken: no active brain");
    }
    return found;
  };
  const setStatus = (version: string, status: BrainStatus): void => {
    const brain = require(version);
    if (status === "active" && brain.status !== "active" && [...brains.values()].some((b) => b.status === "active")) {
      throw new RangeError(`two active brains are impossible: ${active().version} is already active`);
    }
    if (status !== "active" && brain.status === "active") {
      throw new RangeError(`cannot demote the only active brain ${version} without a promotion or failover`);
    }
    brain.status = status;
  };
  return {
    active,
    candidate: () => [...brains.values()].find((b) => b.status === "candidate") ?? null,
    list: () => [...brains.values()].map((b) => ({ ...b, competence: { ...b.competence } })),
    setStatus,
    promote(version, log) {
      const next = require(version);
      if (next.status !== "candidate") {
        throw new RangeError(`only a candidate can be promoted; ${version} is ${next.status}`);
      }
      const previous = active();
      previous.status = "standby";
      next.status = "active";
      log.append({ type: "BrainPromoted", at: now(), from: previous.version, to: next.version });
    },
    failover(log) {
      const previous = active();
      const standby = [...brains.values()].find((b) => b.status === "standby");
      if (!standby) {
        throw new RangeError("failover impossible: no standby brain");
      }
      previous.status = "quarantined";
      standby.status = "active";
      log.append({ type: "BrainFailover", at: now(), from: previous.version, to: standby.version });
    },
  };
}

