import { z } from "zod";
import type { EventLog } from "../kernel/event-log";
import { defineEvent, type DomainEvent } from "../kernel/events";
import { TRUST_ORDER, type Trust } from "../trust/trust";

/** Durable externalized memory: claims are folded from MemoryWritten events; corrections supersede, never overwrite (E13). */
export interface MemoryClaim {
  key: string;
  value: unknown;
  trust: Trust;
  provenance: string;
  supersedes: string | null;
  at: number;
}

export const MEMORY_WRITTEN = "MemoryWritten";

export const memoryWrittenEvent = defineEvent(MEMORY_WRITTEN, {
  key: z.string().min(1),
  value: z.unknown(),
  trust: z.enum(TRUST_ORDER),
  provenance: z.string().min(1),
  supersedes: z.string().min(1).nullable(),
});

interface ClaimRecord extends MemoryClaim {
  id: string;
}

function claimsFor(log: EventLog, key: string): ClaimRecord[] {
  const claims: ClaimRecord[] = [];
  for (const event of log.all()) {
    if (event.type !== MEMORY_WRITTEN) {
      continue;
    }
    const written = memoryWrittenEvent.parse(event);
    if (written.key !== key) {
      continue;
    }
    claims.push({
      id: written.id,
      key: written.key,
      value: written.value,
      trust: written.trust,
      provenance: written.provenance,
      supersedes: written.supersedes,
      at: written.at,
    });
  }
  return claims;
}

function stripId(claim: ClaimRecord): MemoryClaim {
  const { id: _id, ...claimWithoutId } = claim;
  return claimWithoutId;
}

/** Append a claim; a correction names the claim it supersedes (the prior event id). Returns the event (its id is the claim id). */
export function writeMemory(
  log: EventLog,
  claim: Omit<MemoryClaim, "at" | "supersedes"> & { supersedes?: string | null },
  now: number,
): DomainEvent {
  return log.append({
    type: MEMORY_WRITTEN,
    at: now,
    key: claim.key,
    value: claim.value,
    trust: claim.trust,
    provenance: claim.provenance,
    supersedes: claim.supersedes ?? null,
  });
}

/** The latest claim for `key` that no later claim supersedes. */
export function readMemory(log: EventLog, key: string): MemoryClaim | undefined {
  const claims = claimsFor(log, key);
  const superseded = new Set(claims.map((claim) => claim.supersedes).filter((id): id is string => id !== null));
  const live = claims.filter((claim) => !superseded.has(claim.id));
  const latest = live[live.length - 1];
  return latest ? stripId(latest) : undefined;
}

/** The full correction history for `key`, oldest first — nothing is ever dropped. */
export function memoryLineage(log: EventLog, key: string): MemoryClaim[] {
  return claimsFor(log, key).map(stripId);
}

