import { z } from "zod";
import type { EventLog } from "../kernel/event-log";
import { defineEvent, type DomainEvent } from "../kernel/events";

/** The guard written BEFORE a paid/external effect fires, so a failover that replays the log cannot fire it twice (E11.4). */
export const sideEffectCommittedEvent = defineEvent("SideEffectCommitted", { effectKey: z.string().min(1) });

export function isCommitted(log: EventLog, effectKey: string): boolean {
  return log.all().some((event) => event.type === "SideEffectCommitted" && event.effectKey === effectKey);
}

/**
 * Fire `doEffect` at most once per effectKey across restarts: fold the log for an existing guard; if present return
 * null (no re-fire); else append the guard, run the effect, return its event. `now` stamps the guard (defaults to
 * the log's latest logical time).
 */
export function commitOnce(log: EventLog, effectKey: string, doEffect: () => DomainEvent, now?: number): DomainEvent | null {
  if (isCommitted(log, effectKey)) {
    return null;
  }
  const all = log.all();
  const at = now ?? all[all.length - 1]?.at ?? 0;
  log.append({ type: "SideEffectCommitted", at, effectKey });
  return doEffect();
}

