import { z } from "zod";
import { type AuditFields, emitAudit } from "../audit/audit";
import type { EventLog } from "../kernel/event-log";
import { defineEvent, type DomainEvent } from "../kernel/events";

/** Money is integer minor units (cents) — never floats. Every movement carries its audit (E11.1, E11.2). */
export const moneyMovedSchema = defineEvent("MoneyMoved", {
  fromAccount: z.string(),
  toAccount: z.string(),
  minor: z.number().int().nonnegative(),
  reason: z.string(),
  sideEffectId: z.string(),
});

/** Append a MoneyMoved AND its matching AuditEvent in one call; both carry the same sideEffectId. */
export function moveMoney(
  log: EventLog,
  m: { from: string; to: string; minor: number; reason: string },
  audit: AuditFields,
): DomainEvent {
  if (!Number.isInteger(m.minor) || m.minor < 0) {
    throw new RangeError(`moveMoney: minor units must be a non-negative integer, got ${m.minor}`);
  }
  const moved = log.append({
    type: "MoneyMoved",
    at: audit.at,
    fromAccount: m.from,
    toAccount: m.to,
    minor: m.minor,
    reason: m.reason,
    sideEffectId: audit.sideEffectId,
  });
  emitAudit(log, { ...audit, sideEffectId: moved.id });
  return moved;
}

/** Fold balances: from -= minor, to += minor. */
export function balances(log: EventLog): Record<string, number> {
  const totals: Record<string, number> = {};
  for (const event of log.all()) {
    if (event.type !== "MoneyMoved") {
      continue;
    }
    const moved = moneyMovedSchema.parse(event);
    totals[moved.fromAccount] = (totals[moved.fromAccount] ?? 0) - moved.minor;
    totals[moved.toAccount] = (totals[moved.toAccount] ?? 0) + moved.minor;
  }
  return totals;
}

/** Σ debits === Σ credits: the system-wide delta of every movement is zero. */
export function assertConservation(log: EventLog): void {
  const total = Object.values(balances(log)).reduce((sum, value) => sum + value, 0);
  if (total !== 0) {
    throw new Error(`conservation violated: balances sum to ${total} minor units, expected 0`);
  }
}

/** Ledger-level audit totality: every MoneyMoved has exactly one AuditEvent whose sideEffectId is the movement's id. */
export function assertLedgerAudited(log: EventLog): void {
  const events = log.all();
  const audited = new Map<string, number>();
  for (const event of events) {
    if (event.type === "AuditEvent") {
      const id = String(event.sideEffectId);
      audited.set(id, (audited.get(id) ?? 0) + 1);
    }
  }
  for (const event of events) {
    if (event.type === "MoneyMoved") {
      const count = audited.get(event.id) ?? 0;
      if (count !== 1) {
        throw new Error(`side effect without audit: MoneyMoved ${event.id} has ${count} audit event(s), expected exactly 1`);
      }
    }
  }
}

