import type { AuditFields } from "../audit/audit";
import type { Capability } from "../auth/capability";
import { checkGate, gateOrBlock } from "../auth/gate";
import type { EventLog } from "../kernel/event-log";
import type { Trust } from "../trust/trust";

export interface BudgetPolicy {
  perActionAutoApproveMinor: number;
  dailyCapMinor: number;
}

export interface SpendProposal {
  minor: number;
  evidenceTrust: Trust;
  token: Capability | null;
  now: number;
  policy: BudgetPolicy;
  /** Audit fields for a block; a default actor/version set is used when omitted. */
  blockAudit?: Omit<AuditFields, "approvalSource">;
}

export type SpendDecision = { decision: "auto" | "needs-owner" | "blocked"; reason?: string };

const REQUIRED_TRUST: Trust = "first-party-verified";

/** Spend gating (E11.3): gate first (trust ≥ first-party-verified, valid token, within cap), then the policy threshold. No money moves here. */
export function proposeSpend(log: EventLog, p: SpendProposal): SpendDecision {
  const request = { required: REQUIRED_TRUST, evidenceTrust: p.evidenceTrust, token: p.token, now: p.now, needMinor: p.minor };
  const preview = checkGate(request);
  if (!preview.ok) {
    const blockAudit: Omit<AuditFields, "approvalSource"> = p.blockAudit ?? {
      at: p.now,
      actor: "budget-policy",
      brainVersion: "n/a",
      modelVersion: "n/a",
      toolVersion: "n/a",
      inputsHash: "n/a",
      outputSummary: `spend of ${p.minor} minor units blocked: ${preview.reason}`,
      financialImpactMinor: 0,
      rollbackRef: null,
      sideEffectId: "pending",
    };
    const result = gateOrBlock(log, request, blockAudit);
    return { decision: "blocked", reason: result.ok ? "gate" : result.reason };
  }
  if (p.minor > p.policy.perActionAutoApproveMinor) {
    return { decision: "needs-owner", reason: `${p.minor} exceeds the per-action auto-approve threshold of ${p.policy.perActionAutoApproveMinor}` };
  }
  return { decision: "auto" };
}

