import type { AuditFields } from "../audit/audit";
import type { EventLog } from "../kernel/event-log";
import { moveMoney } from "./ledger";

/** Basis points; the three must sum to exactly 10000. */
export interface AllocationPolicy {
  reserveBps: number;
  payoutBps: number;
  reinvestBps: number;
}

/** Exact integer split: bps shares floored, the remainder goes to reserve so no cent is lost or created (E11.1). */
export function splitByBps(revenueMinor: number, policy: AllocationPolicy): { reserve: number; payout: number; reinvest: number } {
  if (!Number.isInteger(revenueMinor) || revenueMinor < 0) {
    throw new RangeError(`revenue must be a non-negative integer of minor units, got ${revenueMinor}`);
  }
  const total = policy.reserveBps + policy.payoutBps + policy.reinvestBps;
  if (total !== 10_000 || [policy.reserveBps, policy.payoutBps, policy.reinvestBps].some((bps) => !Number.isInteger(bps) || bps < 0)) {
    throw new RangeError(`allocation policy must sum to 10000 bps of non-negative integers, got ${total}`);
  }
  const payout = Math.floor((revenueMinor * policy.payoutBps) / 10_000);
  const reinvest = Math.floor((revenueMinor * policy.reinvestBps) / 10_000);
  const reserve = revenueMinor - payout - reinvest;
  return { reserve, payout, reinvest };
}

/** Move revenue into reserve/payout/reinvest — three audited MoneyMoved events; conservation holds by construction. */
export function allocateRevenue(log: EventLog, revenueMinor: number, policy: AllocationPolicy, audit: (name: string) => AuditFields): void {
  const split = splitByBps(revenueMinor, policy);
  for (const [name, minor] of Object.entries(split) as [keyof typeof split, number][]) {
    moveMoney(log, { from: "revenue", to: name, minor, reason: `allocation:${name}` }, audit(name));
  }
}

