import { createHash } from "node:crypto";
import type { Tainted } from "../trust/tainted";

/** A simulated external service: deterministic, offline, and honest about what it is. */
export interface SimService {
  readonly name: string;
}

export interface WebPage {
  status: number;
  body: string;
  contentHash: string;
}

/** Every fetched body is tainted web-scraped-untrusted at the source (E2). */
export interface WebService extends SimService {
  fetch(url: string): Tainted<WebPage>;
}

export function sha256Hex(text: string): string {
  return createHash("sha256").update(text).digest("hex");
}

import type { Prng } from "../../kernel/prng";
import { taint, type Tainted } from "../../trust/tainted";
import { sha256Hex, type WebPage, type WebService } from "../sim-service";

/** A fixture web served from an injected page map. Never touches the network; unknown URLs are 404. */
export function makeFixtureWeb(_prng: Prng, pages: Record<string, string>): WebService {
  return {
    name: "fixture-web",
    fetch(url: string): Tainted<WebPage> {
      const body = Object.hasOwn(pages, url) ? (pages[url] as string) : undefined;
      const text = body ?? "";
      return taint(
        { status: body === undefined ? 404 : 200, body: text, contentHash: sha256Hex(text) },
        "web-scraped-untrusted",
        url,
      );
    },
  };
}

