import { z } from "zod";
import type { Capability } from "../auth/capability";
import type { Clock } from "../kernel/clock";
import type { Trust } from "../trust/trust";

/** The hard seam between the factory and !Klein (V3.1): fixture and live adapters share this exact shape. */

export interface ProductSpec {
  id: string;
  targetUser: string;
  promise: string;
  mvpSlice: string;
  killCriteria: string;
  acceptance: string;
  evidenceTrust: Trust;
}

export interface BuildCard {
  id: string;
  title: string;
  dependsOn: string[];
  kind: "foundation" | "feature" | "test" | "presentation";
}

export interface BuildPlan {
  runId: string;
  cards: BuildCard[];
}

export type KleinEvent =
  | { t: "decomposed"; runId: string; cardCount: number }
  | { t: "card-started"; runId: string; cardId: string }
  | { t: "card-tests-run"; runId: string; cardId: string; passed: boolean; bundleRef: string }
  | { t: "card-merged"; runId: string; cardId: string }
  | { t: "card-blocked"; runId: string; cardId: string; reason: string }
  | { t: "run-finished"; runId: string; outcome: "success" | "partial" | "failure" };

/** zod at the boundary: every event crossing the seam is validated against this discriminated union. */
export const kleinEventSchema: z.ZodType<KleinEvent> = z.discriminatedUnion("t", [
  z.object({ t: z.literal("decomposed"), runId: z.string().min(1), cardCount: z.number().int().nonnegative() }),
  z.object({ t: z.literal("card-started"), runId: z.string().min(1), cardId: z.string().min(1) }),
  z.object({
    t: z.literal("card-tests-run"),
    runId: z.string().min(1),
    cardId: z.string().min(1),
    passed: z.boolean(),
    bundleRef: z.string().min(1),
  }),
  z.object({ t: z.literal("card-merged"), runId: z.string().min(1), cardId: z.string().min(1) }),
  z.object({ t: z.literal("card-blocked"), runId: z.string().min(1), cardId: z.string().min(1), reason: z.string() }),
  z.object({
    t: z.literal("run-finished"),
    runId: z.string().min(1),
    outcome: z.enum(["success", "partial", "failure"]),
  }),
]);

export interface ResultBranch {
  runId: string;
  branchName: string;
  cardIds: string[];
}

export interface EvidenceBundle {
  runId: string;
  testLogs: Record<string, { passed: boolean; raw: string }>;
}

export type KleinRunState = "pending" | "running" | "finished" | "cancelled";

export interface KleinAdapter {
  decompose(spec: ProductSpec, token: Capability): BuildPlan;
  run(plan: BuildPlan, token: Capability, clock: Clock): Iterable<KleinEvent>;
  status(runId: string): KleinRunState;
  artifacts(runId: string): { branches: ResultBranch[]; bundle: EvidenceBundle };
  cancel(runId: string): void;
}

import { describe, expect, it } from "vitest";
import { mintRoot } from "../../src/auth/capability";
import type { KleinEvent, ProductSpec } from "../../src/klein/adapter";
import { makeFixtureKleinAdapter } from "../../src/klein/fixture-adapter";
import { SAMPLE_SCRIPTS } from "../../src/klein/fixtures/build-plans";
import { makeManualClock } from "../../src/kernel/clock";
import { makePrngTree } from "../../src/kernel/prng";

const spec = (id: string): ProductSpec => ({ id, targetUser: "u", promise: "p", mvpSlice: "m", killCriteria: "k", acceptance: "npm test", evidenceTrust: "benchmarked" });
const token = () => mintRoot({ scope: "build", cap: 1, expiresAt: 1_000 }, makePrngTree(9));
const order = ["foundation", "feature", "test", "presentation"];

describe("fixture KleinAdapter", () => {
  it("a success script yields a well-ordered DAG, tests-run before every merge, and run-finished:success", () => {
    const adapter = makeFixtureKleinAdapter(makePrngTree(1), SAMPLE_SCRIPTS);
    const plan = adapter.decompose(spec("spec-success"), token());
    const ranks = plan.cards.map((c) => order.indexOf(c.kind));
    expect(ranks).toEqual([...ranks].sort((a, b) => a - b));
    expect(plan.cards.every((c) => c.dependsOn.every((dep) => plan.cards.findIndex((d) => d.id === dep) < plan.cards.findIndex((d) => d.id === c.id)))).toBe(true);
    expect(adapter.status(plan.runId)).toBe("pending");
    const events: KleinEvent[] = [...adapter.run(plan, token(), makeManualClock())];
    expect(events[0]?.t).toBe("decomposed");
    expect(events[events.length - 1]).toEqual({ t: "run-finished", runId: plan.runId, outcome: "success" });
    const tested = new Set<string>();
    for (const event of events) {
      if (event.t === "card-tests-run") tested.add(event.cardId);
      if (event.t === "card-merged") expect(tested.has(event.cardId)).toBe(true);
    }
    expect(adapter.status(plan.runId)).toBe("finished");
    const { branches, bundle } = adapter.artifacts(plan.runId);
    expect(branches[0]?.cardIds).toEqual(plan.cards.map((c) => c.id));
    expect(Object.values(bundle.testLogs).every((log) => log.passed && /PASS/u.test(log.raw))).toBe(true);
  });

  it("cancel makes status cancelled and stops the iterator; stall never finishes; fabricate lies; egress blocks", () => {
    const adapter = makeFixtureKleinAdapter(makePrngTree(2), SAMPLE_SCRIPTS);
    const plan = adapter.decompose(spec("spec-success"), token());
    const iterator = adapter.run(plan, token(), makeManualClock())[Symbol.iterator]();
    expect(iterator.next().value?.t).toBe("decomposed");
    adapter.cancel(plan.runId);
    expect(adapter.status(plan.runId)).toBe("cancelled");
    expect(iterator.next().done).toBe(true);

    const stalled = adapter.decompose(spec("spec-stall"), token());
    const stallEvents = [...adapter.run(stalled, token(), makeManualClock())];
    expect(stallEvents.some((e) => e.t === "run-finished")).toBe(false);
    expect(adapter.status(stalled.runId)).toBe("running");

    const fab = adapter.decompose(spec("spec-fabricated"), token());
    [...adapter.run(fab, token(), makeManualClock())];
    const log = adapter.artifacts(fab.runId).bundle.testLogs[`${fab.runId}-t1`];
    expect(log).toEqual({ passed: true, raw: "" });

    const egress = adapter.decompose(spec("spec-egress"), token());
    const egressEvents = [...adapter.run(egress, token(), makeManualClock())];
    expect(egressEvents.some((e) => e.t === "card-blocked" && e.reason === "host-egress-attempt")).toBe(true);
    expect(() => adapter.decompose(spec("unknown"), token())).toThrow(RangeError);
  });
});

import type { BuildPlan } from "../adapter";

/** A real-shaped DAG: foundation → features → test → presentation, deterministic ids (V3.3). */
export function scriptedPlan(runId: string): BuildPlan {
  return {
    runId,
    cards: [
      { id: `${runId}-f1`, title: "foundation: scaffold", dependsOn: [], kind: "foundation" },
      { id: `${runId}-x1`, title: "feature: core flow", dependsOn: [`${runId}-f1`], kind: "feature" },
      { id: `${runId}-x2`, title: "feature: second flow", dependsOn: [`${runId}-f1`], kind: "feature" },
      { id: `${runId}-t1`, title: "test: end-to-end", dependsOn: [`${runId}-x1`, `${runId}-x2`], kind: "test" },
      { id: `${runId}-p1`, title: "presentation: landing", dependsOn: [`${runId}-t1`], kind: "presentation" },
    ],
  };
}

export interface KleinScript {
  productSpecId: string;
  seed: number;
  plan: BuildPlan;
  outcome: "success" | "partial" | "failure";
  /** The bundle claims passed tests with empty/garbage raw logs — S26 must catch the lie. */
  fabricateTestLog?: boolean;
  /** Stop emitting after a few cards without run-finished — S27 stall detection must fire. */
  stall?: boolean;
  /** Emit a card-blocked with reason host-egress-attempt. */
  hostEgress?: boolean;
}

export const SAMPLE_SCRIPTS: readonly KleinScript[] = [
  { productSpecId: "spec-success", seed: 1, plan: scriptedPlan("run-success"), outcome: "success" },
  { productSpecId: "spec-partial", seed: 1, plan: scriptedPlan("run-partial"), outcome: "partial" },
  { productSpecId: "spec-failure", seed: 1, plan: scriptedPlan("run-failure"), outcome: "failure" },
  { productSpecId: "spec-fabricated", seed: 1, plan: scriptedPlan("run-fabricated"), outcome: "success", fabricateTestLog: true },
  { productSpecId: "spec-stall", seed: 1, plan: scriptedPlan("run-stall"), outcome: "success", stall: true },
  { productSpecId: "spec-egress", seed: 1, plan: scriptedPlan("run-egress"), outcome: "partial", hostEgress: true },
];

import type { Capability } from "../auth/capability";
import type { Clock } from "../kernel/clock";
import type { Prng } from "../kernel/prng";
import type { BuildPlan, EvidenceBundle, KleinAdapter, KleinEvent, KleinRunState, ProductSpec, ResultBranch } from "./adapter";
import type { KleinScript } from "./fixtures/build-plans";

export type { KleinScript } from "./fixtures/build-plans";

interface RunRecord {
  script: KleinScript;
  state: KleinRunState;
  merged: string[];
  testLogs: Record<string, { passed: boolean; raw: string }>;
}

/** Scripted, seeded, offline !Klein: the deterministic build engine every governance test drives (V3.3). */
export function makeFixtureKleinAdapter(prng: Prng, scripts: readonly KleinScript[]): KleinAdapter {
  const runs = new Map<string, RunRecord>();
  const scriptFor = (specId: string): KleinScript => {
    const script = scripts.find((entry) => entry.productSpecId === specId);
    if (!script) {
      throw new RangeError(`no script for product spec "${specId}"`);
    }
    return script;
  };
  const requireRun = (runId: string): RunRecord => {
    const run = runs.get(runId);
    if (!run) {
      throw new RangeError(`unknown run "${runId}"`);
    }
    return run;
  };
  const record = (run: RunRecord, cardId: string, passed: boolean): string => {
    const raw = run.script.fabricateTestLog ? "" : passed ? `PASS ${cardId}: 3 passed, 0 failed` : `FAIL ${cardId}: 1 failed, 2 passed`;
    run.testLogs[cardId] = { passed: run.script.fabricateTestLog ? true : passed, raw };
    return `${run.script.plan.runId}/${cardId}/${prng.nextId("bundle")}`;
  };

  return {
    decompose(spec: ProductSpec, token: Capability): BuildPlan {
      if (token.revoked) {
        throw new RangeError("decompose refused: capability is revoked");
      }
      const script = scriptFor(spec.id);
      const plan: BuildPlan = { runId: script.plan.runId, cards: script.plan.cards.map((card) => ({ ...card, dependsOn: [...card.dependsOn] })) };
      runs.set(plan.runId, { script, state: "pending", merged: [], testLogs: {} });
      return plan;
    },
    *run(plan: BuildPlan, token: Capability, clock: Clock): Iterable<KleinEvent> {
      const run = requireRun(plan.runId);
      // Read the state through a call so TypeScript does not narrow `run.state` to "running" after the assignment
      // below (cancel() mutates it from outside the generator).
      const isCancelled = (): boolean => run.state === "cancelled";
      if (token.revoked || isCancelled()) {
        return;
      }
      run.state = "running";
      void clock.now();
      yield { t: "decomposed", runId: plan.runId, cardCount: plan.cards.length };
      let egressUsed = false;
      for (const [index, card] of plan.cards.entries()) {
        if (isCancelled()) {
          return;
        }
        if (run.script.stall && index >= 2) {
          return; // stalls silently: no run-finished, ever
        }
        yield { t: "card-started", runId: plan.runId, cardId: card.id };
        if (run.script.hostEgress && !egressUsed && card.kind === "feature") {
          egressUsed = true;
          yield { t: "card-blocked", runId: plan.runId, cardId: card.id, reason: "host-egress-attempt" };
          continue;
        }
        const passed = run.script.outcome === "success" || (run.script.outcome === "partial" && card.kind !== "test");
        const bundleRef = record(run, card.id, passed);
        yield { t: "card-tests-run", runId: plan.runId, cardId: card.id, passed: run.testLogs[card.id]?.passed ?? passed, bundleRef };
        if (passed || run.script.fabricateTestLog) {
          run.merged.push(card.id);
          yield { t: "card-merged", runId: plan.runId, cardId: card.id };
        } else {
          yield { t: "card-blocked", runId: plan.runId, cardId: card.id, reason: "tests-failed" };
        }
      }
      run.state = "finished";
      yield { t: "run-finished", runId: plan.runId, outcome: run.script.outcome };
    },
    status: (runId) => runs.get(runId)?.state ?? "pending",
    artifacts(runId) {
      const run = requireRun(runId);
      const branches: ResultBranch[] = run.merged.length > 0 ? [{ runId, branchName: `nklein/${runId}`, cardIds: [...run.merged] }] : [];
      const bundle: EvidenceBundle = { runId, testLogs: Object.fromEntries(Object.entries(run.testLogs).map(([id, log]) => [id, { ...log }])) };
      return { branches, bundle };
    },
    cancel(runId) {
      const run = requireRun(runId);
      if (run.state !== "finished") {
        run.state = "cancelled";
      }
    },
  };
}

