import type { Capability } from "../auth/capability";
import type { Clock } from "../kernel/clock";
import type { KleinAdapter, KleinEvent, KleinRunState, ProductSpec } from "./adapter";

/** Contract specs: an adapter under test must be able to decompose these ids (the fixture's sample script ids). */
export const CONTRACT_SPEC_IDS: readonly string[] = ["spec-success", "spec-partial", "spec-failure"];

const TERMINAL: ReadonlySet<KleinRunState> = new Set(["finished", "cancelled"]);
const ORDER: readonly KleinRunState[] = ["pending", "running", "finished", "cancelled"];

function fail(message: string): never {
  throw new Error(`KleinAdapter contract violated: ${message}`);
}

function specFor(id: string): ProductSpec {
  return { id, targetUser: "contract", promise: "contract", mvpSlice: "contract", killCriteria: "contract", acceptance: "npm test", evidenceTrust: "benchmarked" };
}

/**
 * The reusable adapter-parity suite (V8.14): every fixture and live adapter must pass it. Throws on the first
 * violation with a precise message; the caller wraps it in its own test framework.
 */
export function runKleinAdapterContract(
  make: () => KleinAdapter,
  makeToken: () => Capability,
  makeClock: () => Clock,
  specIds: readonly string[] = CONTRACT_SPEC_IDS,
): void {
  for (const specId of specIds) {
    const adapter = make();
    const plan = adapter.decompose(specFor(specId), makeToken());
    const states: KleinRunState[] = [adapter.status(plan.runId)];
    const events: KleinEvent[] = [];
    const tested = new Set<string>();
    for (const event of adapter.run(plan, makeToken(), makeClock())) {
      events.push(event);
      states.push(adapter.status(plan.runId));
      if (event.runId !== plan.runId) fail(`event for run "${event.runId}" while running "${plan.runId}"`);
      if (event.t === "card-tests-run") tested.add(event.cardId);
      if (event.t === "card-merged" && !tested.has(event.cardId)) fail(`card-merged for ${event.cardId} without a prior card-tests-run (${specId})`);
    }
    states.push(adapter.status(plan.runId));
    // (a) ordering: decomposed first, run-finished last (and only last).
    if (events[0]?.t !== "decomposed") fail(`first event must be decomposed, got ${events[0]?.t} (${specId})`);
    const finishedAt = events.findIndex((e) => e.t === "run-finished");
    if (finishedAt !== events.length - 1) fail(`run-finished must be the last event (index ${finishedAt} of ${events.length}) (${specId})`);
    // (b) no ResultBranch card without a preceding tests-run.
    const { branches } = adapter.artifacts(plan.runId);
    for (const branch of branches) {
      for (const cardId of branch.cardIds) {
        if (!tested.has(cardId)) fail(`result branch ${branch.branchName} carries ${cardId} without a tests-run event (${specId})`);
      }
    }
    // (d) monotonic state machine: pending → running → finished|cancelled, never backward.
    let rank = -1;
    for (const state of states) {
      const next = ORDER.indexOf(state);
      if (next < rank) fail(`run state went backward: ${states.join(" → ")} (${specId})`);
      rank = Math.max(rank, next);
    }
    if (!TERMINAL.has(states[states.length - 1] as KleinRunState)) fail(`run did not reach a terminal state: ${states.join(" → ")} (${specId})`);
  }
  // (c) cancel always reaches a terminal state and stops the iterator.
  const adapter = make();
  const plan = adapter.decompose(specFor(specIds[0] ?? "spec-success"), makeToken());
  const iterator = adapter.run(plan, makeToken(), makeClock())[Symbol.iterator]();
  iterator.next();
  adapter.cancel(plan.runId);
  if (adapter.status(plan.runId) !== "cancelled") fail(`cancel did not reach cancelled (status ${adapter.status(plan.runId)})`);
  if (!iterator.next().done) fail("iterator kept emitting after cancel");
  adapter.cancel(plan.runId);
  if (adapter.status(plan.runId) !== "cancelled") fail("cancel is not idempotent");
}

import { describe, expect, it } from "vitest";
import { mintRoot } from "../../src/auth/capability";
import type { ProductSpec } from "../../src/klein/adapter";
import { makeFixtureKleinAdapter } from "../../src/klein/fixture-adapter";
import { SAMPLE_SCRIPTS, scriptedPlan } from "../../src/klein/fixtures/build-plans";
import { verifyBuildSuccess } from "../../src/klein/verify-build";
import { makeManualClock } from "../../src/kernel/clock";
import { makePrngTree } from "../../src/kernel/prng";

const spec = (id: string): ProductSpec => ({ id, targetUser: "u", promise: "p", mvpSlice: "m", killCriteria: "k", acceptance: "npm test", evidenceTrust: "benchmarked" });
const token = () => mintRoot({ scope: "build", cap: 1, expiresAt: 1_000 }, makePrngTree(3));

function bundleFor(specId: string) {
  const adapter = makeFixtureKleinAdapter(makePrngTree(1), SAMPLE_SCRIPTS);
  const plan = adapter.decompose(spec(specId), token());
  [...adapter.run(plan, token(), makeManualClock())];
  return { plan, bundle: adapter.artifacts(plan.runId).bundle };
}

describe("verifyBuildSuccess", () => {
  it("a real bundle with non-empty pass logs is trustworthy", () => {
    const { plan, bundle } = bundleFor("spec-success");
    expect(verifyBuildSuccess(bundle, plan)).toEqual({ trustworthy: true });
  });

  it("the fabricated-log fixture is rejected as fabricated-test-log; failed/missing logs and mismatches are named", () => {
    const fab = bundleFor("spec-fabricated");
    expect(verifyBuildSuccess(fab.bundle, fab.plan)).toEqual({ trustworthy: false, reason: "fabricated-test-log" });
    const failed = bundleFor("spec-failure");
    expect(verifyBuildSuccess(failed.bundle, failed.plan)).toEqual({ trustworthy: false, reason: "tests-failed" });
    const { plan } = bundleFor("spec-success");
    expect(verifyBuildSuccess({ runId: plan.runId, testLogs: {} }, plan)).toEqual({ trustworthy: false, reason: "missing-test-log" });
    expect(verifyBuildSuccess({ runId: "other", testLogs: {} }, plan)).toEqual({ trustworthy: false, reason: "bundle-run-mismatch" });
    const noTests = { ...scriptedPlan("run-x"), cards: scriptedPlan("run-x").cards.filter((c) => c.kind !== "test") };
    expect(verifyBuildSuccess({ runId: "run-x", testLogs: {} }, noTests)).toEqual({ trustworthy: false, reason: "no-test-card" });
  });
});

import type { BuildPlan, EvidenceBundle } from "./adapter";

const PASS_MARKER = /\bPASS\b|\b0 failed\b/u;

/**
 * Evidence-derived success only (V6.2 / V8.11): re-derive the verdict from per-card test logs; a top-level
 * "success" claim is never trusted. A claimed pass with an empty/garbage raw log is a fabricated test log.
 */
export function verifyBuildSuccess(bundle: EvidenceBundle, plan: BuildPlan): { trustworthy: boolean; reason?: string } {
  if (bundle.runId !== plan.runId) {
    return { trustworthy: false, reason: "bundle-run-mismatch" };
  }
  const testCards = plan.cards.filter((card) => card.kind === "test");
  if (testCards.length === 0) {
    return { trustworthy: false, reason: "no-test-card" };
  }
  for (const card of testCards) {
    const log = bundle.testLogs[card.id];
    if (!log) {
      return { trustworthy: false, reason: "missing-test-log" };
    }
    if (!log.passed) {
      return { trustworthy: false, reason: "tests-failed" };
    }
    if (log.raw.trim().length === 0 || !PASS_MARKER.test(log.raw)) {
      return { trustworthy: false, reason: "fabricated-test-log" };
    }
  }
  return { trustworthy: true };
}

import { describe, expect, it } from "vitest";
import { mintRoot } from "../../src/auth/capability";
import type { Brain } from "../../src/brain/registry";
import { makeEvidenceGraph } from "../../src/evidence/graph";
import { makeFixtureKleinAdapter } from "../../src/klein/fixture-adapter";
import { SAMPLE_SCRIPTS } from "../../src/klein/fixtures/build-plans";
import { commissionBuild } from "../../src/klein/governed-run";
import type { ProductSpec } from "../../src/klein/adapter";
import { makeManualClock } from "../../src/kernel/clock";
import { makeEventLog } from "../../src/kernel/event-log";
import { makePrngTree } from "../../src/kernel/prng";
import type { Trust } from "../../src/trust/trust";

const brain = (status: Brain["status"]): Brain => ({ version: "b1", status, transcript: { version: "t1", entries: {} }, competence: {} });
const spec = (id: string, evidenceTrust: Trust = "first-party-verified"): ProductSpec => ({ id, targetUser: "u", promise: "p", mvpSlice: "m", killCriteria: "k", acceptance: "npm test", evidenceTrust });
const grant = (scope = "klein.build", expiresAt = 1_000) => mintRoot({ scope, cap: 1, minorUnits: 10_000, expiresAt }, makePrngTree(5));

function groundedGraph(specId: string, leafTrust: Trust) {
  const g = makeEvidenceGraph(makePrngTree(1));
  const decision = g.addNode({ kind: "decision", trust: "owner-stated", label: specId });
  const fact = g.addNode({ kind: "fact", trust: leafTrust, label: "evidence" });
  g.link({ from: decision.id, to: fact.id, sign: "supports", confidence: 1, freshnessAt: 0 });
  return { g, specNodeId: decision.id };
}

function commission(specId: string, leafTrust: Trust, brainStatus: Brain["status"] = "active", token = grant()) {
  const log = makeEventLog(makePrngTree(2));
  const adapter = makeFixtureKleinAdapter(makePrngTree(3), SAMPLE_SCRIPTS);
  const { g, specNodeId } = groundedGraph(specId, leafTrust);
  const result = commissionBuild(log, adapter, g, { spec: spec(specId), brain: brain(brainStatus), budgetGrant: token, clock: makeManualClock(10), specNodeId });
  return { log, result };
}

describe("commissionBuild (the governed run envelope)", () => {
  it("grounded spec + active brain + valid grant + success script → shipped with branches and a run-start audit", () => {
    const { log, result } = commission("spec-success", "owner-stated");
    expect(result.status).toBe("shipped");
    if (result.status === "shipped") expect(result.branches[0]?.cardIds).toHaveLength(5);
    const types = log.all().map((e) => e.type);
    expect(types.slice(0, 3)).toEqual(["SideEffectCommitted", "KleinRunStarted", "AuditEvent"]);
    expect(log.all().find((e) => e.type === "AuditEvent")).toMatchObject({ actor: "KleinAdapter", approvalSource: "policy", rollbackRef: "nklein/run-success" });
    expect(types.filter((t) => t === "KleinEventLogged").length).toBeGreaterThan(5);
    expect(log.all().some((e) => e.type === "CommissionDeclined")).toBe(false);
  });

  it("a web-scraped spec → under-grounded with an AuthorityEscalationBlocked", () => {
    const { log, result } = commission("spec-success", "web-scraped-untrusted");
    expect(result).toEqual({ status: "declined", reason: "under-grounded" });
    expect(log.all().map((e) => e.type)).toEqual(["AuthorityEscalationBlocked", "AuditEvent", "CommissionDeclined"]);
    expect(log.all().some((e) => e.type === "KleinRunStarted")).toBe(false);
  });

  it("the fabricateTestLog script → fabricated-evidence; a stall → stalled", () => {
    expect(commission("spec-fabricated", "owner-stated").result).toEqual({ status: "declined", reason: "fabricated-evidence" });
    expect(commission("spec-stall", "owner-stated").result).toEqual({ status: "declined", reason: "stalled" });
  });

  it("commissioning from a candidate brain → not-active-brain; an expired or mis-scoped grant → over-budget", () => {
    expect(commission("spec-success", "owner-stated", "candidate").result).toEqual({ status: "declined", reason: "not-active-brain" });
    expect(commission("spec-success", "owner-stated", "active", grant("klein.build", 5)).result).toEqual({ status: "declined", reason: "over-budget" });
    expect(commission("spec-success", "owner-stated", "active", grant("ads")).result).toEqual({ status: "declined", reason: "over-budget" });
  });
});

import { z } from "zod";
import { emitAudit, sha256Hex } from "../audit/audit";
import { type Capability, isSubScope, isValid } from "../auth/capability";
import { commitOnce } from "../brain/idempotency";
import type { Brain } from "../brain/registry";
import type { EvidenceGraph } from "../evidence/graph";
import { traceGrounding } from "../evidence/grounding";
import type { Clock } from "../kernel/clock";
import type { EventLog } from "../kernel/event-log";
import { defineEvent } from "../kernel/events";
import { canonicalJson } from "../util/canonical-json";
import { type KleinAdapter, type KleinEvent, kleinEventSchema, type ProductSpec, type ResultBranch } from "./adapter";
import { verifyBuildSuccess } from "./verify-build";
import "../auth/gate"; // registers AuthorityEscalationBlocked

export interface CommissionRequest {
  spec: ProductSpec;
  brain: Brain;
  budgetGrant: Capability;
  clock: Clock;
  /** The spec's decision node on the evidence graph (defaults to a node whose id or label equals spec.id). */
  specNodeId?: string;
}

export type CommissionResult =
  | { status: "shipped"; branches: ResultBranch[] }
  | { status: "declined"; reason: "under-grounded" | "not-active-brain" | "over-budget" | "fabricated-evidence" | "stalled" | "cancelled" };

export const BUILD_SCOPE = "klein.build";
const REQUIRED_TRUST = "first-party-verified" as const;

export const kleinRunStartedEvent = defineEvent("KleinRunStarted", { specId: z.string(), runId: z.string(), brainVersion: z.string() });
export const kleinEventLoggedEvent = defineEvent("KleinEventLogged", { runId: z.string(), event: kleinEventSchema });
export const commissionDeclinedEvent = defineEvent("CommissionDeclined", {
  specId: z.string(),
  reason: z.enum(["under-grounded", "not-active-brain", "over-budget", "fabricated-evidence", "stalled", "cancelled"]),
});

function decline(log: EventLog, req: CommissionRequest, reason: Exclude<CommissionResult, { status: "shipped" }>["reason"]): CommissionResult {
  log.append({ type: "CommissionDeclined", at: req.clock.now(), specId: req.spec.id, reason });
  return { status: "declined", reason };
}

function findSpecNode(g: EvidenceGraph, req: CommissionRequest): string | null {
  if (req.specNodeId && g.node(req.specNodeId)) {
    return req.specNodeId;
  }
  return g.node(req.spec.id) ? req.spec.id : null;
}

/**
 * The full v2 governance envelope around one !Klein build (V3.2), in the non-negotiable order: active brain →
 * taint gate → budget token → audited run start → drive the run folding every KleinEvent into the log (stall
 * detection) → evidence-derived verification → PROPOSE branches. Applying branches is a separate audited step.
 */
export function commissionBuild(log: EventLog, adapter: KleinAdapter, g: EvidenceGraph, req: CommissionRequest): CommissionResult {
  const now = req.clock.now();
  // 1) active brain
  if (req.brain.status !== "active") {
    return decline(log, req, "not-active-brain");
  }
  // 2) taint gate: the spec must be grounded at >= first-party-verified
  const nodeId = findSpecNode(g, req);
  const grounding = nodeId ? traceGrounding(g, nodeId, REQUIRED_TRUST) : null;
  if (!grounding || !grounding.grounded) {
    const blocked = log.append({
      type: "AuthorityEscalationBlocked",
      at: now,
      reason: "under-trusted",
      required: REQUIRED_TRUST,
      evidenceTrust: grounding?.weakestLeafTrust ?? "adversarial-quarantined",
      tokenId: req.budgetGrant.id,
      needMinor: null,
    });
    emitAudit(log, {
      at: now,
      actor: "KleinAdapter",
      brainVersion: req.brain.version,
      modelVersion: req.brain.transcript.version,
      toolVersion: "klein/adapter",
      inputsHash: sha256Hex(canonicalJson(req.spec)),
      outputSummary: `commission of ${req.spec.id} blocked: under-grounded`,
      approvalSource: "none",
      financialImpactMinor: 0,
      rollbackRef: null,
      sideEffectId: blocked.id,
    });
    return decline(log, req, "under-grounded");
  }
  // 3) budget token
  if (!isValid(req.budgetGrant, now) || !isSubScope(BUILD_SCOPE, req.budgetGrant.scope)) {
    return decline(log, req, "over-budget");
  }
  // 4) run-start audit, idempotent across failover
  const plan = adapter.decompose(req.spec, req.budgetGrant);
  const started = commitOnce(
    log,
    `klein-run:${req.spec.id}:${plan.runId}`,
    () => log.append({ type: "KleinRunStarted", at: now, specId: req.spec.id, runId: plan.runId, brainVersion: req.brain.version }),
    now,
  );
  if (!started) {
    return decline(log, req, "cancelled");
  }
  emitAudit(log, {
    at: now,
    actor: "KleinAdapter",
    brainVersion: req.brain.version,
    modelVersion: req.brain.transcript.version,
    toolVersion: "klein/adapter",
    inputsHash: sha256Hex(canonicalJson(req.spec)),
    outputSummary: `run ${plan.runId} started for ${req.spec.id} (${plan.cards.length} cards)`,
    approvalSource: "policy",
    financialImpactMinor: 0,
    rollbackRef: `nklein/${plan.runId}`,
    sideEffectId: started.id,
  });
  // 5) drive the run, folding every event into the log
  let finished: KleinEvent | null = null;
  for (const event of adapter.run(plan, req.budgetGrant, req.clock)) {
    log.append({ type: "KleinEventLogged", at: req.clock.now(), runId: plan.runId, event });
    if (event.t === "run-finished") {
      finished = event;
    }
  }
  if (adapter.status(plan.runId) === "cancelled") {
    return decline(log, req, "cancelled");
  }
  if (!finished) {
    adapter.cancel(plan.runId);
    return decline(log, req, "stalled");
  }
  // 6) evidence-derived verification
  const { branches, bundle } = adapter.artifacts(plan.runId);
  const verdict = verifyBuildSuccess(bundle, plan);
  if (!verdict.trustworthy) {
    return decline(log, req, "fabricated-evidence");
  }
  // 7) propose only — applying a branch is a distinct audited, reversible step
  return { status: "shipped", branches };
}

import { describe, expect, it } from "vitest";
