import type { EvidenceGraph } from "../evidence/graph";
import type { Tainted } from "../trust/tainted";
import { type Trust, weakest } from "../trust/trust";

export interface Opportunity {
  id: string;
  source: string;
  signal: string;
  trust: Trust;
}

export interface Thesis {
  id: string;
  opportunityId: string;
  targetUser: string;
  promise: string;
  scoreBps: number;
  killCriteria: string;
}

/** Deterministic signal scoring (pure): keyword weights plus a bounded length term, in basis points. */
export function scoreSignalBps(signal: string): number {
  const text = signal.toLowerCase();
  const weights: [RegExp, number][] = [
    [/\b(hate|painful|frustrat|manual|tedious)\b/u, 2500],
    [/\b(pay|paying|subscription|budget|spend)\b/u, 2000],
    [/\b(every (week|month)|recurring|weekly|monthly)\b/u, 1500],
    [/\b(founder|owner|team|freelancer)s?\b/u, 1000],
  ];
  const keywordScore = weights.reduce((sum, [pattern, weight]) => sum + (pattern.test(text) ? weight : 0), 0);
  const lengthScore = Math.min(1000, Math.floor(text.length / 4) * 10);
  return Math.min(10_000, keywordScore + lengthScore);
}

/**
 * Score an opportunity into a thesis on the evidence graph: an opportunity node, a thesis decision node supported by
 * it, and the taint carried through — a web-scraped opportunity yields a web-scraped-untrusted thesis that can be
 * researched but not built until verified (V3.2, E2/E3).
 */
export function scoreOpportunity(g: EvidenceGraph, opp: Tainted<Opportunity>): Thesis {
  const trust = weakest(opp.trust, opp.value.trust);
  const opportunityNode = g.addNode({
    kind: "claim",
    trust,
    label: `opportunity: ${opp.value.signal}`,
    data: { opportunityId: opp.value.id, source: opp.value.source, provenance: opp.provenance },
  });
  const scoreBps = scoreSignalBps(opp.value.signal);
  const targetUser = `people who say "${opp.value.signal}" (${opp.value.source})`;
  const promise = `Remove the pain behind "${opp.value.signal}" with one small, verifiable product slice`;
  const killCriteria = "no verified demand signal (first-party-verified or better) within 30 simulated days";
  const thesisNode = g.addNode({
    kind: "thesis",
    trust,
    label: `thesis for ${opp.value.id}`,
    data: { scoreBps, targetUser, promise, killCriteria },
  });
  g.link({ from: thesisNode.id, to: opportunityNode.id, sign: "supports", confidence: scoreBps / 10_000, freshnessAt: 0 });
  return { id: thesisNode.id, opportunityId: opportunityNode.id, targetUser, promise, scoreBps, killCriteria };
}

import { describe, expect, it } from "vitest";
import { makeEvidenceGraph } from "../../src/evidence/graph";
