import { taint } from "../../src/trust/tainted";

function unverifiedThesis() {
  const g = makeEvidenceGraph(makePrngTree(1));
  const opp: Opportunity = { id: "o1", source: "forum", signal: "founders hate chasing invoices", trust: "web-scraped-untrusted" };
  return { g, thesis: scoreOpportunity(g, taint(opp, "web-scraped-untrusted", "https://forum.test/1")) };
}

describe("three-axis product spec (evidence / risk / authorization)", () => {
  it("(a) owner approval moves authorization only — the evidence grade does NOT move", () => {
    const log = makeEventLog(makePrngTree(2));
    const { g, thesis } = unverifiedThesis();
    const spec = hardenToProductSpec(log, g, thesis, { authorization: "owner-approved", grantedBy: "david", budgetMinor: 5_000 });
    expect(spec.authorization).toBe("owner-approved");
    expect(spec.evidenceGrade).toBe("unverified");
    expect(spec.contentRisk).toBe("untrusted");
    expect(log.all().map((e) => e.type)).toEqual(["AuthorizationGranted"]);
    expect(spec.value.evidenceTrust).toBe("web-scraped-untrusted");
  });

  it("(b) an experimental verification run raises the evidence grade with NO change to authorization", () => {
    const log = makeEventLog(makePrngTree(3));
    const { g, thesis } = unverifiedThesis();
    const spec = hardenToProductSpec(log, g, thesis, { authorization: "policy-delegated" });
    const verified = recordVerificationRun(log, spec, { grade: "experimentally-verified", evidence: "A/B run #7, 400 users" });
    expect(verified.evidenceGrade).toBe("experimentally-verified");
    expect(verified.authorization).toBe("policy-delegated");
    expect(log.all()[1]).toMatchObject({ type: "VerificationRunRecorded", from: "unverified", to: "experimentally-verified" });
    expect(recordVerificationRun(log, verified, { grade: "corroborated", evidence: "weaker" })).toBe(verified);
  });

  it("(c) owner-approved but unverified builds only through the experiment path and is labelled as such", () => {
    const log = makeEventLog(makePrngTree(4));
    const { g, thesis } = unverifiedThesis();
    const spec = hardenToProductSpec(log, g, thesis, { authorization: "owner-approved" });
    expect(buildPathFor(spec)).toBe("experiment");
    expect(situationLabel(spec)).toBe("EXPERIMENT (unverified, owner-approved)");
    expect(buildPathFor({ ...spec, authorization: "none" })).toBe("blocked");
    const verified = recordVerificationRun(log, spec, { grade: "directly-observed", evidence: "observed" });
    expect(buildPathFor(verified)).toBe("verified");
  });

  it("(d) laundering regression: no sequence of owner approvals produces experimentally-verified", () => {
    const log = makeEventLog(makePrngTree(5));
    const { g, thesis } = unverifiedThesis();
    let spec = hardenToProductSpec(log, g, thesis, { authorization: "owner-approved" });
    for (let i = 0; i < 50; i += 1) {
      spec = applyAuthorization(log, spec, { authorization: i % 2 === 0 ? "policy-delegated" : "owner-approved", grantedBy: `owner-${i}` });
      spec = hardenToProductSpec(log, g, thesis, { authorization: "owner-approved", grantedBy: "owner-again" });
    }
    expect(spec.evidenceGrade).toBe("unverified");
    expect(spec.evidenceGrade).not.toBe("experimentally-verified");
    expect(log.all().every((e) => e.type === "AuthorizationGranted")).toBe(true);
  });
});

import { z } from "zod";
import type { EvidenceGraph } from "../evidence/graph";
import type { EventLog } from "../kernel/event-log";
import { defineEvent } from "../kernel/events";
import type { ProductSpec } from "../klein/adapter";
import type { Trust } from "../trust/trust";
import type { Thesis } from "./opportunity";

/**
 * Three INDEPENDENT axes (corrected spec 2026-07-20): evidence is moved only by verification, content risk only by a
 * sanitizer/quarantine review, authorization only by an owner or policy. No transition on one axis moves another —
 * an owner can approve spending on a weak hypothesis but can never make it true (E2 / E11.5).
 */
export const EVIDENCE_GRADES = ["unverified", "corroborated", "directly-observed", "experimentally-verified"] as const;
export type EvidenceGrade = (typeof EVIDENCE_GRADES)[number];
export const CONTENT_RISKS = ["ordinary", "untrusted", "adversarial", "quarantined"] as const;
export type ContentRisk = (typeof CONTENT_RISKS)[number];
export const AUTHORIZATIONS = ["none", "policy-delegated", "owner-approved"] as const;
export type Authorization = (typeof AUTHORIZATIONS)[number];

export interface Graded<T> {
  readonly value: T;
  readonly evidenceGrade: EvidenceGrade;
  readonly contentRisk: ContentRisk;
  readonly authorization: Authorization;
}

export const authorizationGrantedEvent = defineEvent("AuthorizationGranted", {
  specId: z.string().min(1),
  authorization: z.enum(AUTHORIZATIONS),
  budgetMinor: z.number().int().nonnegative().nullable(),
  grantedBy: z.string().min(1),
});

export const verificationRunRecordedEvent = defineEvent("VerificationRunRecorded", {
  specId: z.string().min(1),
  from: z.enum(EVIDENCE_GRADES),
  to: z.enum(EVIDENCE_GRADES),
  evidence: z.string().min(1),
});

export function gradeRank(grade: EvidenceGrade): number {
  return EVIDENCE_GRADES.indexOf(grade);
}

/** A thesis's OWN evidence/risk axes, derived from the trust label it carries on the graph (never from who approved it). */
export function axesFromTrust(trust: Trust): { evidenceGrade: EvidenceGrade; contentRisk: ContentRisk } {
  switch (trust) {
    case "adversarial-quarantined":
      return { evidenceGrade: "unverified", contentRisk: "quarantined" };
    case "web-scraped-untrusted":
      return { evidenceGrade: "unverified", contentRisk: "untrusted" };
    case "model-generated":
    case "community-claim":
      return { evidenceGrade: "unverified", contentRisk: "ordinary" };
    case "benchmarked":
    case "owner-stated":
      return { evidenceGrade: "corroborated", contentRisk: "ordinary" };
    case "first-party-verified":
      return { evidenceGrade: "directly-observed", contentRisk: "ordinary" };
  }
}

/** Build a ProductSpec from the thesis, carry its axes forward unchanged, and apply the grant to AUTHORIZATION only. */
export function hardenToProductSpec(
  log: EventLog,
  g: EvidenceGraph,
  thesis: Thesis,
  grant: { authorization: Authorization; grantedBy?: string; budgetMinor?: number | null; now?: number },
): Graded<ProductSpec> {
  const node = g.node(thesis.id);
  if (!node) {
    throw new RangeError(`hardenToProductSpec: thesis ${thesis.id} is not on the evidence graph`);
  }
  const axes = axesFromTrust(node.trust);
  const spec: ProductSpec = {
    id: `spec-${thesis.id}`,
    targetUser: thesis.targetUser,
    promise: thesis.promise,
    mvpSlice: `one verifiable slice of: ${thesis.promise}`,
    killCriteria: thesis.killCriteria,
    acceptance: "npm test",
    evidenceTrust: node.trust,
  };
  log.append({
    type: "AuthorizationGranted",
    at: grant.now ?? 0,
    specId: spec.id,
    authorization: grant.authorization,
    budgetMinor: grant.budgetMinor ?? null,
    grantedBy: grant.grantedBy ?? "owner",
  });
  return Object.freeze({ value: spec, evidenceGrade: axes.evidenceGrade, contentRisk: axes.contentRisk, authorization: grant.authorization });
}

/** Owner/policy action: moves ONLY the authorization axis (and is recorded). */
export function applyAuthorization(log: EventLog, spec: Graded<ProductSpec>, grant: { authorization: Authorization; grantedBy?: string; budgetMinor?: number | null; now?: number }): Graded<ProductSpec> {
  log.append({ type: "AuthorizationGranted", at: grant.now ?? 0, specId: spec.value.id, authorization: grant.authorization, budgetMinor: grant.budgetMinor ?? null, grantedBy: grant.grantedBy ?? "owner" });
  return Object.freeze({ ...spec, authorization: grant.authorization });
}

/** A reproducible verification process: moves ONLY the evidence axis, and only upward; authorization untouched. */
export function recordVerificationRun(log: EventLog, spec: Graded<ProductSpec>, run: { grade: EvidenceGrade; evidence: string; now?: number }): Graded<ProductSpec> {
  if (gradeRank(run.grade) <= gradeRank(spec.evidenceGrade)) {
    return spec;
  }
  log.append({ type: "VerificationRunRecorded", at: run.now ?? 0, specId: spec.value.id, from: spec.evidenceGrade, to: run.grade, evidence: run.evidence });
  return Object.freeze({ ...spec, evidenceGrade: run.grade });
}

export type BuildPath = "verified" | "experiment" | "blocked";

/** The build gate needs BOTH authorization AND evidence that meets the stakes; low evidence may only build as a labelled experiment. */
export function buildPathFor(spec: Graded<ProductSpec>): BuildPath {
  if (spec.contentRisk === "quarantined" || spec.contentRisk === "adversarial" || spec.authorization === "none") {
    return "blocked";
  }
  return gradeRank(spec.evidenceGrade) >= gradeRank("directly-observed") ? "verified" : "experiment";
}

/** How the situation report must label this spec. */
export function situationLabel(spec: Graded<ProductSpec>): string {
  const path = buildPathFor(spec);
  return path === "experiment"
    ? `EXPERIMENT (${spec.evidenceGrade}, ${spec.authorization})`
    : path === "verified"
      ? `VERIFIED (${spec.evidenceGrade}, ${spec.authorization})`
      : `BLOCKED (${spec.contentRisk}, ${spec.authorization})`;
}

