import type { Capability } from "../auth/capability";
import type { Brain } from "../brain/registry";
import type { EvidenceGraph } from "../evidence/graph";
import type { Clock } from "../kernel/clock";
import type { EventLog } from "../kernel/event-log";
import type { KleinAdapter, ProductSpec } from "../klein/adapter";
import { type CommissionResult, commissionBuild } from "../klein/governed-run";
import type { Tainted } from "../trust/tainted";
import { meetsMin } from "../trust/trust";
import "../klein/governed-run"; // registers CommissionDeclined

/**
 * The factory uses !Klein as ONE tool (V14): assert the spec's own taint, then hand it to the governed envelope.
 * `specNodeId` names the spec's decision node on the evidence graph (the graph has no lookup by label).
 */
export function buildProduct(
  log: EventLog,
  adapter: KleinAdapter,
  g: EvidenceGraph,
  spec: Tainted<ProductSpec>,
  brain: Brain,
  grant: Capability,
  clock: Clock,
  specNodeId?: string,
): CommissionResult {
  if (!meetsMin(spec.trust, "first-party-verified")) {
    log.append({ type: "CommissionDeclined", at: clock.now(), specId: spec.value.id, reason: "under-grounded" });
    return { status: "declined", reason: "under-grounded" };
  }
  return commissionBuild(log, adapter, g, { spec: spec.value, brain, budgetGrant: grant, clock, ...(specNodeId ? { specNodeId } : {}) });
}

