import { z } from "zod";
import { type AuditFields, emitAudit } from "../audit/audit";
import type { EventLog } from "../kernel/event-log";
import { defineEvent, type DomainEvent } from "../kernel/events";
import type { Prng } from "../kernel/prng";
import { meetsMin, type Trust } from "../trust/trust";

export interface Ticket {
  id: string;
  from: string;
  subject: string;
  body: string;
  trust: Trust;
  /** Set when the ticket is quarantined/adversarial: it may be answered, never with credentials. */
  flagged: boolean;
}

export const supportTicketRepliedEvent = defineEvent("SupportTicketReplied", {
  ticketId: z.string().min(1),
  body: z.string(),
  credentialed: z.boolean(),
});

export interface SupportQueue {
  enqueue(ticket: Omit<Ticket, "id" | "flagged">): Ticket;
  list(): Ticket[];
  get(id: string): Ticket | undefined;
  /** An audited SupportTicketReplied side effect; a credentialed reply to a flagged ticket is refused (nothing appended). */
  reply(log: EventLog, ticketId: string, body: string, audit: AuditFields, options?: { credentialed?: boolean }): DomainEvent;
}

const CREDENTIAL_MIN_TRUST: Trust = "community-claim";

export function openSupportQueue(prng: Prng): SupportQueue {
  const tickets = new Map<string, Ticket>();
  return {
    enqueue(ticket) {
      const stored: Ticket = { ...ticket, id: prng.nextId("ticket"), flagged: !meetsMin(ticket.trust, CREDENTIAL_MIN_TRUST) };
      tickets.set(stored.id, stored);
      return { ...stored };
    },
    list: () => [...tickets.values()].map((t) => ({ ...t })),
    get: (id) => {
      const t = tickets.get(id);
      return t ? { ...t } : undefined;
    },
    reply(log, ticketId, body, audit, options) {
      const ticket = tickets.get(ticketId);
      if (!ticket) {
        throw new RangeError(`unknown ticket ${ticketId}`);
      }
      const credentialed = options?.credentialed === true;
      if (credentialed && ticket.flagged) {
        throw new RangeError(`credentialed reply refused: ticket ${ticketId} is ${ticket.trust} (phishing guard)`);
      }
      const replied = log.append({ type: "SupportTicketReplied", at: audit.at, ticketId, body, credentialed });
      emitAudit(log, { ...audit, sideEffectId: replied.id });
      return replied;
    },
  };
}

