import { spendApprovalRequestedEvent } from "./money-room";
import type { EventLog } from "../kernel/event-log";
import { authorityEscalationBlockedEvent } from "../auth/gate";

export interface ApprovalRow {
  id: string;
  impactMinor: number;
  reversible: boolean;
  objection: string | null;
  deadlineAt: number;
}

/** Fold blocked escalations + pending spend approvals into triage rows, sorted (deadline asc, impact desc, reversible asc). */
export function approvalQueueView(log: EventLog): ApprovalRow[] {
  const resolved = new Set<string>();
  for (const event of log.all()) {
    if (event.type === "SpendApprovalResolved") {
      resolved.add(String(event.proposalId));
    }
  }
  const rows: ApprovalRow[] = [];
  for (const event of log.all()) {
    if (event.type === "SpendApprovalRequested") {
      const requested = spendApprovalRequestedEvent.parse(event);
      if (resolved.has(requested.proposalId)) {
        continue;
      }
      rows.push({ id: requested.proposalId, impactMinor: requested.minor, reversible: requested.reversible, objection: requested.objection, deadlineAt: requested.deadlineAt });
    } else if (event.type === "AuthorityEscalationBlocked") {
      const blocked = authorityEscalationBlockedEvent.parse(event);
      rows.push({
        id: blocked.id,
        impactMinor: blocked.needMinor ?? 0,
        reversible: true,
        objection: `red team: authority escalation refused (${blocked.reason}; evidence ${blocked.evidenceTrust} vs required ${blocked.required})`,
        deadlineAt: blocked.at,
      });
    }
  }
  return rows.sort(
    (a, b) => a.deadlineAt - b.deadlineAt || b.impactMinor - a.impactMinor || Number(a.reversible) - Number(b.reversible),
  );
}

