import { z } from "zod";
import { type Capability, revoke } from "../auth/capability";
import type { EventLog } from "../kernel/event-log";
import { defineEvent } from "../kernel/events";
import type { KleinAdapter } from "../klein/adapter";

export const emergencyStopEngagedEvent = defineEvent("EmergencyStopEngaged", {
  capabilityIds: z.array(z.string()),
  cancelledRunIds: z.array(z.string()),
});

/**
 * Kill switch totality: revoke EVERY capability (so no gate can pass — capability soundness V8.8), record the stop,
 * and cancel every live !Klein run. Returns the revoked copies; the originals are frozen and untouched.
 */
export function emergencyStop(
  log: EventLog,
  caps: Capability[],
  options: { now?: number; adapter?: KleinAdapter; runIds?: readonly string[] } = {},
): Capability[] {
  const revoked = caps.map((cap) => revoke(cap));
  const cancelledRunIds: string[] = [];
  for (const runId of options.runIds ?? []) {
    if (options.adapter && options.adapter.status(runId) !== "finished") {
      options.adapter.cancel(runId);
      cancelledRunIds.push(runId);
    }
  }
  log.append({
    type: "EmergencyStopEngaged",
    at: options.now ?? 0,
    capabilityIds: revoked.map((cap) => cap.id),
    cancelledRunIds,
  });
  return revoked;
}

import type { BrainRegistry } from "../brain/registry";
import type { EventLog } from "../kernel/event-log";
import { brainRoomView } from "./brain-room";
import { moneyRoomView } from "./money-room";

export interface ReportLine {
  kind: "revenue" | "spend" | "shipped" | "approval" | "risk" | "brain" | "experiment";
  text: string;
  /** Drill-down reference: the log event id (or claim id) this line is derived from (V9). */
  evidenceNodeId: string;
  at: number;
}

export interface SituationReport {
  headline: { revenueDeltaMinor: number; spendDeltaMinor: number; productsShipped: number; approvalsPending: number; risksRaised: number };
  lines: ReportLine[];
}

const SPEND_ACCOUNTS = new Set(["payout", "reinvest", "spend", "ads"]);

/** The structured record that answers the audit (E11.6): every headline number and every line points at its evidence. */
export function situationReport(log: EventLog, reg: BrainRegistry): SituationReport {
  let revenueDeltaMinor = 0;
  let spendDeltaMinor = 0;
  let productsShipped = 0;
  let risksRaised = 0;
  const lines: ReportLine[] = [];
  for (const event of log.all()) {
    switch (event.type) {
      case "MoneyMoved": {
        const minor = Number(event.minor);
        const to = String(event.toAccount);
        const from = String(event.fromAccount);
        if (to === "revenue" && from === "world") {
          revenueDeltaMinor += minor;
          lines.push({ kind: "revenue", text: `received ${minor} minor units (${String(event.reason)})`, evidenceNodeId: event.id, at: event.at });
        } else if (SPEND_ACCOUNTS.has(to) || to === "world") {
          spendDeltaMinor += minor;
          lines.push({ kind: "spend", text: `${minor} minor units ${from} → ${to} (${String(event.reason)})`, evidenceNodeId: event.id, at: event.at });
        }
        break;
      }
      case "LaunchPublished":
        productsShipped += 1;
        lines.push({ kind: "shipped", text: `launched ${(event.branchNames as string[]).join(", ")}`, evidenceNodeId: event.id, at: event.at });
        break;
      case "AuthorityEscalationBlocked":
        risksRaised += 1;
        lines.push({ kind: "risk", text: `authority escalation blocked: ${String(event.reason)} (evidence ${String(event.evidenceTrust)} vs ${String(event.required)})`, evidenceNodeId: event.id, at: event.at });
        break;
      case "CommissionDeclined":
        lines.push({ kind: "risk", text: `build of ${String(event.specId)} declined: ${String(event.reason)}`, evidenceNodeId: event.id, at: event.at });
        break;
      case "VerificationRunRecorded":
        lines.push({ kind: "experiment", text: `${String(event.specId)} evidence ${String(event.from)} → ${String(event.to)}: ${String(event.evidence)}`, evidenceNodeId: event.id, at: event.at });
        break;
      case "BrainPromoted":
      case "BrainFailover":
        lines.push({ kind: "brain", text: `${event.type}: ${String(event.from)} → ${String(event.to)}`, evidenceNodeId: event.id, at: event.at });
        break;
      case "SpendApprovalRequested":
        lines.push({ kind: "approval", text: `approval pending: ${String(event.minor)} minor units for ${String(event.reason)}`, evidenceNodeId: event.id, at: event.at });
        break;
      default:
        break;
    }
  }
  const money = moneyRoomView(log);
  const brain = brainRoomView(log, reg);
  lines.push({ kind: "brain", text: `active brain ${brain.active.version}${brain.candidate ? `, candidate ${brain.candidate.version}` : ""}`, evidenceNodeId: `brain:${brain.active.version}`, at: log.all()[log.all().length - 1]?.at ?? 0 });
  return {
    headline: { revenueDeltaMinor, spendDeltaMinor, productsShipped, approvalsPending: money.pendingApprovals.length, risksRaised },
    lines,
  };
}

