  kleinScripts: [{ productSpecId: "spec-opp-1", seed: 1, plan: scriptedPlan("run-opp-1"), outcome: "success" }],
  brains: [
    { version: "v1", status: "active", transcript: { version: "t1", entries: {} }, competence: {} },
    { version: "v2", status: "standby", transcript: { version: "t2", entries: {} }, competence: {} },
  ],
  events: [
    { day: 1, kind: "discover", opportunity: { id: "opp-1", source: "forum", signal: "founders hate chasing invoices every month", trust: "web-scraped-untrusted" }, url: "https://forum.test/invoices" },
    { day: 1, kind: "verify", opportunityId: "opp-1", grade: "directly-observed", evidence: "12 founders paid a deposit", budgetMinor: 50_000 },
    { day: 1, kind: "build", opportunityId: "opp-1" },
    { day: 1, kind: "revenue", minor: 100_000, policy: { reserveBps: 5000, payoutBps: 3000, reinvestBps: 2000 } },
  ],
};

describe("runFactory", () => {
  it("a 1-day pack runs one product loop to shipped and produces allocated revenue, in order", () => {
    const { log, state } = runFactory(42, 1, pack);
    expect(state.products["opp-1"]?.result).toBe("shipped");
    const types = log.all().map((e) => e.type);
    expect(types[0]).toBe("DeterminismMarker");
    const order = ["AuthorizationGranted", "VerificationRunRecorded", "KleinRunStarted", "LaunchPublished", "MoneyMoved"];
    const positions = order.map((t) => types.indexOf(t));
    expect(positions.every((p) => p >= 0)).toBe(true);
    expect(positions).toEqual([...positions].sort((a, b) => a - b));
    expect(types.filter((t) => t === "LaunchPublished")).toHaveLength(1);
    expect(balances(log)).toMatchObject({ reserve: 50_000, payout: 30_000, reinvest: 20_000 });
    expect(state.clock.now()).toBe(24 * 60 * 60 * 1000);
  });

  it("is deterministic: the same seed and pack produce byte-identical logs; a different seed differs in ids only", () => {
    const a = runFactory(42, 1, pack).log.all();
    const b = runFactory(42, 1, pack).log.all();
    expect(JSON.stringify(a)).toBe(JSON.stringify(b));
    const c = runFactory(7, 1, pack).log.all();
    expect(c.map((e) => e.type)).toEqual(a.map((e) => e.type));
    expect(JSON.stringify(c)).not.toBe(JSON.stringify(a));
  });
});

