export const DAY_MS = 24 * 60 * 60 * 1000;

export type ScenarioStep =
  | { day: number; kind: "discover"; opportunity: Opportunity; url: string }
  | { day: number; kind: "verify"; opportunityId: string; grade: EvidenceGrade; evidence: string; budgetMinor: number }
  | { day: number; kind: "build"; opportunityId: string }
  | { day: number; kind: "revenue"; minor: number; policy: AllocationPolicy }
  | { day: number; kind: "stop" };

export interface ScenarioPack {
  pages: Record<string, string>;
  kleinScripts: KleinScript[];
  brains: Brain[];
  events: ScenarioStep[];
}

export interface ProductRecord {
  thesis: Thesis;
  spec: Graded<ProductSpec> | null;
  /** The build decision node, grounded only in verification evidence (the web-scraped thesis stays research). */
  decisionNodeId: string | null;
  result: "shipped" | "declined" | null;
  branches: ResultBranch[];
}

export interface FactoryState {
  clock: Clock & { advance(ms: number): void };
  prng: Prng;
  registry: BrainRegistry;
  adapter: KleinAdapter;
  graph: EvidenceGraph;
  web: WebService;
  grants: Capability[];
  products: Record<string, ProductRecord>;
  stopped: boolean;
  day: number;
}

function stepFor(state: FactoryState, log: EventLog, step: ScenarioStep): void {
  const now = state.clock.now();
  switch (step.kind) {
    case "discover": {
      const page = state.web.fetch(step.url);
      const opp = taint({ ...step.opportunity, signal: page.value.status === 200 ? step.opportunity.signal : "no signal" }, page.trust, page.provenance);
      const thesis = scoreOpportunity(state.graph, opp);
      state.products[step.opportunity.id] = { thesis, spec: null, decisionNodeId: null, result: null, branches: [] };
      return;
    }
    case "verify": {
      const product = state.products[step.opportunityId];
      if (!product) throw new RangeError(`verify: unknown opportunity ${step.opportunityId}`);
      let spec = hardenToProductSpec(log, state.graph, product.thesis, { authorization: "owner-approved", grantedBy: "owner", budgetMinor: step.budgetMinor, now });
      spec = recordVerificationRun(log, spec, { grade: step.grade, evidence: step.evidence, now });
      // The pack names the product; the fixture !Klein scripts are keyed by this id.
      spec = Object.freeze({ ...spec, value: { ...spec.value, id: `spec-${step.opportunityId}`, evidenceTrust: "first-party-verified" as const } });
      const decision = state.graph.addNode({ kind: "decision", trust: "owner-stated", label: `build ${spec.value.id}` });
      const evidence = state.graph.addNode({ kind: "fact", trust: "first-party-verified", label: step.evidence });
      state.graph.link({ from: decision.id, to: evidence.id, sign: "supports", confidence: 1, freshnessAt: now });
      product.spec = spec;
      product.decisionNodeId = decision.id;
      return;
    }
    case "build": {
      const product = state.products[step.opportunityId];
      if (!product?.spec || !product.decisionNodeId) throw new RangeError(`build: ${step.opportunityId} is not verified`);
      const grant = mintRoot({ scope: "klein.build", cap: 1, minorUnits: 100_000, expiresAt: now + 7 * DAY_MS }, state.prng);
      state.grants.push(grant);
      const result = buildProduct(
        log,
        state.adapter,
        state.graph,
        taint(product.spec.value, product.spec.value.evidenceTrust, "verification"),
        state.registry.active(),
        grant,
        state.clock,
        product.decisionNodeId,
      );
      product.result = result.status;
      if (result.status === "shipped") {
        product.branches = result.branches;
        launchProduct(log, result.branches, {
          at: now,
          actor: "factory",
          brainVersion: state.registry.active().version,
          modelVersion: state.registry.active().transcript.version,
          toolVersion: "klein/fixture",
          inputsHash: "n/a",
          outputSummary: `launched ${product.spec.value.id}`,
          approvalSource: "owner",
          financialImpactMinor: 0,
          rollbackRef: result.branches[0]?.branchName ?? null,
          sideEffectId: "pending",
        });
      }
      return;
    }
    case "revenue":
      receiveRevenue(log, step.minor, step.policy, now);
      return;
    case "stop":
      state.grants = emergencyStop(log, state.grants, { now, adapter: state.adapter, runIds: Object.values(state.products).map((p) => p.branches[0]?.runId ?? "").filter(Boolean) });
      state.stopped = true;
      return;
  }
}

/** Build the universe from seed + pack and run it day by day through the governed paths only (E1 / V1). */
export function runFactory(seed: number, days: number, pack: ScenarioPack, onDay?: (day: number, log: EventLog, state: FactoryState) => void): { log: EventLog; state: FactoryState } {
  const prng = makePrngTree(seed);
  const log = makeEventLog(prng.fork("log"));
  const clock = makeManualClock(0);
  const state: FactoryState = {
    clock,
    prng,
    registry: makeBrainRegistry(pack.brains, () => clock.now()),
    adapter: makeFixtureKleinAdapter(prng.fork("klein"), pack.kleinScripts),
    graph: makeEvidenceGraph(prng.fork("graph")),
    web: makeFixtureWeb(prng.fork("web"), pack.pages),
    grants: [],
    products: {},
    stopped: false,
    day: 0,
  };
  log.append({ type: "DeterminismMarker", at: 0, seed });
  for (let day = 1; day <= days; day += 1) {
    clock.advance(DAY_MS);
    state.day = day;
    for (const step of pack.events.filter((s) => s.day === day)) {
      stepFor(state, log, step);
    }
    onDay?.(day, log, state);
  }
  return { log, state };
}

