describe("assertAllInvariants — the grading harness", () => {
  it("a clean governed run passes every invariant", () => {
    const { log, result } = cleanLog();
    expect(result.status).toBe("shipped");
    expect(() => assertAllInvariants(log)).not.toThrow();
  });

  const violations: [string, (log: ReturnType<typeof makeEventLog>) => void][] = [
    ["E11.2 audit totality", (log) => log.append({ type: "MoneyMoved", at: 2, fromAccount: "a", toAccount: "b", minor: 5, reason: "x", sideEffectId: "y" })],
    ["E11.3 authority non-escalation", (log) => { const m = log.append({ type: "MoneyMoved", at: 2, fromAccount: "a", toAccount: "b", minor: 5, reason: "x", sideEffectId: "y" }); emitAudit(log, audit(m.id, "none")); }],
    ["E11.4 failover idempotency", (log) => { log.append({ type: "SideEffectCommitted", at: 2, effectKey: "pay-1" }); log.append({ type: "SideEffectCommitted", at: 3, effectKey: "pay-1" }); }],
    ["E11.5 taint monotonicity", (log) => log.append({ type: "VerificationRunRecorded", at: 2, specId: "s", from: "corroborated", to: "unverified", evidence: "e" })],
    ["E11.6 reviewability", (log) => { const m = log.append({ type: "MoneyMoved", at: 2, fromAccount: "a", toAccount: "b", minor: 5, reason: "x", sideEffectId: "y" }); emitAudit(log, { ...audit(m.id), inputsHash: " " }); }],
    ["V8.8 capability soundness", (log) => { log.append({ type: "EmergencyStopEngaged", at: 2, capabilityIds: [], cancelledRunIds: [] }); const r = log.append({ type: "KleinRunStarted", at: 3, specId: "s", runId: "r", brainVersion: "b" }); emitAudit(log, audit(r.id)); }],
    ["V8.11 evidence-derived success", (log) => log.append({ type: "KleinEventLogged", at: 2, runId: "ghost", event: { t: "run-finished", runId: "ghost", outcome: "success" } })],
  ];
  for (const [name, corrupt] of violations) {
    it(`a log violating ${name} fails with that named error`, () => {
      const { log } = cleanLog();
      corrupt(log);
      let caught: unknown;
      try { assertAllInvariants(log); } catch (error) { caught = error; }
      expect(caught).toBeInstanceOf(InvariantViolation);
      expect((caught as InvariantViolation).invariant).toBe(name);
    });
  }

  it("E11.1 conservation cannot be violated through the log by construction (double entry), and still runs first", () => {
    const { log } = cleanLog();
    log.append({ type: "MoneyMoved", at: 2, fromAccount: "a", toAccount: "a", minor: 5, reason: "self", sideEffectId: "y" });
    let caught: unknown;
    try { assertAllInvariants(log); } catch (error) { caught = error; }
    // The self-move nets to zero, so conservation holds; the unaudited movement is caught by the NEXT invariant.
    expect((caught as InvariantViolation).invariant).toBe("E11.2 audit totality");
  });

  it("a log without the determinism marker fails E11.7", () => {
    const log = makeEventLog(makePrngTree(9));
    let caught: unknown;
    try { assertAllInvariants(log); } catch (error) { caught = error; }
    expect((caught as InvariantViolation).invariant).toBe("E11.7 determinism marker");
  });
});

import { z } from "zod";
import { EXTERNAL_EFFECT_TYPES } from "../audit/side-effect";
import { gradeRank, verificationRunRecordedEvent } from "../factory/product-spec";
import { assertConservation } from "../finance/ledger";
import type { EventLog } from "../kernel/event-log";
import { defineEvent, type DomainEvent } from "../kernel/events";
import { kleinEventLoggedEvent } from "../klein/governed-run";

/** E11.7: a run declares its seed once, so the whole log is reproducible from it. */
export const determinismMarkerEvent = defineEvent("DeterminismMarker", { seed: z.number().int() });

export type InvariantName =
  | "E11.1 conservation"
  | "E11.2 audit totality"
  | "E11.3 authority non-escalation"
  | "E11.4 failover idempotency"
  | "E11.5 taint monotonicity"
  | "E11.6 reviewability"
  | "E11.7 determinism marker"
  | "V8.8 capability soundness"
  | "V8.11 evidence-derived success";

export class InvariantViolation extends Error {
  constructor(
    readonly invariant: InvariantName,
    detail: string,
  ) {
    super(`invariant ${invariant} violated: ${detail}`);
    this.name = "InvariantViolation";
  }
}

const check = (invariant: InvariantName, run: () => void): void => {
  try {
    run();
  } catch (error) {
    if (error instanceof InvariantViolation) throw error;
    throw new InvariantViolation(invariant, error instanceof Error ? error.message : String(error));
  }
};

/**
 * S27's run-start audit references KleinRunStarted, which S11's list predates; the battery classifies it external so
 * totality is judged over the whole slice (S11 should gain the entry in a follow-up).
 */
export const EXTERNAL_TYPES_IN_SLICE: ReadonlySet<string> = new Set([...EXTERNAL_EFFECT_TYPES, "KleinRunStarted"]);
const isExternal = (type: string): boolean => EXTERNAL_TYPES_IN_SLICE.has(type);

function assertAuditTotalityInSlice(events: readonly DomainEvent[]): void {
  const externalIds = new Set(events.filter((e) => isExternal(e.type)).map((e) => e.id));
  const counts = new Map<string, number>();
  for (const event of events) {
    if (event.type !== "AuditEvent") continue;
    const sideEffectId = String(event.sideEffectId);
    if (!externalIds.has(sideEffectId)) throw new Error(`audit without side effect: AuditEvent ${event.id} references "${sideEffectId}"`);
    counts.set(sideEffectId, (counts.get(sideEffectId) ?? 0) + 1);
  }
  for (const event of events) {
    if (!isExternal(event.type)) continue;
    const count = counts.get(event.id) ?? 0;
    if (count !== 1) throw new Error(`side effect without audit: ${event.type} ${event.id} has ${count} audit event(s), expected exactly 1`);
  }
}

function auditsBySideEffect(events: readonly DomainEvent[]): Map<string, DomainEvent[]> {
  const map = new Map<string, DomainEvent[]>();
  for (const event of events) {
    if (event.type === "AuditEvent") {
      const id = String(event.sideEffectId);
      map.set(id, [...(map.get(id) ?? []), event]);
    }
  }
  return map;
}

/** The grading harness (E11 / V8): every per-card assertion composed, in order, throwing the FIRST violated invariant by name. */
export function assertAllInvariants(log: EventLog): void {
  const events = log.all();
  check("E11.1 conservation", () => assertConservation(log));
  check("E11.2 audit totality", () => assertAuditTotalityInSlice(events));
  check("E11.3 authority non-escalation", () => {
    const audits = auditsBySideEffect(events);
    for (const event of events) {
      if (!isExternal(event.type) || event.type === "AuthorityEscalationBlocked") continue;
      const source = audits.get(event.id)?.[0]?.approvalSource;
      if (source !== "policy" && source !== "owner") {
        throw new Error(`${event.type} ${event.id} fired without a passing gate (approvalSource ${String(source)})`);
      }
    }
  });
  check("E11.4 failover idempotency", () => {
    const seen = new Set<string>();
    for (const event of events) {
      if (event.type !== "SideEffectCommitted") continue;
      const key = String(event.effectKey);
      if (seen.has(key)) throw new Error(`effectKey "${key}" committed twice`);
      seen.add(key);
    }
  });
  check("E11.5 taint monotonicity", () => {
    for (const event of events) {
      if (event.type !== "VerificationRunRecorded") continue;
      const run = verificationRunRecordedEvent.parse(event);
      if (gradeRank(run.to) <= gradeRank(run.from)) throw new Error(`evidence grade of ${run.specId} moved ${run.from} → ${run.to} without a raising verification`);
      if (!run.evidence.trim()) throw new Error(`evidence grade of ${run.specId} raised without recorded evidence`);
    }
  });
  check("E11.6 reviewability", () => {
    const audits = auditsBySideEffect(events);
    for (const event of events) {
      if (!isExternal(event.type)) continue;
      const audit = audits.get(event.id)?.[0];
      if (!audit || !String(audit.inputsHash).trim() || !String(audit.outputSummary).trim()) {
        throw new Error(`${event.type} ${event.id} has no reviewable audit record (inputsHash/outputSummary)`);
      }
    }
  });
  check("E11.7 determinism marker", () => {
    if (!events.some((event) => event.type === "DeterminismMarker")) throw new Error("no DeterminismMarker in the log");
  });
  check("V8.8 capability soundness", () => {
    let stopped = false;
    for (const event of events) {
      if (event.type === "EmergencyStopEngaged") stopped = true;
      if (stopped && event.type === "KleinRunStarted") throw new Error(`run ${String(event.runId)} started after an emergency stop`);
    }
  });
  check("V8.11 evidence-derived success", () => {
    const passedRuns = new Set<string>();
    for (const event of events) {
      if (event.type !== "KleinEventLogged") continue;
      const logged = kleinEventLoggedEvent.parse(event);
      if (logged.event.t === "card-tests-run" && logged.event.passed) passedRuns.add(logged.runId);
      if (logged.event.t === "run-finished" && logged.event.outcome === "success" && !passedRuns.has(logged.runId)) {
        throw new Error(`run ${logged.runId} claims success with no passing card-tests-run evidence`);
      }
    }
  });
}

import { describe, expect, it } from "vitest";
import { balances } from "../../src/finance/ledger";
import { snapshot } from "../../src/kernel/snapshot";
