describe("the flagship 30-day deterministic run", () => {
  it("invariants hold on all 30 days, two runs are byte-identical, and at least one product shipped with revenue allocated", () => {
    const daysChecked: number[] = [];
    const first = runFactory(123, 30, baseline, (day, log) => {
      expect(() => assertAllInvariants(log)).not.toThrow();
      daysChecked.push(day);
    });
    expect(daysChecked).toHaveLength(30);
    const second = runFactory(123, 30, baseline);
    expect(snapshot(first.log)).toBe(snapshot(second.log));
    expect(first.state.products["opp-invoices"]?.result).toBe("shipped");
    expect(first.log.all().filter((e) => e.type === "LaunchPublished")).toHaveLength(1);
    const b = balances(first.log);
    expect(b.reserve).toBe(450_000);
    expect(b.payout).toBe(270_000);
    expect(b.reinvest).toBe(180_000);
    expect(first.state.clock.now()).toBe(30 * 24 * 60 * 60 * 1000);
  });
});

