import { describe, expect, it } from "vitest";
import { assertConservation } from "../../src/finance/ledger";
import { makePrngTree } from "../../src/kernel/prng";
import { restore, snapshot } from "../../src/kernel/snapshot";
import { assertAllInvariants } from "../../src/sim/invariants";
import { baseline } from "../../src/sim/scenario-packs/baseline";
import { runFactory } from "../../src/sim/run-factory";
import { buildProduct } from "../../src/factory/build-step";
import { taint } from "../../src/trust/tainted";

describe("failover during a build (idempotency under chaos)", () => {
  it("the standby brain never re-fires a committed side effect; conservation and the invariants hold post-failover", () => {
    let checked = false;
    const { log } = runFactory(123, 6, baseline, (day, dayLog, state) => {
      if (day !== 6) return;
      // Day 6 ran the governed build. Kill the active brain, rebuild the world from a snapshot, and resume by
      // re-attempting the very same build on the restored log — the commitOnce guard must refuse a second fire.
      const snap = snapshot(dayLog);
      state.registry.failover(dayLog);
      expect(state.registry.active().version).toBe("v2");
      const restored = restore(snap, makePrngTree(999));
      const product = state.products["opp-invoices"];
      const grant = state.grants[0];
      if (!product?.spec || !product.decisionNodeId || !grant) throw new Error("day 6 should have built opp-invoices");
      const again = buildProduct(restored, state.adapter, state.graph, taint(product.spec.value, "first-party-verified", "verification"), state.registry.active(), grant, state.clock, product.decisionNodeId);
      expect(again).toEqual({ status: "declined", reason: "cancelled" });
      const types = restored.all().map((e) => e.type);
      expect(types.filter((t) => t === "KleinRunStarted")).toHaveLength(1);
      expect(types.filter((t) => t === "LaunchPublished")).toHaveLength(1);
      expect(restored.all().filter((e) => e.type === "SideEffectCommitted" && String(e.effectKey).startsWith("klein-run:spec-opp-invoices"))).toHaveLength(1);
      expect(() => assertConservation(restored)).not.toThrow();
      expect(() => assertAllInvariants(restored)).not.toThrow();
      checked = true;
    });
    expect(checked).toBe(true);
    expect(log.all().filter((e) => e.type === "BrainFailover")).toHaveLength(1);
    expect(() => assertAllInvariants(log)).not.toThrow();
  });
});

