/**
 * The ONLY file under src/** allowed to read the wall clock (the no-wallclock guard allowlists exactly this path).
 * Production wiring injects `systemClock`; tests and the simulation inject `makeManualClock` (S02). V1.
 */
export const systemClock: Clock = {
  now: () => Date.now(),
};

/**
 * Live-service stubs: a production adapter that is NOT configured (always, under `npm test`) must throw on any
 * use, so no test can accidentally reach a real network. Lives beside the wall clock because both form the
 * untested-in-CI seam this card owns (S44); a later card may move it to src/services/live/.
 */
export function makeLiveServiceStub<T extends object>(name: string): T {
  const refuse = (): never => {
    throw new Error(`live adapter not configured in tests: ${name}`);
  };
  return new Proxy({} as T, {
    get(_target, property) {
      if (property === "name") {
        return name;
      }
      return refuse;
    },
  });
}

import { describe, expect, it } from "vitest";
import { canonicalJson } from "../../src/util/canonical-json";

describe("canonicalJson", () => {
  it("is independent of key order, at every level", () => {
    expect(canonicalJson({ b: 1, a: 2 })).toBe(canonicalJson({ a: 2, b: 1 }));
    expect(canonicalJson({ z: { y: 1, x: [{ b: 1, a: 2 }] }, a: 0 })).toBe('{"a":0,"z":{"x":[{"a":2,"b":1}],"y":1}}');
  });

  it("preserves array order, drops undefined members, and has no whitespace", () => {
    expect(canonicalJson([3, 1, 2])).toBe("[3,1,2]");
    expect(canonicalJson({ a: undefined, b: null, c: "s" })).toBe('{"b":null,"c":"s"}');
    expect(canonicalJson("x")).toBe('"x"');
    expect(canonicalJson(undefined)).toBe("null");
    expect(canonicalJson({ a: [1, { b: [2, 3] }] })).not.toMatch(/\s/u);
  });
});

/** Canonical JSON: sorted object keys at every level, arrays preserved, no whitespace — every inputsHash uses it (E11.7 / E11.2). */
export function canonicalJson(v: unknown): string {
  if (Array.isArray(v)) {
    return `[${v.map((item) => canonicalJson(item)).join(",")}]`;
  }
  if (v !== null && typeof v === "object") {
    const entries = Object.entries(v as Record<string, unknown>)
      .filter(([, value]) => value !== undefined)
      .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
    return `{${entries.map(([key, value]) => `${JSON.stringify(key)}:${canonicalJson(value)}`).join(",")}}`;
  }
  const primitive = JSON.stringify(v);
  return primitive === undefined ? "null" : primitive;
}

