import { z } from "zod";
import type { EventLog } from "../kernel/event-log";
import { defineEvent, type DomainEvent } from "../kernel/events";

/** Knowledge-debt ledger: an unresolved debt that gates an action makes that action an honest refusal (E13 / V10). */
export interface DebtItem {
  id: string;
  topic: string;
  risk: "low" | "med" | "high";
  resolved: boolean;
  gatesAction: string | null;
}

export const DEBT_RAISED = "DebtRaised";
export const DEBT_RESOLVED = "DebtResolved";

export const debtRaisedEvent = defineEvent(DEBT_RAISED, {
  debtId: z.string().min(1),
  topic: z.string().min(1),
  risk: z.enum(["low", "med", "high"]),
  gatesAction: z.string().min(1).nullable(),
});

export const debtResolvedEvent = defineEvent(DEBT_RESOLVED, { debtId: z.string().min(1) });

/** Fold the ledger from the log: DebtRaised creates/updates an item, DebtResolved marks it resolved. */
export function foldDebts(events: readonly DomainEvent[]): Map<string, DebtItem> {
  const debts = new Map<string, DebtItem>();
  for (const event of events) {
    if (event.type === DEBT_RAISED) {
      const raised = debtRaisedEvent.parse(event);
      debts.set(raised.debtId, {
        id: raised.debtId,
        topic: raised.topic,
        risk: raised.risk,
        resolved: false,
        gatesAction: raised.gatesAction,
      });
    } else if (event.type === DEBT_RESOLVED) {
      const resolved = debtResolvedEvent.parse(event);
      const existing = debts.get(resolved.debtId);
      if (existing) {
        debts.set(resolved.debtId, { ...existing, resolved: true });
      }
    }
  }
  return debts;
}

/** Every debt currently open, in raise order. */
export function unresolvedDebts(log: EventLog): DebtItem[] {
  return [...foldDebts(log.all()).values()].filter((debt) => !debt.resolved);
}

/** True when any unresolved debt gates this action — the action must refuse honestly, not proceed. */
export function isActionBlocked(log: EventLog, action: string): boolean {
  return unresolvedDebts(log).some((debt) => debt.gatesAction === action);
}

