import type { KleinAdapter } from "../klein/adapter";
import type { Trust } from "../trust/trust";

/** !Klein is ONE governed tool among others, not the center (V14): every tool is a versioned, promotable entry. */
export interface ToolEntry {
  name: string;
  version: string;
  trust: Trust;
  capabilities: string[];
  state: "shadow" | "active" | "retired";
}

export interface ToolRegistry {
  register(entry: Omit<ToolEntry, "state"> & { state?: ToolEntry["state"] }): ToolEntry;
  list(): ToolEntry[];
  get(name: string): ToolEntry | undefined;
  /** shadow → active (mirrors brain promotion); anything else throws. */
  promote(name: string): ToolEntry;
  retire(name: string): ToolEntry;
}

export function makeToolRegistry(): ToolRegistry {
  const tools = new Map<string, ToolEntry>();
  const copy = (entry: ToolEntry): ToolEntry => ({ ...entry, capabilities: [...entry.capabilities] });
  const require = (name: string): ToolEntry => {
    const entry = tools.get(name);
    if (!entry) {
      throw new RangeError(`unknown tool "${name}"`);
    }
    return entry;
  };
  return {
    register(entry) {
      if (tools.has(entry.name)) {
        throw new RangeError(`tool "${entry.name}" is already registered (version ${tools.get(entry.name)?.version})`);
      }
      const stored: ToolEntry = { ...entry, capabilities: [...entry.capabilities], state: entry.state ?? "shadow" };
      tools.set(stored.name, stored);
      return copy(stored);
    },
    list: () => [...tools.values()].map(copy),
    get: (name) => {
      const entry = tools.get(name);
      return entry ? copy(entry) : undefined;
    },
    promote(name) {
      const entry = require(name);
      if (entry.state !== "shadow") {
        throw new RangeError(`only a shadow tool can be promoted; "${name}" is ${entry.state}`);
      }
      entry.state = "active";
      return copy(entry);
    },
    retire(name) {
      const entry = require(name);
      entry.state = "retired";
      return copy(entry);
    },
  };
}

/** Register a KleinAdapter as exactly one tool entry named "klein" whose capabilities are its five contract methods. */
export function registerKleinAdapter(registry: ToolRegistry, adapter: KleinAdapter, version: string, trust: Trust = "first-party-verified"): ToolEntry {
  const capabilities = (["decompose", "run", "status", "artifacts", "cancel"] as const).filter(
    (method) => typeof adapter[method] === "function",
  );
  return registry.register({ name: "klein", version, trust, capabilities: [...capabilities] });
}

