/** Wish-protocol interpretation record: a deterministic monkey's-paw guard for ambiguous instructions (E7). */
export interface WishInterpretation {
  operationalReading: string;
  rejectedReadings: string[];
  divergence: "low" | "high";
  needsConfirmation: boolean;
}

interface WishFixture {
  readonly matches: readonly string[];
  readonly operationalReading: string;
  readonly rejectedReadings: readonly string[];
  readonly divergence: "low" | "high";
}

/** Scripted readings for known-ambiguous instructions. Lookup is exact after normalisation — no NLP. */
const FIXTURES: readonly WishFixture[] = [
  {
    matches: ["cut costs", "reduce costs", "lower costs", "save money"],
    operationalReading:
      "Propose a ranked list of reversible cost reductions (unused subscriptions, idle compute, over-provisioned plans) for owner approval; keep every safety, backup and compliance spend untouched.",
    rejectedReadings: [
      "cancel customer-data backup",
      "stop paying for security monitoring",
      "lay off staff without owner approval",
      "cancel all paid services immediately",
    ],
    divergence: "high",
  },
  {
    matches: ["grow revenue", "increase revenue", "make more money"],
    operationalReading:
      "Propose ethical growth experiments (pricing tests, upsell offers, outreach to consenting leads) for owner approval within the current budget and legal boundaries.",
    rejectedReadings: ["charge customers without consent", "spam purchased lead lists", "raise prices on existing contracts unilaterally"],
    divergence: "high",
  },
  {
    matches: ["clean up the repo", "tidy the repository"],
    operationalReading: "Remove build artifacts and dead code behind a reviewable pull request; never delete history or uncommitted work.",
    rejectedReadings: ["force-push over main", "delete branches other people own"],
    divergence: "high",
  },
  {
    matches: ["run the tests", "run tests"],
    operationalReading: "Run the project's test command and report the results.",
    rejectedReadings: [],
    divergence: "low",
  },
];

function normalise(instruction: string): string {
  return instruction.trim().toLowerCase().replace(/[.!?]+$/u, "").replace(/\s+/gu, " ");
}

/** Deterministic interpretation: known ambiguous wishes get their scripted record; anything else is read literally at low divergence. */
export function interpretWish(instruction: string): WishInterpretation {
  const key = normalise(instruction);
  const fixture = FIXTURES.find((entry) => entry.matches.includes(key));
  if (!fixture) {
    return { operationalReading: instruction.trim(), rejectedReadings: [], divergence: "low", needsConfirmation: false };
  }
  return {
    operationalReading: fixture.operationalReading,
    rejectedReadings: [...fixture.rejectedReadings],
    divergence: fixture.divergence,
    needsConfirmation: fixture.divergence === "high",
  };
}

