import type { EventLog } from "../kernel/event-log";
import { eventSchemaFor } from "../kernel/events";

export type EffectClass = "internal" | "external";

/** The live registry: the slice-1 side effects plus every type breadth registers through `registerExternalEffectTypes`. */
const externalEffectRegistry = new Set<string>([
  "MoneyMoved",
  "ResultBranchApplied",
  "SupportTicketReplied",
  "LaunchPublished",
  "PluginInstalled",
  "AuthorityEscalationBlocked",
]);

/**
 * Every event type the factory treats as a REAL side effect (money moved, branch applied, message sent, publish,
 * escalation, …). A live read-only VIEW of the registry (S52 seam): registrations are visible to every reader.
 */
export const EXTERNAL_EFFECT_TYPES: ReadonlySet<string> = externalEffectRegistry;

/**
 * §M0 step 1 (S52): a new capability names its side effects here so E11.2 totality stays total. Idempotent; a type
 * that no card has defined with `defineEvent` is rejected — an unregistered event could never be appended anyway.
 */
export function registerExternalEffectTypes(types: readonly string[]): void {
  for (const type of types) {
    if (externalEffectRegistry.has(type)) continue;
    if (eventSchemaFor(type) === undefined) {
      throw new Error(`unknown event type: "${type}" — define it with defineEvent before registering it as a side effect`);
    }
    externalEffectRegistry.add(type);
  }
}

export function isExternalEffectType(type: string): boolean {
  return externalEffectRegistry.has(type);
}

export function classifyEffect(eventType: string): EffectClass {
  return EXTERNAL_EFFECT_TYPES.has(eventType) ? "external" : "internal";
}

/**
 * Totality of audit (E11.2): every external event has EXACTLY one AuditEvent whose sideEffectId is its id, and every
 * AuditEvent references an existing external event. Throws with a precise message on the first violation.
 */
export function assertAuditTotality(log: EventLog): void {
  const events = log.all();
  const externalIds = new Set(events.filter((e) => classifyEffect(e.type) === "external").map((e) => e.id));
  const auditsBySideEffect = new Map<string, number>();
  for (const event of events) {
    if (event.type !== "AuditEvent") {
      continue;
    }
    const sideEffectId = String(event.sideEffectId);
    if (!externalIds.has(sideEffectId)) {
      throw new Error(`audit without side effect: AuditEvent ${event.id} references "${sideEffectId}", which is not an external event`);
    }
    auditsBySideEffect.set(sideEffectId, (auditsBySideEffect.get(sideEffectId) ?? 0) + 1);
  }
  for (const event of events) {
    if (classifyEffect(event.type) !== "external") {
      continue;
    }
    const count = auditsBySideEffect.get(event.id) ?? 0;
    if (count !== 1) {
      throw new Error(`side effect without audit: ${event.type} ${event.id} has ${count} audit event(s), expected exactly 1`);
    }
  }
}

