import { BUILT_IN_INVARIANTS, InvariantViolation, assertAllInvariants, determinismMarkerEvent, listInvariants, registerInvariant } from "../../src/sim/invariants";
import { runFactory } from "../../src/sim/run-factory";
import { baseline } from "../../src/sim/scenario-packs/baseline";

describe("invariant registry (S53 seam for the S40 battery)", () => {
  it("lists the built-ins unchanged, then registrations in order, and rejects duplicates and empty names", () => {
    expect(listInvariants().slice(0, BUILT_IN_INVARIANTS.length)).toEqual([...BUILT_IN_INVARIANTS]);
    registerInvariant("registry-test: always passes", () => undefined);
    expect(listInvariants()).toContain("registry-test: always passes");
    expect(() => registerInvariant("registry-test: always passes", () => undefined)).toThrow(/already registered/u);
    expect(() => registerInvariant("E11.1 conservation", () => undefined)).toThrow(/already registered/u);
    expect(() => registerInvariant("  ", () => undefined)).toThrow(/empty/u);
  });

  it("a registered invariant that throws surfaces as an InvariantViolation naming it; a passing one keeps the baseline green", () => {
    const { log } = runFactory(53, 3, baseline);
    expect(() => assertAllInvariants(log)).not.toThrow();
    registerInvariant("registry-test: no more than 10 000 events", (l) => {
      if (l.all().length > 10_000) throw new Error("too many events");
    });
    expect(() => assertAllInvariants(log)).not.toThrow();
    let armed = true;
    registerInvariant("registry-test: armed trap", (l) => {
      if (armed && l.all().some((event) => event.type === "DeterminismMarker")) throw new Error("marker present");
