  });

  it("an InvariantViolation thrown by a registered check is re-thrown as is", () => {
    const log = makeEventLog(makePrngTree(1));
    log.append({ type: "DeterminismMarker", at: 0, seed: 1 });
    determinismMarkerEvent.parse(log.all()[0]);
    registerInvariant("registry-test: rethrows", () => {
      throw new InvariantViolation("registry-test: inner", "inner detail");
    });
    expect(() => assertAllInvariants(log)).toThrow(/inner detail/u);
  });
});

import { z } from "zod";

/** E4: the brain is assumed small and fallible; competence is tracked per skill and recalibrated from outcomes. */
export const SKILLS = [
  "coding",
  "planning",
  "long-context",
  "tool-call-format",
  "financial-reasoning",
  "marketing-copy",
  "adversarial-resistance",
] as const;

export type Skill = (typeof SKILLS)[number];

export type Stakes = "low" | "medium" | "high";

export interface CompetenceProfile {
  brainId: string;
  /** Integer scores 0–100 per skill. */
  scores: Record<Skill, number>;
  /** Number of recalibration samples folded into each score. */
  samples: Record<Skill, number>;
  calibratedAt: number;
}

const scoreSchema = z.number().int().min(0).max(100);
const skillRecord = <T extends z.ZodTypeAny>(value: T) =>
  z.object(Object.fromEntries(SKILLS.map((skill) => [skill, value])) as Record<Skill, T>).strict();

export const competenceProfileSchema: z.ZodType<CompetenceProfile> = z
  .object({
    brainId: z.string().min(1),
    scores: skillRecord(scoreSchema),
    samples: skillRecord(z.number().int().nonnegative()),
    calibratedAt: z.number().int(),
  })
  .strict();

const DEFAULT_SCORE = 50;
/** Each outcome moves the score 20% of the way toward its target (integer EMA, half away from zero). */
const EMA_BPS = 2000;

function roundHalfAwayFromZero(value: number): number {
  return value < 0 ? -Math.round(-value) : Math.round(value);
}

/** A profile seeded from a benchmark harness (missing skills default to 50). Frozen. */
export function seedProfile(brainId: string, scores: Partial<Record<Skill, number>>, now: number): CompetenceProfile {
  const full = Object.fromEntries(SKILLS.map((skill) => [skill, scores[skill] ?? DEFAULT_SCORE])) as Record<Skill, number>;
  const samples = Object.fromEntries(SKILLS.map((skill) => [skill, 0])) as Record<Skill, number>;
  return Object.freeze(competenceProfileSchema.parse({ brainId, scores: full, samples, calibratedAt: now }));
}

/** Fold one live outcome into the skill's score: success pulls toward 100, failure toward 0; always within 0–100. Returns a new profile. */
export function recalibrate(profile: CompetenceProfile, skill: Skill, outcome: "success" | "failure", now: number): CompetenceProfile {
  const target = outcome === "success" ? 100 : 0;
  const current = profile.scores[skill];
  const moved = current + roundHalfAwayFromZero(((target - current) * EMA_BPS) / 10_000);
  const clamped = Math.min(100, Math.max(0, moved));
  return Object.freeze(
    competenceProfileSchema.parse({
      brainId: profile.brainId,
      scores: { ...profile.scores, [skill]: clamped },
      samples: { ...profile.samples, [skill]: profile.samples[skill] + 1 },
      calibratedAt: now,
    }),
  );
}

/** In-competence test used by the router: the brain's score for the skill meets the requirement. */
export function meetsRequirement(profile: CompetenceProfile, skill: Skill, requiredScore: number): boolean {
  return profile.scores[skill] >= requiredScore;
}

import { describe, expect, it } from "vitest";
import { SKILLS, competenceProfileSchema, meetsRequirement, recalibrate, seedProfile } from "../../src/brain/competence";

describe("competence profile (E4)", () => {
  it("seeds missing skills at 50, freezes the profile, and the schema rejects out-of-range or unknown skills", () => {
    const profile = seedProfile("brain-a", { coding: 80 }, 5);
    expect(profile.scores.coding).toBe(80);
    expect(profile.scores.planning).toBe(50);
    expect(Object.keys(profile.scores)).toEqual([...SKILLS]);
    expect(Object.isFrozen(profile)).toBe(true);
    expect(() => competenceProfileSchema.parse({ ...profile, scores: { ...profile.scores, coding: 101 } })).toThrow();
    expect(() => competenceProfileSchema.parse({ ...profile, scores: { ...profile.scores, juggling: 10 } })).toThrow();
    expect(meetsRequirement(profile, "coding", 80)).toBe(true);
    expect(meetsRequirement(profile, "coding", 81)).toBe(false);
  });

  it("recalibration moves 20% toward the outcome, counts samples, never leaves 0–100, and is deterministic", () => {
    let profile = seedProfile("brain-a", { coding: 50 }, 0);
    profile = recalibrate(profile, "coding", "success", 1);
    expect(profile.scores.coding).toBe(60);
    expect(profile.samples.coding).toBe(1);
    expect(profile.calibratedAt).toBe(1);
    for (let i = 0; i < 40; i += 1) profile = recalibrate(profile, "coding", "success", i + 2);
    expect(profile.scores.coding).toBeLessThanOrEqual(100);
    expect(profile.scores.coding).toBeGreaterThanOrEqual(97);
    for (let i = 0; i < 60; i += 1) profile = recalibrate(profile, "coding", "failure", i + 50);
    expect(profile.scores.coding).toBeGreaterThanOrEqual(0);
    expect(profile.scores.coding).toBeLessThanOrEqual(3);
    expect(profile.samples.coding).toBe(101);
    const a = recalibrate(seedProfile("b", { planning: 33 }, 0), "planning", "failure", 1);
    const b = recalibrate(seedProfile("b", { planning: 33 }, 0), "planning", "failure", 1);
    expect(a).toEqual(b);
    expect(a.scores.planning).toBe(26);
  });
});

import { type CompetenceProfile, type Skill, type Stakes, meetsRequirement } from "./competence";

/** E4/V4: where a unit of work goes — the local brain, the candidate, a decomposition, a governed frontier burst, or the owner. */
export type Route = "local" | "candidate" | "decompose" | "burst" | "escalate";

export interface RouteRequest {
  skill: Skill;
  requiredScore: number;
  stakes: Stakes;
  active: CompetenceProfile;
  candidate?: CompetenceProfile;
  burstAllowed: boolean;
  /** False when the context carries private/user data that may not leave the residency boundary — a hard stop for bursts. */
  residencyOk: boolean;
  budgetOk: boolean;
  decomposable: boolean;
}

export interface RouteDecision {
  route: Route;
  reason: string;
}

/** High-stakes work needs a margin above the bare requirement before the local brain may keep it. */
export const HIGH_STAKES_MARGIN = 10;

/** Pure routing: competence × stakes × residency × budget. Never bursts without residency; never keeps high stakes on a thin margin. */
export function routeWork(req: RouteRequest): RouteDecision {
  const score = req.active.scores[req.skill];
  const inCompetence = meetsRequirement(req.active, req.skill, req.requiredScore);
  if (inCompetence) {
    if (req.stakes !== "high") {
      return { route: "local", reason: `in-competence (${score} ≥ ${req.requiredScore}) at ${req.stakes} stakes` };
    }
    if (score - req.requiredScore >= HIGH_STAKES_MARGIN) {
      return { route: "local", reason: `in-competence with margin ${score - req.requiredScore} ≥ ${HIGH_STAKES_MARGIN} at high stakes` };
    }
    return { route: "escalate", reason: `high stakes on a thin margin (${score - req.requiredScore} < ${HIGH_STAKES_MARGIN})` };
  }
  if (req.candidate && meetsRequirement(req.candidate, req.skill, req.requiredScore)) {
    return { route: "candidate", reason: `candidate brain meets ${req.requiredScore} for ${req.skill}` };
  }
  if (req.decomposable) {
    return { route: "decompose", reason: `out-of-competence (${score} < ${req.requiredScore}); decomposing into in-competence subtasks` };
  }
  if (!req.residencyOk) {
    return { route: "escalate", reason: "burst forbidden: context would leave the residency boundary" };
  }
  if (req.burstAllowed && req.budgetOk) {
    return { route: "burst", reason: "out-of-competence, not decomposable; policy-gated frontier burst within budget" };
  }
  return { route: "escalate", reason: req.burstAllowed ? "burst budget exhausted" : "burst not allowed by policy" };
}

