import { z } from "zod";
import type { EventLog } from "../kernel/event-log";
import { defineEvent } from "../kernel/events";

/** V7 #3 / ASI02: a role that keeps failing the same way, or burns brain-time without progress, is cut off — once, loudly. */
export const circuitBreakerTrippedEvent = defineEvent("CircuitBreakerTripped", {
  roleId: z.string().min(1),
  attempts: z.number().int().nonnegative(),
  brainTimeMs: z.number().int().nonnegative(),
  reason: z.enum(["same-error-loop", "brain-time-cap"]),
});

export interface BreakerPolicy {
  maxAttempts: number;
  maxBrainTimeMs: number;
}

export interface Attempt {
  ok: boolean;
  brainTimeMs: number;
  /** A stable key for the failure shape (null for a success). */
  errorKey: string | null;
}

export interface CircuitBreaker {
  record(log: EventLog, roleId: string, attempt: Attempt, now: number): "ok" | "tripped";
  isTripped(roleId: string): boolean;
}

interface RoleState {
  consecutiveSameError: number;
  lastErrorKey: string | null;
  brainTimeMs: number;
  tripped: boolean;
}

export function makeBreaker(policy: BreakerPolicy): CircuitBreaker {
  const roles = new Map<string, RoleState>();
  const stateOf = (roleId: string): RoleState => {
    const existing = roles.get(roleId);
    if (existing) return existing;
    const fresh: RoleState = { consecutiveSameError: 0, lastErrorKey: null, brainTimeMs: 0, tripped: false };
    roles.set(roleId, fresh);
    return fresh;
  };
  return {
    record(log, roleId, attempt, now) {
      const state = stateOf(roleId);
      if (state.tripped) return "tripped";
      state.brainTimeMs += Math.max(0, attempt.brainTimeMs);
      if (attempt.ok) {
        state.consecutiveSameError = 0;
        state.lastErrorKey = null;
        state.brainTimeMs = 0;
        return "ok";
      }
      state.consecutiveSameError = attempt.errorKey !== null && attempt.errorKey === state.lastErrorKey ? state.consecutiveSameError + 1 : 1;
      state.lastErrorKey = attempt.errorKey;
      const reason = state.consecutiveSameError >= policy.maxAttempts ? "same-error-loop" : state.brainTimeMs > policy.maxBrainTimeMs ? "brain-time-cap" : null;
      if (reason === null) return "ok";
      state.tripped = true;
      log.append({ type: "CircuitBreakerTripped", at: now, roleId, attempts: state.consecutiveSameError, brainTimeMs: state.brainTimeMs, reason });
      return "tripped";
    },
    isTripped: (roleId) => roles.get(roleId)?.tripped ?? false,
  };
}

