/** E4/V4: every routing decision is on the log; a frontier burst is a REAL side effect (data leaves the machine) and is audited. */
export const workRoutedEvent = defineEvent("WorkRouted", {
  workId: z.string().min(1),
  route: z.enum(["local", "candidate", "decompose", "burst", "escalate"]),
  skill: z.enum(SKILLS),
  stakes: z.enum(["low", "medium", "high"]),
  reason: z.string().min(1),
});

export const frontierBurstRequestedEvent = defineEvent("FrontierBurstRequested", {
  workId: z.string().min(1),
  provider: z.string().min(1),
  tokensCap: z.number().int().positive(),
});

registerExternalEffectTypes(["FrontierBurstRequested"]);

export interface BurstPolicy {
  provider: string;
  tokensCap: number;
}

export function routeAndRecord(log: EventLog, req: RouteRequest & { workId: string }, burst: BurstPolicy, audit: Omit<AuditFields, "sideEffectId" | "approvalSource">): Route {
  const decision = routeWork(req);
  log.append({ type: "WorkRouted", at: audit.at, workId: req.workId, route: decision.route, skill: req.skill, stakes: req.stakes, reason: decision.reason });
  if (decision.route === "burst") {
    commitOnce(
      log,
      `burst:${req.workId}`,
      () => {
        const requested = log.append({ type: "FrontierBurstRequested", at: audit.at, workId: req.workId, provider: burst.provider, tokensCap: burst.tokensCap });
        emitAudit(log, { ...audit, approvalSource: "policy", sideEffectId: requested.id });
        return requested;
      },
      audit.at,
    );
  }
  return decision.route;
}

