import { z } from "zod";
import type { EventLog } from "../kernel/event-log";
import { defineEvent } from "../kernel/events";

/** E5: every prediction is a falsifiable forecast with a resolution day and criteria; the simulation resolves it. */
export interface Forecast {
  id: string;
  category: string;
  claim: string;
  /** Probability in basis points (0–10000). */
  probabilityBps: number;
  resolveAtDay: number;
  criteria: string;
}

export const forecastSchema: z.ZodType<Forecast> = z
  .object({
    id: z.string().min(1),
    category: z.string().min(1),
    claim: z.string().min(1),
    probabilityBps: z.number().int().min(0).max(10_000),
    resolveAtDay: z.number().int().nonnegative(),
    criteria: z.string().min(1),
  })
  .strict();

export const forecastRecordedEvent = defineEvent("ForecastRecorded", {
  forecastId: z.string().min(1),
  category: z.string().min(1),
  claim: z.string().min(1),
  probabilityBps: z.number().int().min(0).max(10_000),
  resolveAtDay: z.number().int().nonnegative(),
  criteria: z.string().min(1),
});

export const forecastResolvedEvent = defineEvent("ForecastResolved", {
  forecastId: z.string().min(1),
  outcome: z.boolean(),
  resolvedDay: z.number().int().nonnegative(),
});

export interface CalibrationSummary {
  n: number;
  /** Mean squared error of the probabilities, in basis points (0 = perfect, 10000 = always certain and always wrong). */
  brierBps: number;
  /** mean(probability) − hit rate, in bps: positive = over-confident, negative = under-confident. */
  overconfidenceBps: number;
}

const roundHalfUp = (numerator: number, denominator: number): number => Math.floor((numerator * 2 + denominator) / (2 * denominator));

/** Brier score in bps with integer arithmetic only (multiply first, divide last). */
export function brierScoreBps(pairs: readonly { probabilityBps: number; outcome: boolean }[]): number {
  if (pairs.length === 0) return 0;
  let sum = 0;
  for (const pair of pairs) {
    const delta = pair.probabilityBps - (pair.outcome ? 10_000 : 0);
    sum += delta * delta;
  }
  return roundHalfUp(sum, pairs.length * 10_000);
}

/** Fold every resolved forecast by category. Unresolved forecasts are ignored. */
export function calibrationByCategory(log: EventLog): Map<string, CalibrationSummary> {
  const recorded = new Map<string, { category: string; probabilityBps: number }>();
  const pairsByCategory = new Map<string, { probabilityBps: number; outcome: boolean }[]>();
  for (const event of log.all()) {
    if (event.type === "ForecastRecorded") {
      const f = forecastRecordedEvent.parse(event);
      recorded.set(f.forecastId, { category: f.category, probabilityBps: f.probabilityBps });
    } else if (event.type === "ForecastResolved") {
      const r = forecastResolvedEvent.parse(event);
      const f = recorded.get(r.forecastId);
      if (!f) continue;
      const list = pairsByCategory.get(f.category) ?? [];
      list.push({ probabilityBps: f.probabilityBps, outcome: r.outcome });
      pairsByCategory.set(f.category, list);
    }
  }
  const summary = new Map<string, CalibrationSummary>();
  for (const [category, pairs] of pairsByCategory) {
    const meanProbabilityBps = roundHalfUp(pairs.reduce((s, p) => s + p.probabilityBps, 0), pairs.length);
    const hitRateBps = roundHalfUp(pairs.filter((p) => p.outcome).length * 10_000, pairs.length);
    summary.set(category, { n: pairs.length, brierBps: brierScoreBps(pairs), overconfidenceBps: meanProbabilityBps - hitRateBps });
  }
  return summary;
}

