import type { Clock } from "../kernel/clock";
import type { EventLog } from "../kernel/event-log";
import type { DomainEvent } from "../kernel/events";
import { type CalibrationSummary, type Forecast, forecastRecordedEvent, forecastResolvedEvent, forecastSchema } from "./calibration";

/** Append a forecast (validated) — the prediction is now falsifiable on record. */
export function recordForecast(log: EventLog, f: Forecast, clock: Clock): DomainEvent {
  const forecast = forecastSchema.parse(f);
  if (log.all().some((event) => event.type === "ForecastRecorded" && event.forecastId === forecast.id)) {
    throw new RangeError(`recordForecast: forecast "${forecast.id}" is already recorded`);
  }
  return log.append({ type: "ForecastRecorded", at: clock.now(), forecastId: forecast.id, category: forecast.category, claim: forecast.claim, probabilityBps: forecast.probabilityBps, resolveAtDay: forecast.resolveAtDay, criteria: forecast.criteria });
}

/** Resolve a recorded, still-open forecast exactly once. */
export function resolveForecast(log: EventLog, forecastId: string, outcome: boolean, day: number, clock: Clock): DomainEvent {
  const events = log.all();
  if (!events.some((event) => event.type === "ForecastRecorded" && event.forecastId === forecastId)) {
    throw new RangeError(`resolveForecast: unknown forecast "${forecastId}"`);
  }
  if (events.some((event) => event.type === "ForecastResolved" && event.forecastId === forecastId)) {
    throw new RangeError(`resolveForecast: forecast "${forecastId}" is already resolved`);
  }
  return log.append({ type: "ForecastResolved", at: clock.now(), forecastId, outcome, resolvedDay: day });
}

/** Forecasts due at or before `day` that have no resolution yet. */
export function openForecasts(log: EventLog, day: number): Forecast[] {
  const resolved = new Set<string>();
  const open: Forecast[] = [];
  for (const event of log.all()) {
    if (event.type === "ForecastResolved") resolved.add(forecastResolvedEvent.parse(event).forecastId);
  }
  for (const event of log.all()) {
    if (event.type !== "ForecastRecorded") continue;
    const f = forecastRecordedEvent.parse(event);
    if (resolved.has(f.forecastId) || f.resolveAtDay > day) continue;
    open.push({ id: f.forecastId, category: f.category, claim: f.claim, probabilityBps: f.probabilityBps, resolveAtDay: f.resolveAtDay, criteria: f.criteria });
  }
  return open;
}

/** E5 feedback: an over-confident category's expected value is discounted by its measured over-confidence (integer minor units). */
export function discountedEv(evMinor: number, category: string, calib: ReadonlyMap<string, CalibrationSummary>): number {
  const summary = calib.get(category);
  if (!summary) return evMinor;
  const overconfidence = Math.max(0, summary.overconfidenceBps);
  return Math.max(0, Math.floor((evMinor * (10_000 - overconfidence)) / 10_000));
}

import { describe, expect, it } from "vitest";
