import { makePrngTree } from "../../src/kernel/prng";

const forecast = (id: string, day: number, probabilityBps = 9_000) => ({ id, category: "marketing", claim: `campaign ${id} converts`, probabilityBps, resolveAtDay: day, criteria: "conversion ≥ 2%" });

describe("forecast recording, resolution and the calibration discount (E5)", () => {
  it("record → resolve yields n=1; double record/resolve and unknown ids throw; openForecasts respects the day", () => {
    const log = makeEventLog(makePrngTree(59));
    const clock = makeManualClock(0);
    recordForecast(log, forecast("f1", 3), clock);
    recordForecast(log, forecast("f2", 9), clock);
    expect(() => recordForecast(log, forecast("f1", 3), clock)).toThrow(/already recorded/u);
    expect(openForecasts(log, 3).map((f) => f.id)).toEqual(["f1"]);
    expect(openForecasts(log, 10).map((f) => f.id)).toEqual(["f1", "f2"]);
