      ["marketing", { n: 4, brierBps: 3_000, overconfidenceBps: 2_500 }],
      ["product", { n: 4, brierBps: 1_000, overconfidenceBps: -1_500 }],
    ]);
    expect(discountedEv(10_000, "marketing", calib)).toBe(7_500);
    expect(discountedEv(10_000, "product", calib)).toBe(10_000);
