/** V8.13 calibration honesty: a poorly-calibrated category with thin evidence cannot clear a high gate — it escalates. */
export const calibrationEscalationEvent = defineEvent("CalibrationEscalation", {
  decisionId: z.string().min(1),
  category: z.string().min(1),
  brierBps: z.number().int().nonnegative(),
  evidenceTrust: z.enum(TRUST_ORDER),
});

export interface CalibrationDecision {
  id: string;
  category: string;
  stakes: Stakes;
  evidenceTrust: Trust;
  requiredTrust: Trust;
}

/** Brier above this (or fewer than MIN_SAMPLES resolutions) counts as poor calibration. */
export const POOR_CALIBRATION_BRIER_BPS = 2_500;
export const MIN_SAMPLES = 3;

export function isPoorlyCalibrated(summary: CalibrationSummary | undefined): boolean {
  return summary === undefined || summary.n < MIN_SAMPLES || summary.brierBps > POOR_CALIBRATION_BRIER_BPS;
}

export function calibrationGate(log: EventLog, decision: CalibrationDecision, calib: ReadonlyMap<string, CalibrationSummary>, now: number): "pass" | "escalate" {
  const summary = calib.get(decision.category);
  const thinEvidence = !meetsMin(decision.evidenceTrust, decision.requiredTrust);
  if (decision.stakes !== "high" || !isPoorlyCalibrated(summary) || !thinEvidence) return "pass";
  if (!log.all().some((event) => event.type === "CalibrationEscalation" && event.decisionId === decision.id)) {
    log.append({ type: "CalibrationEscalation", at: now, decisionId: decision.id, category: decision.category, brierBps: summary?.brierBps ?? 10_000, evidenceTrust: decision.evidenceTrust });
  }
  return "escalate";
}

export const CALIBRATION_HONESTY_INVARIANT = "V8.13 calibration honesty";

/** Every escalated decision id must be absent from every external effect's audit inputsHash (no confident-wrong autonomy). */
export function assertCalibrationHonesty(log: EventLog): void {
  const events = log.all();
  const escalated = new Set(events.filter((event) => event.type === "CalibrationEscalation").map((event) => String(event.decisionId)));
  if (escalated.size === 0) return;
  for (const event of events) {
    if (event.type !== "AuditEvent") continue;
    const inputsHash = String(event.inputsHash);
    if (escalated.has(inputsHash)) {
      throw new Error(`decision ${inputsHash} was escalated for poor calibration but an audited side effect (${String(event.sideEffectId)}) executed it`);
    }
  }
}

registerInvariant(CALIBRATION_HONESTY_INVARIANT, assertCalibrationHonesty);

import { describe, expect, it } from "vitest";
import { emitAudit } from "../../src/audit/audit";
import { CALIBRATION_HONESTY_INVARIANT, calibrationGate, isPoorlyCalibrated } from "../../src/auth/calibration-gate";
import { makeEventLog } from "../../src/kernel/event-log";
import { makePrngTree } from "../../src/kernel/prng";
import { InvariantViolation, assertAllInvariants, listInvariants } from "../../src/sim/invariants";
import { runFactory } from "../../src/sim/run-factory";
import { baseline } from "../../src/sim/scenario-packs/baseline";

const poor = new Map([["marketing", { n: 5, brierBps: 4_100, overconfidenceBps: 4_000 }]]);
const good = new Map([["marketing", { n: 5, brierBps: 800, overconfidenceBps: 200 }]]);
const decision = { id: "dec-1", category: "marketing", stakes: "high" as const, evidenceTrust: "community-claim" as const, requiredTrust: "first-party-verified" as const };

describe("calibration-honesty gate (V8.13)", () => {
  it("escalates high-stakes thin-evidence decisions in poorly calibrated (or unmeasured) categories, once; passes otherwise", () => {
    const log = makeEventLog(makePrngTree(60));
    expect(calibrationGate(log, decision, poor, 1)).toBe("escalate");
    expect(calibrationGate(log, decision, poor, 2)).toBe("escalate");
    expect(log.all().filter((event) => event.type === "CalibrationEscalation")).toHaveLength(1);
    expect(calibrationGate(log, { ...decision, id: "dec-2" }, new Map(), 3)).toBe("escalate");
    expect(calibrationGate(log, { ...decision, id: "dec-3" }, good, 4)).toBe("pass");
    expect(calibrationGate(log, { ...decision, id: "dec-4", stakes: "medium" }, poor, 5)).toBe("pass");
    expect(calibrationGate(log, { ...decision, id: "dec-5", evidenceTrust: "owner-stated" }, poor, 6)).toBe("pass");
    expect(isPoorlyCalibrated({ n: 2, brierBps: 0, overconfidenceBps: 0 })).toBe(true);
  });

  it("registers the invariant, keeps the baseline green, and trips when an escalated decision is executed anyway", () => {
    expect(listInvariants()).toContain(CALIBRATION_HONESTY_INVARIANT);
    const { log } = runFactory(60, 3, baseline);
    expect(() => assertAllInvariants(log)).not.toThrow();
    calibrationGate(log, { ...decision, id: "dec-x" }, poor, 100);
    expect(() => assertAllInvariants(log)).not.toThrow();
    const moved = log.append({ type: "MoneyMoved", at: 101, fromAccount: "reserve", toAccount: "ads", minor: 100, reason: "campaign", sideEffectId: "pending" });
    emitAudit(log, { at: 101, actor: "marketer", brainVersion: "v1", modelVersion: "t1", toolVersion: "0", inputsHash: "dec-x", outputSummary: "spent anyway", approvalSource: "policy", financialImpactMinor: 100, rollbackRef: null, sideEffectId: moved.id });
    let caught: unknown;
    try {
      assertAllInvariants(log);
    } catch (error) {
      caught = error;
    }
    expect(caught).toBeInstanceOf(InvariantViolation);
    expect((caught as InvariantViolation).invariant).toBe(CALIBRATION_HONESTY_INVARIANT);
  });
});

import type { CalibrationSummary } from "./calibration";

/** E6: projects bid scarce brain-time against risk-adjusted EV; the owner's ruin policy caps every bet. */
export interface ComputeBid {
  projectId: string;
  /** Requested brain-time for this tick. */
  brainTimeMs: number;
  /** Risk-adjusted expected value of the work, integer minor units. */
  evMinor: number;
  /** Probability of losing the bet, in basis points. */
  riskBps: number;
  /** Bids sharing a key are correlated (same platform, same thesis) and diversified against. */
  correlationKey: string;
}

export interface MarketPolicy {
  budgetMs: number;
  /** Every bidder receives at least this much per tick (never starve a long shot). */
  fairnessFloorMs: number;
  /** Hard Kelly cap: no single bet exceeds this fraction of the budget. */
  maxFractionBps: number;
  runwayDays: number;
  reserveMinor: number;
}

export interface Allocation {
  projectId: string;
  brainTimeMs: number;
  reason: string;
}

const BPS = 10_000;

/** Kelly-style fraction in bps, hard-capped by the policy: (ev − risk×ev)/ev = 1 − risk, never above maxFractionBps, never negative. */
export function kellyFractionBps(evMinor: number, riskBps: number, maxFractionBps: number): number {
  if (evMinor <= 0) return 0;
  const edgeBps = BPS - Math.min(BPS, Math.max(0, riskBps));
  return Math.min(maxFractionBps, Math.max(0, edgeBps));
}

/** Bet size in brain-time ms: the requested time, capped by Kelly × budget and shrunk by measured over-confidence. */
export function sizeBet(bid: ComputeBid, policy: MarketPolicy, overconfidenceBps: number): number {
  const kelly = kellyFractionBps(bid.evMinor, bid.riskBps, policy.maxFractionBps);
  const confidence = BPS - Math.min(BPS, Math.max(0, overconfidenceBps));
  const cap = Math.floor((policy.budgetMs * kelly * confidence) / (BPS * BPS));
  return Math.max(0, Math.min(bid.brainTimeMs, cap));
}

/**
 * Clear one tick: fairness floors first, then the remainder by descending calibration-discounted EV (ties by projectId);
 * the second and later bids sharing a correlationKey get half; the total never exceeds the budget. Pure and deterministic.
 */
export function clearMarket(bids: readonly ComputeBid[], policy: MarketPolicy, calib: ReadonlyMap<string, CalibrationSummary>): Allocation[] {
  const overconfidenceOf = (bid: ComputeBid): number => Math.max(0, calib.get(bid.correlationKey)?.overconfidenceBps ?? 0);
  const discountedEv = (bid: ComputeBid): number => Math.floor((bid.evMinor * (BPS - overconfidenceOf(bid))) / BPS);
  const ordered = [...bids].sort((a, b) => discountedEv(b) - discountedEv(a) || (a.projectId < b.projectId ? -1 : a.projectId > b.projectId ? 1 : 0));
  const allocations = new Map<string, Allocation>();
  let remaining = policy.budgetMs;
  for (const bid of ordered) {
    const floor = Math.min(policy.fairnessFloorMs, bid.brainTimeMs, remaining);
    allocations.set(bid.projectId, { projectId: bid.projectId, brainTimeMs: floor, reason: "fairness floor" });
    remaining -= floor;
  }
  const seenKeys = new Set<string>();
  for (const bid of ordered) {
    const current = allocations.get(bid.projectId);
    if (!current) continue;
    let want = sizeBet(bid, policy, overconfidenceOf(bid)) - current.brainTimeMs;
    let reason = `discounted EV ${discountedEv(bid)}`;
    if (seenKeys.has(bid.correlationKey)) {
      want = Math.floor(want / 2);
      reason += ` (correlated with an earlier bid on "${bid.correlationKey}": halved)`;
    }
    seenKeys.add(bid.correlationKey);
    const grant = Math.max(0, Math.min(want, remaining));
    remaining -= grant;
    allocations.set(bid.projectId, { projectId: bid.projectId, brainTimeMs: current.brainTimeMs + grant, reason: grant > 0 ? reason : current.reason });
  }
  return ordered.map((bid) => allocations.get(bid.projectId) as Allocation);
}

import { describe, expect, it } from "vitest";
import { type ComputeBid, type MarketPolicy, clearMarket, kellyFractionBps, sizeBet } from "../../src/finance/compute-market";

const policy: MarketPolicy = { budgetMs: 10_000, fairnessFloorMs: 500, maxFractionBps: 4_000, runwayDays: 30, reserveMinor: 100_000 };
const bid = (projectId: string, evMinor: number, riskBps: number, correlationKey = projectId, brainTimeMs = 6_000): ComputeBid => ({ projectId, brainTimeMs, evMinor, riskBps, correlationKey });

describe("compute market (E6)", () => {
  it("Kelly fraction is 1 − risk, hard-capped and never negative; bet sizing shrinks with over-confidence", () => {
    expect(kellyFractionBps(1_000, 2_000, 4_000)).toBe(4_000);
    expect(kellyFractionBps(1_000, 8_000, 4_000)).toBe(2_000);
    expect(kellyFractionBps(1_000, 12_000, 4_000)).toBe(0);
    expect(kellyFractionBps(0, 0, 4_000)).toBe(0);
    expect(sizeBet(bid("a", 1_000, 8_000), policy, 0)).toBe(2_000);
    expect(sizeBet(bid("a", 1_000, 8_000), policy, 5_000)).toBe(1_000);
    expect(sizeBet(bid("a", 1_000, 8_000, "a", 700), policy, 0)).toBe(700);
  });

  it("clears deterministically: floors never starved, total ≤ budget, correlated bids halved, winners first", () => {
    const bids = [bid("cashcow", 50_000, 1_000), bid("longshot", 1_000, 9_500), bid("twin-a", 20_000, 2_000, "platform-x"), bid("twin-b", 20_000, 2_000, "platform-x")];
    const calib = new Map([["cashcow", { n: 5, brierBps: 1_000, overconfidenceBps: 1_000 }]]);
    const first = clearMarket(bids, policy, calib);
    const second = clearMarket([...bids].reverse(), policy, calib);
    expect(first).toEqual(second);
    expect(first.map((a) => a.projectId)).toEqual(["cashcow", "twin-a", "twin-b", "longshot"]);
    const total = first.reduce((s, a) => s + a.brainTimeMs, 0);
    expect(total).toBeLessThanOrEqual(policy.budgetMs);
    for (const allocation of first) expect(allocation.brainTimeMs).toBeGreaterThanOrEqual(Math.min(policy.fairnessFloorMs, 6_000));
    const twinA = first.find((a) => a.projectId === "twin-a") as { brainTimeMs: number };
    const twinB = first.find((a) => a.projectId === "twin-b") as { brainTimeMs: number; reason: string };
    expect(twinB.brainTimeMs).toBeLessThan(twinA.brainTimeMs);
    expect(twinB.reason).toMatch(/correlated/u);
    expect(first.every((a) => Number.isInteger(a.brainTimeMs))).toBe(true);
    expect(first.find((a) => a.projectId === "longshot")?.brainTimeMs).toBe(500);
  });
});

import { z } from "zod";
import { type AuditFields, emitAudit } from "../audit/audit";
import { registerExternalEffectTypes } from "../audit/side-effect";
import { commitOnce } from "../brain/idempotency";
import type { EventLog } from "../kernel/event-log";
import { defineEvent } from "../kernel/events";
import { registerInvariant } from "../sim/invariants";
import type { CalibrationSummary } from "./calibration";
import { type Allocation, type ComputeBid, type MarketPolicy, clearMarket } from "./compute-market";
import { balances } from "./ledger";

/** E6: an allocation of brain-time is a real (audited) side effect; a tick is idempotent across failover. */
export const computeAllocatedEvent = defineEvent("ComputeAllocated", {
  projectId: z.string().min(1),
  brainTimeMs: z.number().int().nonnegative(),
  tick: z.number().int().nonnegative(),
  reason: z.string(),
  correlationKey: z.string(),
  budgetMs: z.number().int().nonnegative(),
});

registerExternalEffectTypes(["ComputeAllocated"]);

export function runMarketTick(log: EventLog, bids: readonly ComputeBid[], policy: MarketPolicy, calib: ReadonlyMap<string, CalibrationSummary>, tick: number, audit: Omit<AuditFields, "sideEffectId" | "approvalSource">): Allocation[] {
  const allocations = clearMarket(bids, policy, calib);
  for (const allocation of allocations) {
    const bid = bids.find((b) => b.projectId === allocation.projectId);
    commitOnce(
      log,
      `market:${tick}:${allocation.projectId}`,
      () => {
        const allocated = log.append({ type: "ComputeAllocated", at: audit.at, projectId: allocation.projectId, brainTimeMs: allocation.brainTimeMs, tick, reason: allocation.reason, correlationKey: bid?.correlationKey ?? allocation.projectId, budgetMs: policy.budgetMs });
        emitAudit(log, { ...audit, approvalSource: "policy", sideEffectId: allocated.id, outputSummary: `tick ${tick}: ${allocation.brainTimeMs}ms to ${allocation.projectId} (${allocation.reason})` });
        return allocated;
      },
      audit.at,
    );
  }
  return allocations;
}

export const RUIN_AVOIDANCE_INVARIANT = "E6 ruin avoidance";

/** The reserve never dips below the policy floor and no project ever takes more than the hard fraction of a tick's budget. */
export function assertRuinConstraint(log: EventLog, policy: MarketPolicy): void {
  const reserve = balances(log).reserve ?? 0;
  if (reserve < policy.reserveMinor && log.all().some((event) => event.type === "MoneyMoved")) {
    throw new Error(`reserve ${reserve} minor is below the ruin floor ${policy.reserveMinor}`);
  }
  for (const event of log.all()) {
    if (event.type !== "ComputeAllocated") continue;
    const allocated = computeAllocatedEvent.parse(event);
    const cap = Math.floor((allocated.budgetMs * policy.maxFractionBps) / 10_000);
    if (allocated.brainTimeMs > Math.max(cap, policy.fairnessFloorMs)) {
      throw new Error(`tick ${allocated.tick} gave ${allocated.projectId} ${allocated.brainTimeMs}ms, above the ${policy.maxFractionBps} bps cap (${cap}ms)`);
    }
  }
}

/** Register the invariant for a policy (a run has one policy); registering again for the same policy is a no-op. */
const registered = new Set<string>();
export function registerRuinInvariant(policy: MarketPolicy): void {
  const key = JSON.stringify(policy);
  if (registered.has(key)) return;
  registered.add(key);
  registerInvariant(`${RUIN_AVOIDANCE_INVARIANT} (${registered.size})`, (log) => assertRuinConstraint(log, policy));
}

import { describe, expect, it } from "vitest";
import { assertAuditTotality, classifyEffect } from "../../src/audit/side-effect";
