import { InvariantViolation, assertAllInvariants, listInvariants } from "../../src/sim/invariants";
import { runFactory } from "../../src/sim/run-factory";
import { baseline } from "../../src/sim/scenario-packs/baseline";

const policy: MarketPolicy = { budgetMs: 10_000, fairnessFloorMs: 500, maxFractionBps: 4_000, runwayDays: 30, reserveMinor: 0 };
const audit = { at: 1, actor: "market", brainVersion: "v1", modelVersion: "t1", toolVersion: "0", inputsHash: "market", outputSummary: "", financialImpactMinor: 0, rollbackRef: null };
const bids = (winnerEv: number): ComputeBid[] => [
  { projectId: "winner", brainTimeMs: 8_000, evMinor: winnerEv, riskBps: 1_000, correlationKey: "a" },
  { projectId: "loser", brainTimeMs: 8_000, evMinor: 1_000, riskBps: 9_000, correlationKey: "b" },
];

describe("market tick (E6, governed)", () => {
  it("emits one audited ComputeAllocated per allocation, replays as a no-op, and reallocates toward demonstrated winners", () => {
    const log = makeEventLog(makePrngTree(62));
    const first = runMarketTick(log, bids(10_000), policy, new Map(), 1, audit);
    expect(classifyEffect("ComputeAllocated")).toBe("external");
    expect(log.all().filter((event) => event.type === "ComputeAllocated")).toHaveLength(2);
    expect(() => assertAuditTotality(log)).not.toThrow();
    const before = log.all().length;
    runMarketTick(log, bids(10_000), policy, new Map(), 1, audit);
    expect(log.all().length).toBe(before);
    const second = runMarketTick(log, bids(50_000), policy, new Map(), 2, { ...audit, at: 2 });
    const share = (a: { projectId: string; brainTimeMs: number }[]) => (a.find((x) => x.projectId === "winner")?.brainTimeMs ?? 0);
    expect(share(second)).toBeGreaterThanOrEqual(share(first));
    expect(() => assertRuinConstraint(log, policy)).not.toThrow();
  });

  it("the ruin invariant is registered, green on baseline, and trips on an over-allocation", () => {
    registerRuinInvariant(policy);
    expect(listInvariants().some((name) => name.startsWith("E6 ruin avoidance"))).toBe(true);
    const { log } = runFactory(62, 3, baseline);
    expect(() => assertAllInvariants(log)).not.toThrow();
    log.append({ type: "ComputeAllocated", at: 5, projectId: "greedy", brainTimeMs: 9_000, tick: 9, reason: "bug", correlationKey: "g", budgetMs: 10_000 });
    let caught: unknown;
    try {
      assertAllInvariants(log);
    } catch (error) {
      caught = error;
    }
    expect(caught).toBeInstanceOf(InvariantViolation);
    expect(String((caught as Error).message)).toMatch(/above the 4000 bps cap|side effect without audit/u);
  });
});

import { z } from "zod";
import { assertConservation, balances } from "../finance/ledger";
import type { EventLog } from "../kernel/event-log";
import { defineEvent, type DomainEvent } from "../kernel/events";

/** A spend that S20 routed to needs-owner: recorded so the cockpit (and S36's queue) can show it; no money moves. */
export const spendApprovalRequestedEvent = defineEvent("SpendApprovalRequested", {
  proposalId: z.string().min(1),
  minor: z.number().int().nonnegative(),
  reason: z.string(),
  deadlineAt: z.number().int(),
  reversible: z.boolean(),
  objection: z.string().nullable(),
});

export const spendApprovalResolvedEvent = defineEvent("SpendApprovalResolved", {
  proposalId: z.string().min(1),
  decision: z.enum(["approved", "rejected"]),
});

export function recordPendingApproval(
  log: EventLog,
  p: { proposalId: string; minor: number; reason: string; now: number; deadlineAt?: number; reversible?: boolean; objection?: string | null },
): DomainEvent {
  return log.append({
    type: "SpendApprovalRequested",
    at: p.now,
    proposalId: p.proposalId,
    minor: p.minor,
    reason: p.reason,
    deadlineAt: p.deadlineAt ?? p.now,
    reversible: p.reversible ?? true,
    objection: p.objection ?? null,
  });
}

export interface ConcentrationView {
  /** Share of allocated brain-time per correlation key, in basis points of the total allocated so far. */
  byCorrelationKey: Record<string, number>;
  maxKey: string | null;
  maxBps: number;
  /** E6: a single correlated thesis holding more than half the brain-time is a concentration risk. */
  warning: boolean;
}

export const CONCENTRATION_WARNING_BPS = 5000;

export interface MoneyRoomView {
  balances: Record<string, number>;
  pendingApprovals: { id: string; minor: number; reason: string }[];
  conserved: boolean;
  concentration: ConcentrationView;
}

/** Fold ComputeAllocated (S62) per correlation key — no dependency on the bids themselves. */
export function concentrationView(log: EventLog): ConcentrationView {
  const totals: Record<string, number> = {};
  let sum = 0;
  for (const event of log.all()) {
    if (event.type !== "ComputeAllocated") continue;
    const key = String(event.correlationKey ?? event.projectId);
    const ms = Number(event.brainTimeMs) || 0;
    totals[key] = (totals[key] ?? 0) + ms;
    sum += ms;
  }
  const byCorrelationKey: Record<string, number> = {};
  let maxKey: string | null = null;
  let maxBps = 0;
  for (const key of Object.keys(totals).sort()) {
    const bps = sum === 0 ? 0 : Math.round(((totals[key] ?? 0) * 10_000) / sum);
    byCorrelationKey[key] = bps;
    if (bps > maxBps) {
      maxBps = bps;
      maxKey = key;
    }
  }
  return { byCorrelationKey, maxKey, maxBps, warning: maxBps > CONCENTRATION_WARNING_BPS };
}

/** Pure projection: balances folded from MoneyMoved, open approvals, and whether conservation holds (E11.1). */
export function moneyRoomView(log: EventLog): MoneyRoomView {
  const resolved = new Set<string>();
  const pending: { id: string; minor: number; reason: string }[] = [];
  for (const event of log.all()) {
    if (event.type === "SpendApprovalResolved") {
      resolved.add(String(event.proposalId));
    }
  }
  for (const event of log.all()) {
    if (event.type === "SpendApprovalRequested") {
      const requested = spendApprovalRequestedEvent.parse(event);
      if (!resolved.has(requested.proposalId)) {
        pending.push({ id: requested.proposalId, minor: requested.minor, reason: requested.reason });
      }
    }
  }
  let conserved = true;
  try {
    assertConservation(log);
  } catch {
    conserved = false;
  }
  return { balances: balances(log), pendingApprovals: pending, conserved,
    concentration: concentrationView(log) };
}

import { type ComputeBid, type MarketPolicy } from "../../finance/compute-market";
import { registerRuinInvariant, runMarketTick } from "../../finance/market-tick";
