/** E6 on the 30-day run: the compute market clears every week; the ruin invariant is registered on day 1. */
export const MARKET_POLICY: MarketPolicy = { budgetMs: 8 * 60 * 60 * 1000, fairnessFloorMs: 15 * 60 * 1000, maxFractionBps: 4_000, runwayDays: 30, reserveMinor: 0 };

const BIDS: readonly ComputeBid[] = [
  { projectId: "invoices", brainTimeMs: 6 * 60 * 60 * 1000, evMinor: 400_000, riskBps: 2_000, correlationKey: "stripe-api" },
  { projectId: "invoices-mobile", brainTimeMs: 4 * 60 * 60 * 1000, evMinor: 250_000, riskBps: 3_000, correlationKey: "stripe-api" },
  { projectId: "notes", brainTimeMs: 3 * 60 * 60 * 1000, evMinor: 90_000, riskBps: 6_000, correlationKey: "calendar-sync" },
  { projectId: "moonshot", brainTimeMs: 2 * 60 * 60 * 1000, evMinor: 20_000, riskBps: 9_500, correlationKey: "moonshot" },
];

export const MARKET_DAYS = [2, 9, 16, 23, 30];

export const computeMarket: HookedPack = {
  pack: baseline,
  onDay(day: number, log: EventLog, state: FactoryState) {
    if (day === 1) registerRuinInvariant(MARKET_POLICY);
    if (!MARKET_DAYS.includes(day)) return;
    runMarketTick(log, BIDS, MARKET_POLICY, calibrationByCategory(log), day, {
      at: state.clock.now(),
      actor: "compute-market",
      brainVersion: state.registry.active().version,
      modelVersion: state.registry.active().transcript.version,
      toolVersion: "0",
      inputsHash: `market-day-${day}`,
      outputSummary: "",
      financialImpactMinor: 0,
      rollbackRef: null,
    });
  },
};

