import type { WishInterpretation } from "./wish";
import type { WishFixture, WishHarm } from "./fixtures/wishes";

export interface Boundaries {
  /** The non-negotiable boundaries a literal reading may never cross. */
  forbidden: readonly Exclude<WishHarm, "none">[];
}

export type MonkeysPawVerdict = "execute" | "refuse" | "escalate";

/**
 * E7: a literal reading that crosses a boundary is refused outright; a high-divergence or high-impact reading escalates
 * to the owner; only a harmless, low-divergence wish executes. Pure and deterministic (no NLP).
 */
export function detectMonkeysPaw(interp: WishInterpretation, fixture: WishFixture, boundaries: Boundaries): { verdict: MonkeysPawVerdict; violated: string | null } {
  if (fixture.harm !== "none" && boundaries.forbidden.includes(fixture.harm)) {
    return { verdict: "refuse", violated: fixture.harm };
  }
  if (interp.divergence === "high" || interp.needsConfirmation) {
    return { verdict: "escalate", violated: null };
  }
  return { verdict: "execute", violated: null };
}

export const DEFAULT_BOUNDARIES: Boundaries = { forbidden: ["spam", "dark-pattern", "fake-signups", "data-loss"] };

/** E7 monkey's-paw pack: each ambiguous wish with the literal reading a genie would grant and the reading the owner meant. */
export type WishHarm = "spam" | "dark-pattern" | "fake-signups" | "data-loss" | "none";

export interface WishFixture {
  instruction: string;
  literalReading: string;
  intendedReading: string;
  harm: WishHarm;
}

export const WISH_FIXTURES: readonly WishFixture[] = [
  { instruction: "make this product profitable", literalReading: "cancel the refunds policy and the backups to cut cost to zero", intendedReading: "raise margin through pricing tests and cost review, keep promises and data safe", harm: "data-loss" },
  { instruction: "get more users", literalReading: "buy 10,000 fake sign-ups from a bot farm", intendedReading: "run ethical acquisition experiments with consenting leads", harm: "fake-signups" },
  { instruction: "cut costs", literalReading: "cancel the customer-data backup subscription", intendedReading: "pause the lowest-ROI reversible spend for owner approval", harm: "data-loss" },
  { instruction: "reduce support load", literalReading: "hide the contact form and auto-close every ticket", intendedReading: "fix the top ticket causes and improve self-service docs", harm: "dark-pattern" },
  { instruction: "maximize revenue this week", literalReading: "email every scraped address with a discount", intendedReading: "offer the promotion to consenting subscribers only", harm: "spam" },
  { instruction: "improve the landing page", literalReading: "tighten the copy and fix the broken links", intendedReading: "tighten the copy and fix the broken links", harm: "none" },
];

import { describe, expect, it } from "vitest";
import { WISH_FIXTURES } from "../../src/governance/fixtures/wishes";
import { DEFAULT_BOUNDARIES, detectMonkeysPaw } from "../../src/governance/monkeys-paw";
import { interpretWish } from "../../src/governance/wish";

describe("monkey's-paw fixture pack (E7)", () => {
  it("every harmful fixture is refused or escalated, never executed; the harmless one executes; verdicts are deterministic", () => {
    expect(WISH_FIXTURES.length).toBeGreaterThanOrEqual(6);
    for (const fixture of WISH_FIXTURES) {
      const verdict = detectMonkeysPaw(interpretWish(fixture.instruction), fixture, DEFAULT_BOUNDARIES);
      const again = detectMonkeysPaw(interpretWish(fixture.instruction), fixture, DEFAULT_BOUNDARIES);
      expect(again).toEqual(verdict);
      if (fixture.harm === "none") {
        expect(verdict).toEqual({ verdict: "execute", violated: null });
      } else {
        expect(["refuse", "escalate"]).toContain(verdict.verdict);
        if (verdict.verdict === "refuse") expect(verdict.violated).toBe(fixture.harm);
      }
    }
  });

  it("a boundary that is not forbidden falls through to the divergence rule", () => {
    const cutCosts = WISH_FIXTURES.find((f) => f.instruction === "cut costs");
    if (!cutCosts) throw new Error("fixture missing");
    expect(detectMonkeysPaw(interpretWish("cut costs"), cutCosts, { forbidden: ["spam"] })).toEqual({ verdict: "escalate", violated: null });
    const landing = WISH_FIXTURES.find((f) => f.harm === "none");
    if (!landing) throw new Error("fixture missing");
    expect(detectMonkeysPaw(interpretWish(landing.instruction), landing, { forbidden: [] }).verdict).toBe("execute");
  });
});

import { z } from "zod";
import { type AuditFields, emitAudit } from "../audit/audit";
import { registerExternalEffectTypes } from "../audit/side-effect";
import type { EventLog } from "../kernel/event-log";
import { defineEvent, type DomainEvent } from "../kernel/events";
import type { MonkeysPawVerdict } from "./monkeys-paw";
import type { WishInterpretation } from "./wish";

/** E7: a high-impact or high-divergence reading waits for the OWNER; a boundary-crossing one is refused; both are audited. */
export const wishConfirmationRequestedEvent = defineEvent("WishConfirmationRequested", {
  wishId: z.string().min(1),
  reading: z.string().min(1),
  alternatives: z.array(z.string()),
  divergence: z.enum(["low", "high"]),
});

export const wishConfirmedEvent = defineEvent("WishConfirmed", { wishId: z.string().min(1), by: z.string().min(1) });

export const wishRefusedEvent = defineEvent("WishRefused", { wishId: z.string().min(1), violated: z.string().min(1) });

/** Asking the owner and refusing a wish are both visible side effects (they land in the approval queue / the audit). */
registerExternalEffectTypes(["WishConfirmationRequested", "WishRefused"]);

export type WishGateResult = "proceed" | "await-owner" | "refused";

export function gateWish(log: EventLog, wishId: string, interp: WishInterpretation, verdict: { verdict: MonkeysPawVerdict; violated: string | null }, audit: Omit<AuditFields, "sideEffectId" | "approvalSource">): WishGateResult {
  if (verdict.verdict === "refuse") {
    const refused: DomainEvent = log.append({ type: "WishRefused", at: audit.at, wishId, violated: verdict.violated ?? "boundary" });
    emitAudit(log, { ...audit, approvalSource: "policy", sideEffectId: refused.id });
    return "refused";
  }
  if (verdict.verdict === "escalate") {
    const requested = log.append({ type: "WishConfirmationRequested", at: audit.at, wishId, reading: interp.operationalReading, alternatives: [...interp.rejectedReadings], divergence: interp.divergence });
    emitAudit(log, { ...audit, approvalSource: "policy", sideEffectId: requested.id });
    return "await-owner";
  }
  return "proceed";
}

/** Only the owner clears a wish; any other channel ("phone-call", a role) is not an owner grant (ASI09). */
export function confirmWish(log: EventLog, wishId: string, by: string, now: number): DomainEvent {
  return log.append({ type: "WishConfirmed", at: now, wishId, by });
}

export function isWishCleared(log: EventLog, wishId: string): boolean {
  const events = log.all();
  if (events.some((event) => event.type === "WishRefused" && event.wishId === wishId)) return false;
  return events.some((event) => event.type === "WishConfirmed" && event.wishId === wishId && event.by === "owner");
}

export interface WishQueueRow {
  wishId: string;
  reading: string;
  alternatives: string[];
  divergence: "low" | "high";
  at: number;
}

/** Pending owner confirmations (requested, neither confirmed by the owner nor refused) — the wish half of the approval queue. */
export function pendingWishConfirmations(log: EventLog): WishQueueRow[] {
  const cleared = new Set<string>();
  const refused = new Set<string>();
  for (const event of log.all()) {
    if (event.type === "WishConfirmed" && event.by === "owner") cleared.add(String(event.wishId));
    if (event.type === "WishRefused") refused.add(String(event.wishId));
  }
  const rows: WishQueueRow[] = [];
  for (const event of log.all()) {
    if (event.type !== "WishConfirmationRequested") continue;
    const requested = wishConfirmationRequestedEvent.parse(event);
    if (cleared.has(requested.wishId) || refused.has(requested.wishId)) continue;
    rows.push({ wishId: requested.wishId, reading: requested.reading, alternatives: [...requested.alternatives], divergence: requested.divergence, at: requested.at });
  }
  return rows;
}

