/** E8: the factory is an organization of typed roles, not a prompt chain. */
export const ROLES = ["scout", "pm", "engineer", "marketer", "finance", "infra", "maintainer", "redteam"] as const;

export type RoleId = (typeof ROLES)[number];

export function isRoleId(value: string): value is RoleId {
  return (ROLES as readonly string[]).includes(value);
}

/** Deterministic fixture signing keys — one per role (a real deployment injects them from the constitution's key store). */
export function fixtureRoleKey(role: RoleId): string {
  return `key:${role}`;
}

import { createHmac } from "node:crypto";
import { z } from "zod";
import type { EventLog } from "../kernel/event-log";
import { defineEvent, type DomainEvent } from "../kernel/events";
import { canonicalJson } from "../util/canonical-json";
import { ROLES, type RoleId } from "./roles";

/** ASI07 / V8.5: every inter-role hand-off is signed by its sender and grounded in evidence nodes. */
export interface HandOff {
  id: string;
  from: RoleId;
  to: RoleId;
  kind: string;
  payload: unknown;
  evidenceNodeIds: string[];
  signature: string;
}

export const handOffRejectedEvent = defineEvent("HandOffRejected", {
  handOffId: z.string().min(1),
  from: z.enum(ROLES),
  to: z.enum(ROLES),
  reason: z.enum(["bad-signature", "ungrounded"]),
});

function signingInput(h: Omit<HandOff, "signature">): string {
  return canonicalJson({ id: h.id, from: h.from, to: h.to, kind: h.kind, payload: h.payload, evidenceNodeIds: h.evidenceNodeIds });
}

/** HMAC-SHA256 over the canonical JSON of the unsigned hand-off with the SENDER's key. */
export function signHandOff(h: Omit<HandOff, "signature">, key: string): HandOff {
  return Object.freeze({ ...h, evidenceNodeIds: [...h.evidenceNodeIds], signature: createHmac("sha256", key).update(signingInput(h)).digest("hex") });
}

/** Verify with the key of the role the hand-off CLAIMS to come from (a forged sender fails by construction). */
export function verifyHandOff(h: HandOff, keyOf: (role: RoleId) => string): boolean {
  const { signature, ...unsigned } = h;
  const expected = createHmac("sha256", keyOf(h.from)).update(signingInput(unsigned)).digest("hex");
  return expected.length === signature.length && expected === signature;
}

/** Accept a hand-off into the org: ungrounded or badly signed ones are refused with one HandOffRejected event. */
export function acceptHandOff(log: EventLog, h: HandOff, keyOf: (role: RoleId) => string, now: number): boolean {
  const reason = h.evidenceNodeIds.length === 0 ? "ungrounded" : !verifyHandOff(h, keyOf) ? "bad-signature" : null;
  if (reason === null) return true;
  const rejected: DomainEvent = log.append({ type: "HandOffRejected", at: now, handOffId: h.id, from: h.from, to: h.to, reason });
  void rejected;
  return false;
}

