import { z } from "zod";
import { type AuditFields, emitAudit } from "../audit/audit";
import { registerExternalEffectTypes } from "../audit/side-effect";
import type { EvidenceGraph } from "../evidence/graph";
import { traceGrounding } from "../evidence/grounding";
import type { EventLog } from "../kernel/event-log";
import { defineEvent } from "../kernel/events";

/** E8: every high-stakes decision carries the strongest objection the red team could raise — and its answer. */
export interface Decision {
  id: string;
  kind: "spend" | "launch" | "promotion" | "self-mod" | "other";
  amountMinor?: number;
  evidenceNodeIds: string[];
  reversible: boolean;
}

export interface RedTeamPolicy {
  spendThresholdMinor: number;
}

export interface Objection {
  decisionId: string;
  strongest: string;
  severity: "low" | "medium" | "high";
}

export const redTeamEscalatedEvent = defineEvent("RedTeamEscalated", {
  decisionId: z.string().min(1),
  kind: z.enum(["spend", "launch", "promotion", "self-mod", "other"]),
  objection: z.string().min(1),
  severity: z.enum(["low", "medium", "high"]),
});

registerExternalEffectTypes(["RedTeamEscalated"]);

export function requiresRedTeam(d: Decision, p: RedTeamPolicy): boolean {
  if (d.kind === "launch" || d.kind === "promotion" || d.kind === "self-mod") return true;
  return d.kind === "spend" && (d.amountMinor ?? 0) > p.spendThresholdMinor;
}

/** The strongest objection: under-grounded evidence (high), an irreversible step (medium), else a routine caution (low). */
export function redTeamObjection(d: Decision, g: EvidenceGraph): Objection {
  const ungrounded = d.evidenceNodeIds.length === 0 || d.evidenceNodeIds.some((id) => !traceGrounding(g, id, "first-party-verified").grounded);
  if (ungrounded) {
    return { decisionId: d.id, strongest: `evidence for ${d.kind} ${d.id} does not ground to a first-party-verified leaf`, severity: "high" };
  }
  if (!d.reversible) {
    return { decisionId: d.id, strongest: `${d.kind} ${d.id} is irreversible; no rollback plan can undo it`, severity: "medium" };
  }
  return { decisionId: d.id, strongest: `${d.kind} ${d.id} carries the usual execution risk`, severity: "low" };
}

/** Unanswered medium/high objections escalate to the owner (audited with the objection); answered ones approve with both recorded. */
export function redTeamGate(log: EventLog, d: Decision, objection: Objection, answer: string | null, audit: Omit<AuditFields, "sideEffectId" | "approvalSource" | "outputSummary">): "approved" | "escalated" {
  if (objection.severity !== "low" && answer === null) {
    const escalated = log.append({ type: "RedTeamEscalated", at: audit.at, decisionId: d.id, kind: d.kind, objection: objection.strongest, severity: objection.severity });
    emitAudit(log, { ...audit, approvalSource: "policy", outputSummary: `escalated: ${objection.strongest}`, sideEffectId: escalated.id });
    return "escalated";
  }
  return "approved";
}

/** The audit text a downstream side effect records when a decision passed the red team: objection + answer, verbatim. */
export function redTeamRecord(objection: Objection, answer: string | null): string {
  return `objection(${objection.severity}): ${objection.strongest} | answer: ${answer ?? "none required"}`;
}

import { describe, expect, it } from "vitest";
import { assertAuditTotality } from "../../src/audit/side-effect";
import { makeEvidenceGraph } from "../../src/evidence/graph";
import { makeEventLog } from "../../src/kernel/event-log";
import { makePrngTree } from "../../src/kernel/prng";
import { type Decision, redTeamGate, redTeamObjection, redTeamRecord, requiresRedTeam } from "../../src/org/red-team";

const policy = { spendThresholdMinor: 100_000 };
const audit = { at: 1, actor: "redteam", brainVersion: "0", modelVersion: "fixture", toolVersion: "0", inputsHash: "h", financialImpactMinor: 0, rollbackRef: null };

function graphWithGroundedDecision() {
  const g = makeEvidenceGraph(makePrngTree(67));
  const leaf = g.addNode({ kind: "fact", trust: "first-party-verified", label: "signed contract" });
  const decision = g.addNode({ kind: "decision", trust: "first-party-verified", label: "spend" });
  g.link({ from: decision.id, to: leaf.id, sign: "supports", confidence: 1, freshnessAt: 0 });
  const hype = g.addNode({ kind: "claim", trust: "model-generated", label: "rumour" });
  const shaky = g.addNode({ kind: "decision", trust: "model-generated", label: "launch" });
  g.link({ from: shaky.id, to: hype.id, sign: "supports", confidence: 1, freshnessAt: 0 });
  return { g, decision, shaky };
}

describe("red-team objection + high-stakes sign-off gate (E8)", () => {
  it("decides which decisions need the red team", () => {
    expect(requiresRedTeam({ id: "d1", kind: "spend", amountMinor: 100_001, evidenceNodeIds: [], reversible: true }, policy)).toBe(true);
    expect(requiresRedTeam({ id: "d2", kind: "spend", amountMinor: 100_000, evidenceNodeIds: [], reversible: true }, policy)).toBe(false);
    expect(requiresRedTeam({ id: "d3", kind: "launch", evidenceNodeIds: [], reversible: false }, policy)).toBe(true);
    expect(requiresRedTeam({ id: "d4", kind: "other", evidenceNodeIds: [], reversible: true }, policy)).toBe(false);
  });

  it("an unanswered high objection escalates with the objection on the audit; an answered one approves", () => {
    const { g, decision, shaky } = graphWithGroundedDecision();
    const log = makeEventLog(makePrngTree(68));
    const launch: Decision = { id: "launch-1", kind: "launch", evidenceNodeIds: [shaky.id], reversible: false };
    const objection = redTeamObjection(launch, g);
    expect(objection.severity).toBe("high");
    expect(redTeamGate(log, launch, objection, null, audit)).toBe("escalated");
    const escalations = log.all().filter((event) => event.type === "RedTeamEscalated");
    expect(escalations).toHaveLength(1);
    expect(log.all().find((event) => event.type === "AuditEvent")?.outputSummary).toMatch(/does not ground/u);
    expect(() => assertAuditTotality(log)).not.toThrow();
    const spend: Decision = { id: "spend-1", kind: "spend", amountMinor: 250_000, evidenceNodeIds: [decision.id], reversible: false };
    const spendObjection = redTeamObjection(spend, g);
    expect(spendObjection.severity).toBe("medium");
    expect(redTeamGate(log, spend, spendObjection, "vendor contract has a 30-day exit clause", audit)).toBe("approved");
    expect(log.all().filter((event) => event.type === "RedTeamEscalated")).toHaveLength(1);
    expect(redTeamRecord(spendObjection, "vendor contract has a 30-day exit clause")).toMatch(/objection\(medium\).*answer: vendor/u);
    const routine: Decision = { id: "spend-2", kind: "spend", amountMinor: 1_000, evidenceNodeIds: [decision.id], reversible: true };
    expect(redTeamObjection(routine, g).severity).toBe("low");
    expect(redTeamGate(log, routine, redTeamObjection(routine, g), null, audit)).toBe("approved");
  });
});

