import { createHash } from "node:crypto";
import { TRUST_ORDER, type Trust, trustRank } from "../trust/trust";
import { canonicalJson } from "../util/canonical-json";

/** The policy surface a self-modification may touch only in the tightening direction (E9 safety ratchet). */
export interface PolicyBundle {
  minTrustForSpend: Trust;
  autoApproveLimitMinor: number;
  auditFields: readonly string[];
  taintGates: Record<string, Trust>;
}

function deepFreeze<T>(value: T): T {
  if (value !== null && typeof value === "object") {
    for (const item of Object.values(value as Record<string, unknown>)) deepFreeze(item);
    Object.freeze(value);
  }
  return value;
}

/**
 * The immutable core (E9 / V5): the components no role, brain, tool or !Klein run may modify, plus the policy floor.
 * Separately hashed so a run can prove the kernel it started under is the kernel it is still running under.
 */
export const CONSTITUTION: Readonly<{ version: string; coreComponents: readonly string[]; policy: PolicyBundle }> = deepFreeze({
  version: "1",
  coreComponents: [
    "auth/capability",
    "auth/gate",
    "audit/audit",
    "audit/side-effect",
    "cockpit/kill-switch",
    "finance/budget",
    "trust/tainted",
    "governance/constitution",
  ],
  policy: {
    minTrustForSpend: "first-party-verified",
    autoApproveLimitMinor: 10_000,
    auditFields: ["actor", "brainVersion", "modelVersion", "toolVersion", "inputsHash", "outputSummary", "approvalSource", "financialImpactMinor", "rollbackRef", "sideEffectId"],
    taintGates: { spend: "first-party-verified", publish: "first-party-verified", "brain-promotion": "benchmarked", "self-modification": "owner-stated" },
  },
});

export function constitutionHash(): string {
  return createHash("sha256").update(canonicalJson(CONSTITUTION)).digest("hex");
}

/** `src/auth/gate.ts`, `auth/gate.ts` and `auth/gate` all name the same core component. */
export function isCoreComponent(path: string): boolean {
  const normalized = path.trim().replace(/\\/gu, "/").replace(/^\.?\//u, "").replace(/^src\//u, "").replace(/\.(ts|js|mts|mjs)$/u, "");
  return CONSTITUTION.coreComponents.includes(normalized);
}

/** The ratchet: `after` may only tighten `before` — never lower a trust floor, raise auto-approval, drop an audit field or loosen/remove a taint gate. */
export function ratchetOk(before: PolicyBundle, after: PolicyBundle): boolean {
  if (trustRank(after.minTrustForSpend) < trustRank(before.minTrustForSpend)) return false;
  if (after.autoApproveLimitMinor > before.autoApproveLimitMinor) return false;
  if (!before.auditFields.every((field) => after.auditFields.includes(field))) return false;
  for (const [gate, floor] of Object.entries(before.taintGates)) {
    const next = after.taintGates[gate];
    if (next === undefined || !(TRUST_ORDER as readonly string[]).includes(next) || trustRank(next) < trustRank(floor)) return false;
  }
  return true;
}

export function assertConstitutionIntact(expectedHash: string): void {
  const actual = constitutionHash();
  if (actual !== expectedHash) {
    throw new Error(`constitution hash mismatch: expected ${expectedHash}, running under ${actual}`);
  }
}

