/** V6.1: a self-change is a product — built through the governed !Klein envelope and staged to the CANDIDATE brain first. */
export interface SelfChangeProposal {
  id: string;
  title: string;
  touches: readonly string[];
  /** The proposal's thesis node on the evidence graph (must ground ≥ first-party-verified, like any build). */
  thesisNodeId: string;
  policyAfter: PolicyBundle;
}

export const selfChangeStagedEvent = defineEvent("SelfChangeStaged", { proposalId: z.string().min(1), runId: z.string().min(1), targetBrainId: z.string().min(1) });
export const selfChangeRejectedEvent = defineEvent("SelfChangeRejected", { proposalId: z.string().min(1), reason: z.string().min(1) });

registerExternalEffectTypes(["SelfChangeStaged"]);

export function selfChangeSpec(p: SelfChangeProposal): ProductSpec {
  return { id: `self-${p.id}`, targetUser: "the factory itself", promise: p.title, mvpSlice: p.touches.join(", "), killCriteria: "any invariant regression or a weakened safety property", acceptance: "npm test", evidenceTrust: "owner-stated" };
}

export type SelfChangeResult = { status: "staged"; runId: string; targetBrainId: string } | { status: "rejected"; reason: string };

function reject(log: EventLog, p: SelfChangeProposal, reason: string, now: number): SelfChangeResult {
  log.append({ type: "SelfChangeRejected", at: now, proposalId: p.id, reason });
  return { status: "rejected", reason };
}

/**
 * Constitution first (core untouchable, ratchet), then the same envelope as any product build (commissioned by the
 * ACTIVE brain — V3.2 — and staged to the candidate), then one audited SelfChangeStaged.
 */
export function proposeSelfChange(log: EventLog, adapter: KleinAdapter, g: EvidenceGraph, reg: BrainRegistry, p: SelfChangeProposal, commission: { budgetGrant: Capability; clock: Clock }, audit: Omit<AuditFields, "sideEffectId" | "approvalSource" | "at" | "inputsHash">): SelfChangeResult {
  const now = commission.clock.now();
  const core = p.touches.find((path) => isCoreComponent(path));
  if (core !== undefined) return reject(log, p, `touches the immutable core: ${core}`, now);
  if (!ratchetOk(CONSTITUTION.policy, p.policyAfter)) return reject(log, p, "weakens a safety property (ratchet)", now);
  const candidate = reg.candidate();
  if (!candidate) return reject(log, p, "no candidate brain to stage to", now);
  const spec = selfChangeSpec(p);
  const result = commissionBuild(log, adapter, g, { spec, brain: reg.active(), budgetGrant: commission.budgetGrant, clock: commission.clock, specNodeId: p.thesisNodeId });
  if (result.status !== "shipped") return reject(log, p, `build declined: ${result.reason}`, now);
  const runId = result.branches[0]?.runId ?? spec.id;
  const staged = log.append({ type: "SelfChangeStaged", at: now, proposalId: p.id, runId, targetBrainId: candidate.version });
  emitAudit(log, { ...audit, at: now, approvalSource: "policy", inputsHash: sha256Hex(canonicalJson(p)), sideEffectId: staged.id });
  return { status: "staged", runId, targetBrainId: candidate.version };
}

