import { registerInvariant } from "../sim/invariants";

/** V6.2 / V8.11: an improvement is never accepted from a self-report — it is re-derived from the evidence bundle. */
export interface ImprovementClaim {
  proposalId: string;
  metric: string;
  beforeBps: number;
  afterBps: number;
  bundleRunId: string;
}

export const improvementVerifiedEvent = defineEvent("ImprovementVerified", { proposalId: z.string().min(1), metric: z.string().min(1), afterBps: z.number().int(), runId: z.string().min(1) });
export const improvementRejectedEvent = defineEvent("ImprovementRejected", { proposalId: z.string().min(1), reason: z.string().min(1) });

const metricMarker = (metric: string, afterBps: number): RegExp => new RegExp(`\\b${metric.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&")}[=:]\\s*${afterBps}\\b`, "u");

export function verifyImprovementClaim(log: EventLog, claim: ImprovementClaim, bundle: EvidenceBundle, plan: BuildPlan, now: number): { accepted: boolean; reason: string } {
  const reject = (reason: string) => {
    log.append({ type: "ImprovementRejected", at: now, proposalId: claim.proposalId, reason });
    return { accepted: false, reason };
  };
  if (claim.bundleRunId !== bundle.runId) return reject(`claim names run ${claim.bundleRunId} but the bundle is ${bundle.runId}`);
  const build = verifyBuildSuccess(bundle, plan);
  if (!build.trustworthy) return reject(`build evidence not trustworthy: ${build.reason ?? "unknown"}`);
  const marker = metricMarker(claim.metric, claim.afterBps);
  const rederived = Object.values(bundle.testLogs).some((entry) => entry.passed && marker.test(entry.raw));
  if (!rederived) return reject(`metric ${claim.metric}=${claim.afterBps} is not re-derivable from the evidence bundle`);
  if (claim.afterBps <= claim.beforeBps) return reject(`no improvement: ${claim.afterBps} ≤ ${claim.beforeBps}`);
  log.append({ type: "ImprovementVerified", at: now, proposalId: claim.proposalId, metric: claim.metric, afterBps: claim.afterBps, runId: bundle.runId });
  return { accepted: true, reason: "re-derived from the evidence bundle" };
}

export const EVIDENCE_DERIVED_SELF_CHANGE_INVARIANT = "V8.11 evidence-derived success (self-change)";

/** Every staged self-change and every verified improvement must trace to a passing card-tests-run of its run on the log. */
export function assertEvidenceDerivedSelfChange(log: EventLog): void {
  const events = log.all();
  const passingRuns = new Set<string>();
  for (const event of events) {
    if (event.type !== "KleinEventLogged") continue;
    const logged = kleinEventLoggedEvent.parse(event);
    if (logged.event.t === "card-tests-run" && logged.event.passed) passingRuns.add(logged.runId);
  }
  for (const event of events) {
    if (event.type === "SelfChangeStaged" && !passingRuns.has(String(event.runId))) {
      throw new Error(`self-change ${String(event.proposalId)} was staged without a passing card-tests-run for run ${String(event.runId)}`);
    }
    if (event.type === "ImprovementVerified" && !passingRuns.has(String(event.runId))) {
      throw new Error(`improvement ${String(event.proposalId)} was verified without a passing card-tests-run for run ${String(event.runId)}`);
    }
  }
}

registerInvariant(EVIDENCE_DERIVED_SELF_CHANGE_INVARIANT, assertEvidenceDerivedSelfChange);

