import type { Prng } from "../kernel/prng";
import type { SimService } from "../services/sim-service";
import { type Tainted, taint } from "../trust/tainted";
import { type ModelEntry, modelEntrySchema } from "./types";

/** §M1 L3: the model catalog is a SimService; every entry it serves is a community claim until verified (E2). */
export interface ModelRegistry extends SimService {
  list(): Tainted<ModelEntry>[];
}

export function makeFixtureModelRegistry(prng: Prng, entries: readonly ModelEntry[]): ModelRegistry {
  const seeded = prng.fork("modelintel");
  const catalog = entries.map((entry) => modelEntrySchema.parse(entry));
  void seeded;
  return {
    name: "fixture-model-registry",
    list: () => catalog.map((entry) => taint({ ...entry, benchScores: { ...entry.benchScores } }, "community-claim", `modelintel:${entry.id}`)),
  };
}

