import { z } from "zod";
import { type AuditFields, emitAudit } from "../audit/audit";
import { registerExternalEffectTypes } from "../audit/side-effect";
import type { EventLog } from "../kernel/event-log";
import { defineEvent } from "../kernel/events";
import { type Tainted, verify } from "../trust/tainted";
import { meetsMin } from "../trust/trust";
import { isCommercialUseAllowed } from "./license";
import type { ModelEntry } from "./types";

/** §M1 L4: a benchmark claim is raised to `benchmarked` only when the harness re-derives it; a fabricated claim is audited. */
export const benchmarkClaimRejectedEvent = defineEvent("BenchmarkClaimRejected", {
  modelId: z.string().min(1),
  metric: z.string().min(1),
  claimed: z.number(),
  measured: z.number(),
});

registerExternalEffectTypes(["BenchmarkClaimRejected"]);

/** Claimed vs measured may differ by at most this many basis points of the measured score. */
export const BENCHMARK_TOLERANCE_BPS = 500;

function withinTolerance(claimed: number, measured: number): boolean {
  const scale = Math.max(Math.abs(measured), 1);
  return Math.abs(claimed - measured) * 10_000 <= BENCHMARK_TOLERANCE_BPS * scale;
}

export function verifyBenchmark(log: EventLog, entry: Tainted<ModelEntry>, harness: { scores: Record<string, number> }, audit: Omit<AuditFields, "sideEffectId" | "approvalSource">): Tainted<ModelEntry> {
  for (const [metric, claimed] of Object.entries(entry.value.benchScores)) {
    const measured = harness.scores[metric];
    if (measured === undefined || !withinTolerance(claimed, measured)) {
      const rejected = log.append({ type: "BenchmarkClaimRejected", at: audit.at, modelId: entry.value.id, metric, claimed, measured: measured ?? Number.NaN });
      emitAudit(log, { ...audit, approvalSource: "policy", sideEffectId: rejected.id });
      return entry;
    }
  }
  return verify(entry, "benchmarked", () => undefined);
}

export function canPromote(entry: Tainted<ModelEntry>): { ok: boolean; reason: string | null } {
  if (entry.value.malwareFlag) return { ok: false, reason: "malware-flagged" };
  if (!isCommercialUseAllowed(entry.value.license)) return { ok: false, reason: `license ${entry.value.license} forbids commercial use` };
  if (!meetsMin(entry.trust, "benchmarked")) return { ok: false, reason: `trust ${entry.trust} is below benchmarked` };
  return { ok: true, reason: null };
}

import { describe, expect, it } from "vitest";
import { assertAuditTotality } from "../../src/audit/side-effect";
import { makeEventLog } from "../../src/kernel/event-log";
