const audit = { at: 1, actor: "modelintel", brainVersion: "v1", modelVersion: "t1", toolVersion: "0", inputsHash: "feed", outputSummary: "benchmark claim rejected", financialImpactMinor: 0, rollbackRef: null };
const entries = [
  { id: "sota-x", benchScores: { swe: 90 }, license: "research-only", quant: "Q8", ctx: 8192, costMinorPer1k: 0, malwareFlag: true },
