];

describe("poisoned model-intel feed (V7 #8 / ASI04)", () => {
  it("the 'new SOTA model' stays community-claim with one audited rejection and cannot be promoted for three independent reasons", () => {
    const log = makeEventLog(makePrngTree(76));
    const [sota, honest] = makeFixtureModelRegistry(makePrngTree(76), entries).list();
    if (!sota || !honest) throw new Error("fixture");
    const verified = verifyBenchmark(log, sota, { scores: { swe: 60 } }, audit);
