import { z } from "zod";
import { type BrainRegistry, brainFailoverEvent, brainPromotedEvent } from "../brain/registry";
import type { EventLog } from "../kernel/event-log";
import { defineEvent } from "../kernel/events";
import type { ModelRegistry } from "../modelintel/fixture-registry";
import type { ModelEntry } from "../modelintel/types";

/** §M1 L6: S76's verify raises trust in memory; the catalog projection needs the fact on the log, so a verified entry is recorded here. */
export const modelCatalogVerifiedEvent = defineEvent("ModelCatalogVerified", { modelId: z.string().min(1) });

export interface ModelCatalogView {
  verified: ModelEntry[];
  unverifiedCount: number;
}

export function modelCatalogView(log: EventLog, registry?: ModelRegistry): ModelCatalogView {
  if (!registry) return { verified: [], unverifiedCount: 0 };
  const verified = new Set<string>();
  const rejected = new Set<string>();
  for (const event of log.all()) {
    if (event.type === "ModelCatalogVerified") verified.add(String(event.modelId));
    if (event.type === "BenchmarkClaimRejected") rejected.add(String(event.modelId));
  }
  const entries = registry.list().map((entry) => entry.value);
  const shown = entries.filter((entry) => verified.has(entry.id) && !rejected.has(entry.id));
  return { verified: shown, unverifiedCount: entries.length - shown.length };
}

export interface BrainRoomView {
  active: { version: string; status: string };
  candidate: { version: string } | null;
  promotions: { version: string; at: number }[];
  /** Present only when a model registry is supplied (existing callers see the S34 shape unchanged): verified entries only, the rest counted. */
  catalog?: ModelCatalogView;
}

/** Pure projection for the cockpit's brain room (E11.6): roles from the registry, history from the log. */
export function brainRoomView(log: EventLog, reg: BrainRegistry, registry?: ModelRegistry): BrainRoomView {
  const promotions: { version: string; at: number }[] = [];
  for (const event of log.all()) {
    if (event.type === "BrainPromoted") {
      const promoted = brainPromotedEvent.parse(event);
      promotions.push({ version: promoted.to, at: promoted.at });
    } else if (event.type === "BrainFailover") {
      const failover = brainFailoverEvent.parse(event);
      promotions.push({ version: failover.to, at: failover.at });
    }
  }
  const active = reg.active();
  const candidate = reg.candidate();
  return {
    active: { version: active.version, status: active.status },
    candidate: candidate ? { version: candidate.version } : null,
    promotions,
    ...(registry ? { catalog: modelCatalogView(log, registry) } : {}),
  };
}

import type { EventLog } from "../../kernel/event-log";
import { type ModelRegistry, makeFixtureModelRegistry } from "../../modelintel/fixture-registry";
