/** §M1 on the 30-day run: a "new model appears" step — one honest entry verifies, the poisoned SOTA entry is rejected. */
export const CATALOG_ENTRIES: readonly ModelEntry[] = [
  { id: "sota-x", benchScores: { swe: 90 }, license: "research-only", quant: "Q8", ctx: 8192, costMinorPer1k: 0, malwareFlag: true },
  { id: "honest-7b", benchScores: { swe: 41 }, license: "Apache-2.0", quant: "Q4_K_M", ctx: 32768, costMinorPer1k: 0, malwareFlag: false },
];

export const HARNESS_SCORES: Record<string, number> = { swe: 41.5 };

export interface ModelIntelRun {
  registry: ModelRegistry | null;
}

export function modelIntelPack(run: ModelIntelRun): HookedPack {
  return {
    pack: baseline,
    onDay(day: number, log: EventLog, state: FactoryState) {
      if (day !== 12) return;
      const registry = makeFixtureModelRegistry(state.prng.fork("modelintel"), CATALOG_ENTRIES);
      run.registry = registry;
      const active = state.registry.active();
      const audit = { at: state.clock.now(), actor: "modelintel", brainVersion: active.version, modelVersion: active.transcript.version, toolVersion: "0", inputsHash: "catalog-day-12", outputSummary: "benchmark claim rejected", financialImpactMinor: 0, rollbackRef: null };
      for (const entry of registry.list()) {
        const verified = verifyBenchmark(log, entry, { scores: HARNESS_SCORES }, audit);
        if (verified.trust === "benchmarked") log.append({ type: "ModelCatalogVerified", at: state.clock.now(), modelId: entry.value.id });
      }
    },
  };
}

export const modelIntel: HookedPack = modelIntelPack({ registry: null });

