  });
});

import { z } from "zod";
import { TRUST_ORDER, type Trust } from "../trust/trust";

/** E3: a research claim cites the evidence nodes that ground it — a claim with no citation is not a claim. */
export interface Claim {
  text: string;
  evidenceNodeIds: string[];
  trust: Trust;
}

export interface OpportunityBrief {
  id: string;
  claims: Claim[];
  /** Logical time the brief was assembled (E13 freshness). */
  freshnessAt: number;
}

export const claimSchema: z.ZodType<Claim> = z
  .object({
    text: z.string().min(1),
    evidenceNodeIds: z.array(z.string().min(1)).min(1),
    trust: z.enum(TRUST_ORDER),
  })
  .strict();

export const opportunityBriefSchema: z.ZodType<OpportunityBrief> = z
  .object({
    id: z.string().min(1),
    claims: z.array(claimSchema),
    freshnessAt: z.number().int(),
  })
  .strict();

import { meetsMin, type Trust } from "../trust/trust";

export type ClaimClass = "evidence" | "hype";

/** Hype vs evidence (§M2): only claims at `benchmarked` or above count as evidence; everything below is hype. */
export function classifyClaim(trust: Trust): ClaimClass {
  return meetsMin(trust, "benchmarked") ? "evidence" : "hype";
}

