import type { EvidenceGraph } from "../evidence/graph";
import type { Clock } from "../kernel/clock";
import type { Prng } from "../kernel/prng";
import type { WebService } from "../services/sim-service";
import { type Claim, type OpportunityBrief, opportunityBriefSchema } from "./types";

/** §M2 L3: a fixture research run — every page is a tainted evidence node, every claim cites it, the brief is stamped by the clock. */
export function researchOpportunity(g: EvidenceGraph, web: WebService, urls: readonly string[], clock: Clock, prng: Prng): OpportunityBrief {
  const claims: Claim[] = [];
  for (const url of urls) {
    const page = web.fetch(url);
    const pageNode = g.addNode({ kind: "fact", trust: page.trust, label: `page ${url}`, data: { url, contentHash: page.value.contentHash, status: page.value.status } });
    const claimNode = g.addNode({ kind: "claim", trust: page.trust, label: `claim from ${url}`, data: { excerpt: page.value.body.slice(0, 80) } });
    g.link({ from: claimNode.id, to: pageNode.id, sign: "supports", confidence: 1, freshnessAt: clock.now() });
    claims.push({ text: page.value.status === 200 ? page.value.body.slice(0, 80) : `no content at ${url}`, evidenceNodeIds: [pageNode.id], trust: page.trust });
  }
  return opportunityBriefSchema.parse({ id: prng.nextId("brief"), claims, freshnessAt: clock.now() });
}

