/** V7 #1: no unverified public claim — an outreach claim must ground to a first-party-verified leaf or it is blocked and audited. */
export const publicClaimBlockedEvent = defineEvent("PublicClaimBlocked", { claimText: z.string().min(1), reason: z.string().min(1) });

registerExternalEffectTypes(["PublicClaimBlocked"]);

export function guardPublicClaim(log: EventLog, g: EvidenceGraph, claim: Claim, audit: Omit<AuditFields, "sideEffectId" | "approvalSource">): "allowed" | "blocked" {
  const decision = g.addNode({ kind: "decision", trust: claim.trust, label: `publish: ${claim.text.slice(0, 60)}` });
  for (const evidenceId of claim.evidenceNodeIds) {
    if (g.node(evidenceId)) g.link({ from: decision.id, to: evidenceId, sign: "supports", confidence: 1, freshnessAt: audit.at });
  }
  const grounding = traceGrounding(g, decision.id, "first-party-verified");
  if (grounding.grounded) return "allowed";
  const blocked = log.append({ type: "PublicClaimBlocked", at: audit.at, claimText: claim.text, reason: `weakest leaf ${grounding.weakestLeafTrust}; a public claim needs first-party-verified grounding` });
  emitAudit(log, { ...audit, approvalSource: "policy", sideEffectId: blocked.id });
  return "blocked";
}

/** V7 #2: an asserted list (93 contacts) is grounded only if it traces to benchmarked-or-better evidence. */
export function contactListGrounded(g: EvidenceGraph, nodeId: string): boolean {
  return g.node(nodeId) !== undefined && traceGrounding(g, nodeId, "benchmarked").grounded;
}

