/** E12: the radar shows evidence quality and freshness per brief — hype is visible as hype. */
export interface RadarRow {
  briefId: string;
  evidenceRatioBps: number;
  freshnessDays: number;
  hypeCount: number;
}

export function marketRadarView(briefs: readonly OpportunityBrief[], now: number): { rows: RadarRow[] } {
  const rows = briefs.map((brief) => {
    const total = brief.claims.length;
    const evidence = brief.claims.filter((claim) => classifyClaim(claim.trust) === "evidence").length;
    return { briefId: brief.id, evidenceRatioBps: total === 0 ? 0 : Math.round((evidence * 10_000) / total), freshnessDays: Math.max(0, Math.floor((now - brief.freshnessAt) / DAY_MS)), hypeCount: total - evidence };
  });
  return { rows: rows.sort((a, b) => b.evidenceRatioBps - a.evidenceRatioBps || (a.briefId < b.briefId ? -1 : a.briefId > b.briefId ? 1 : 0)) };
}

import type { EventLog } from "../../kernel/event-log";
