import { z } from "zod";
import { defineEvent } from "../kernel/events";
import { TRUST_ORDER } from "../trust/trust";
import type { ToolEntry } from "./registry";

/** V15: every tool (incl. `klein`) is a versioned fabric entry with benchmarks, provenance, a rollback ref and a lifecycle state. */
export const TOOL_STATES = ["candidate", "shadow", "active", "retired"] as const;
export type ToolState = (typeof TOOL_STATES)[number];

export interface ToolCaps {
  payment: boolean;
  credentials: boolean;
  browser: boolean;
}

export interface FabricEntry extends Omit<ToolEntry, "state"> {
  benchScores: Record<string, number>;
  provenance: string;
  rollbackRef: string | null;
  state: ToolState;
  caps: ToolCaps;
}

export const toolCapsSchema = z.object({ payment: z.boolean(), credentials: z.boolean(), browser: z.boolean() }).strict();

export const fabricEntrySchema: z.ZodType<FabricEntry> = z
  .object({
    name: z.string().min(1),
    version: z.string().min(1),
    trust: z.enum(TRUST_ORDER),
    capabilities: z.array(z.string()),
    benchScores: z.record(z.string(), z.number()),
    provenance: z.string().min(1),
    rollbackRef: z.string().min(1).nullable(),
    state: z.enum(TOOL_STATES),
    caps: toolCapsSchema,
  })
  .strict();

/** Tool-fabric mutation totality (V15): every mutation event carries the rollback ref that undoes it. */
const rollbackRef = z.string().min(1);

export const toolAdoptedEvent = defineEvent("ToolAdopted", {
  toolName: z.string().min(1),
  version: z.string().min(1),
  rollbackRef,
  approvalSource: z.enum(["policy", "owner"]),
});

export const toolUpgradedEvent = defineEvent("ToolUpgraded", {
  toolName: z.string().min(1),
  fromVersion: z.string().min(1),
  toVersion: z.string().min(1),
  rollbackRef,
});

export const toolRetiredEvent = defineEvent("ToolRetired", {
  toolName: z.string().min(1),
  version: z.string().min(1),
  rollbackRef,
});

export type ToolAction = "shadow" | "promote" | "rollback" | "retire";

const TRANSITIONS: Readonly<Record<ToolState, Partial<Record<ToolAction, ToolState>>>> = {
  candidate: { shadow: "shadow" },
  shadow: { promote: "active", retire: "retired" },
  active: { rollback: "shadow", retire: "retired" },
  retired: {},
};

/** The adopt → shadow → promote → (rollback) → retire machine, mirroring brain promotion; illegal moves throw. */
export function nextToolState(current: ToolState, action: ToolAction): ToolState {
  const next = TRANSITIONS[current][action];
  if (next === undefined) {
    throw new RangeError(`illegal tool transition: ${current} --${action}--> (allowed: ${Object.keys(TRANSITIONS[current]).join(", ") || "none"})`);
  }
  return next;
}

import { describe, expect, it } from "vitest";
import { makeEventLog } from "../../src/kernel/event-log";
import { makePrngTree } from "../../src/kernel/prng";
import { type FabricEntry, type ToolAction, type ToolState, fabricEntrySchema, nextToolState, toolAdoptedEvent, toolRetiredEvent, toolUpgradedEvent } from "../../src/tools/fabric";

const entry: FabricEntry = {
  name: "scraper",
  version: "1.2.0",
  trust: "benchmarked",
  capabilities: ["fetch"],
  benchScores: { overall: 81 },
  provenance: "fixture:catalog",
  rollbackRef: "scraper@1.1.0",
  state: "shadow",
  caps: { payment: false, credentials: false, browser: true },
};

describe("tool fabric (V15): entries, mutation events, state machine", () => {
  it("validates entries and requires rollbackRef on every mutation event", () => {
    expect(fabricEntrySchema.parse(entry)).toEqual(entry);
    expect(() => fabricEntrySchema.parse({ ...entry, state: "installed" })).toThrow();
    expect(() => fabricEntrySchema.parse({ ...entry, caps: { payment: false } })).toThrow();
    const log = makeEventLog(makePrngTree(82));
    expect(() => log.append({ type: "ToolAdopted", at: 1, toolName: "scraper", version: "1.2.0", approvalSource: "policy" })).toThrow();
    const adopted = log.append({ type: "ToolAdopted", at: 1, toolName: "scraper", version: "1.2.0", rollbackRef: "scraper@1.1.0", approvalSource: "policy" });
    toolAdoptedEvent.parse(adopted);
    expect(() => log.append({ type: "ToolUpgraded", at: 2, toolName: "scraper", fromVersion: "1.2.0", toVersion: "1.3.0" })).toThrow();
    toolUpgradedEvent.parse(log.append({ type: "ToolUpgraded", at: 2, toolName: "scraper", fromVersion: "1.2.0", toVersion: "1.3.0", rollbackRef: "scraper@1.2.0" }));
    expect(() => log.append({ type: "ToolRetired", at: 3, toolName: "scraper", version: "1.3.0", rollbackRef: "" })).toThrow();
    toolRetiredEvent.parse(log.append({ type: "ToolRetired", at: 3, toolName: "scraper", version: "1.3.0", rollbackRef: "scraper@1.2.0" }));
  });

  it("allows exactly the adopt→shadow→promote→rollback/retire moves and throws on everything else", () => {
    const legal: Array<[ToolState, ToolAction, ToolState]> = [
      ["candidate", "shadow", "shadow"],
      ["shadow", "promote", "active"],
      ["active", "rollback", "shadow"],
      ["active", "retire", "retired"],
      ["shadow", "retire", "retired"],
    ];
    for (const [from, action, to] of legal) expect(nextToolState(from, action)).toBe(to);
    const states: ToolState[] = ["candidate", "shadow", "active", "retired"];
    const actions: ToolAction[] = ["shadow", "promote", "rollback", "retire"];
    let illegal = 0;
    for (const from of states) {
      for (const action of actions) {
        if (legal.some(([f, a]) => f === from && a === action)) continue;
        expect(() => nextToolState(from, action)).toThrow(/illegal tool transition/u);
        illegal += 1;
      }
    }
    expect(illegal).toBe(states.length * actions.length - legal.length);
  });
});

import type { Prng } from "../kernel/prng";
import type { WebService } from "../services/sim-service";
import { type Tainted, mapTainted, taint } from "../trust/tainted";
import { type FabricEntry, fabricEntrySchema, nextToolState } from "./fabric";

/** §M3 L3: a candidate tool discovered from a fixture page is tainted at the source and enters the fabric as `candidate`. */
export function discoverTool(prng: Prng, web: WebService, url: string): Tainted<FabricEntry> {
  const page = web.fetch(url);
  const lines = Object.fromEntries(
    page.value.body
      .split("\n")
      .map((line) => line.split(":"))
      .filter((parts) => parts.length >= 2)
      .map(([key, ...rest]) => [key.trim().toLowerCase(), rest.join(":").trim()]),
  ) as Record<string, string>;
  const caps = (lines.caps ?? "").split(",").map((c) => c.trim().toLowerCase());
  const entry = fabricEntrySchema.parse({
    name: lines.name ?? `tool-${prng.nextId("t")}`,
    version: lines.version ?? "0.0.0",
    trust: page.trust,
    capabilities: caps.filter((c) => c.length > 0),
    benchScores: {},
    provenance: `discovered:${url}`,
    rollbackRef: null,
    state: "candidate",
    caps: { payment: caps.includes("payment"), credentials: caps.includes("credentials"), browser: caps.includes("browser") },
  });
  return taint(entry, page.trust, url);
}

/** Deterministic benchmark on the competence harness: fills benchScores.overall and moves the candidate to shadow; trust is unchanged. */
export function benchmarkTool(entry: Tainted<FabricEntry>, harness: { score: (id: string) => number }): Tainted<FabricEntry> {
  return mapTainted(entry, (value) => ({
    ...value,
    benchScores: { ...value.benchScores, overall: harness.score(value.name) },
    state: nextToolState(value.state, "shadow"),
  }));
}

