import { type AuditFields, emitAudit } from "../audit/audit";
import { registerExternalEffectTypes } from "../audit/side-effect";
import { type Capability, isSubScope, isValid } from "../auth/capability";
import { commitOnce } from "../brain/idempotency";
import type { EventLog } from "../kernel/event-log";
import type { Tainted } from "../trust/tainted";
import { meetsMin, trustRank } from "../trust/trust";
import { type FabricEntry, toolAdoptedEvent } from "./fabric";

/** V15: adopting a tool is a governed mutation of the fabric — gated, tokened, audited, rollback-able, once. */
export const ADOPT_SCOPE = "tools:adopt";

/** The S82 events must be defined before they are registered as side effects (a value import keeps the module order honest). */
void toolAdoptedEvent;
registerExternalEffectTypes(["ToolAdopted", "ToolUpgraded", "ToolRetired"]);

/** The tool safety ratchet: an upgrade may never add payment/credential caps, lower trust, or drop its rollback ref. */
export function ratchetOkTool(before: FabricEntry, after: FabricEntry): boolean {
  if (after.caps.payment && !before.caps.payment) return false;
  if (after.caps.credentials && !before.caps.credentials) return false;
  if (trustRank(after.trust) < trustRank(before.trust)) return false;
  if (before.rollbackRef !== null && after.rollbackRef === null) return false;
  return true;
}

export type AdoptResult = { status: "adopted" } | { status: "rejected"; reason: string };

export function adoptTool(log: EventLog, entry: Tainted<FabricEntry>, token: Capability | null, now: number, audit: Omit<AuditFields, "sideEffectId" | "approvalSource" | "at">): AdoptResult {
  if (!meetsMin(entry.trust, "benchmarked")) return { status: "rejected", reason: `trust ${entry.trust} is below benchmarked` };
  if (token === null || !isValid(token, now)) return { status: "rejected", reason: "no valid capability token" };
  if (!isSubScope(ADOPT_SCOPE, token.scope)) return { status: "rejected", reason: `token scope ${token.scope} does not cover ${ADOPT_SCOPE}` };
  if (entry.value.rollbackRef === null) return { status: "rejected", reason: "no rollback ref" };
  const adopted = commitOnce(
    log,
    `tool-adopt:${entry.value.name}@${entry.value.version}`,
    () => log.append({ type: "ToolAdopted", at: now, toolName: entry.value.name, version: entry.value.version, rollbackRef: entry.value.rollbackRef as string, approvalSource: "policy" }),
    now,
  );
  if (adopted) {
    emitAudit(log, { ...audit, at: now, approvalSource: "policy", sideEffectId: adopted.id, rollbackRef: entry.value.rollbackRef });
  }
  return { status: "adopted" };
}

