/** V14: !Klein is one row in the tool catalog, not the spine. Pure selector over the S47 registry + the S82 fabric. */
export interface ToolCatalogRow {
  id: string;
  version: string;
  state: ToolState;
  benchScore: number | null;
  trust: Trust;
}

export function toolCatalogView(registry: ToolRegistry, fabric: readonly FabricEntry[]): { rows: ToolCatalogRow[] } {
  const rows = new Map<string, ToolCatalogRow>();
  for (const entry of registry.list()) {
    rows.set(entry.name, { id: entry.name, version: entry.version, state: entry.state, benchScore: null, trust: entry.trust });
  }
  for (const entry of fabric) {
    rows.set(entry.name, { id: entry.name, version: entry.version, state: entry.state, benchScore: entry.benchScores.overall ?? null, trust: entry.trust });
  }
  return { rows: [...rows.values()].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0)) };
}

