import { z } from "zod";
import type { Clock } from "../kernel/clock";
import type { EventLog } from "../kernel/event-log";
import { defineEvent, type DomainEvent } from "../kernel/events";
import { MEMORY_WRITTEN, type MemoryClaim, memoryWrittenEvent, readMemory, writeMemory } from "./memory";

/** E13 knowledge gardening: a merge never overwrites — it supersedes with a correction event, and high-stakes facts decay. */
export const MEMORY_CORRECTED = "MemoryCorrected";

export const memoryCorrectedEvent = defineEvent(MEMORY_CORRECTED, {
  key: z.string().min(1),
  fromVersion: z.string().min(1).nullable(),
  toVersion: z.string().min(1),
  reason: z.string().min(1),
});

export interface RevalidationPolicy {
  /** Age (logical ms) after which a high-stakes claim must be re-validated before it may ground a decision. */
  ttlMs: number;
  highStakesKeys: readonly string[];
}

/** The event id of the live (unsuperseded) claim for `key`, or null when nothing is written yet. */
function liveClaimId(log: EventLog, key: string): string | null {
  const superseded = new Set<string>();
  const ids: string[] = [];
  for (const event of log.all()) {
    if (event.type !== MEMORY_WRITTEN) continue;
    const written = memoryWrittenEvent.parse(event);
    if (written.key !== key) continue;
    ids.push(written.id);
    if (written.supersedes !== null) superseded.add(written.supersedes);
  }
  const live = ids.filter((id) => !superseded.has(id));
  return live[live.length - 1] ?? null;
}

/**
 * Merge new evidence into `key`: writes a claim that supersedes the live one (lineage keeps both, E13) and appends the
 * MemoryCorrected event naming both versions and the reason. Returns the now-live claim.
 */
export function mergeClaim(
  log: EventLog,
  key: string,
  claim: Omit<MemoryClaim, "key" | "at" | "supersedes">,
  reason: string,
  clock: Clock,
): MemoryClaim {
  const fromVersion = liveClaimId(log, key);
  const written: DomainEvent = writeMemory(log, { key, value: claim.value, trust: claim.trust, provenance: claim.provenance, supersedes: fromVersion }, clock.now());
  log.append({ type: MEMORY_CORRECTED, at: clock.now(), key, fromVersion, toVersion: written.id, reason });
  const live = readMemory(log, key);
  if (!live) throw new Error(`mergeClaim: no live claim for "${key}" after writing`);
  return live;
}

/** Logical age of a claim (never negative). */
export function freshnessMs(claim: MemoryClaim, now: number): number {
  return Math.max(0, now - claim.at);
}

/** A high-stakes claim older than the policy's ttl needs re-validation; other keys, or absent claims, never do. */
export function needsRevalidation(log: EventLog, key: string, now: number, policy: RevalidationPolicy): boolean {
  if (!policy.highStakesKeys.includes(key)) return false;
  const claim = readMemory(log, key);
  if (!claim) return false;
  return freshnessMs(claim, now) > policy.ttlMs;
}

/** Action-gating view of decay: "stale" blocks grounding a new decision on the claim until it is merged afresh. */
export function revalidationGate(log: EventLog, key: string, now: number, policy: RevalidationPolicy): "ok" | "stale" {
  return needsRevalidation(log, key, now, policy) ? "stale" : "ok";
}

import { describe, expect, it } from "vitest";
import { makeManualClock } from "../../src/kernel/clock";
import { makeEventLog } from "../../src/kernel/event-log";
import { makePrngTree } from "../../src/kernel/prng";
import { MEMORY_CORRECTED, freshnessMs, mergeClaim, needsRevalidation, revalidationGate } from "../../src/memory/gardening";
import { memoryLineage, readMemory, writeMemory } from "../../src/memory/memory";

const policy = { ttlMs: 1_000, highStakesKeys: ["risk-tolerance"] };

describe("knowledge gardening (E13): provenance-preserving merges + decay", () => {
  it("a merge supersedes the live claim, keeps both versions in the lineage and records the correction", () => {
    const log = makeEventLog(makePrngTree(87));
    const clock = makeManualClock(10);
    writeMemory(log, { key: "risk-tolerance", value: "low", trust: "owner-stated", provenance: "owner chat 1" }, clock.now());
    clock.advance(5);
    const live = mergeClaim(log, "risk-tolerance", { value: "moderate", trust: "owner-stated", provenance: "owner chat 2" }, "owner revised", clock);
    expect(live.value).toBe("moderate");
    expect(readMemory(log, "risk-tolerance")?.value).toBe("moderate");
    const lineage = memoryLineage(log, "risk-tolerance");
    expect(lineage.map((claim) => claim.value)).toEqual(["low", "moderate"]);
    const corrections = log.all().filter((event) => event.type === MEMORY_CORRECTED);
    expect(corrections).toHaveLength(1);
    expect(corrections[0]?.reason).toBe("owner revised");
    expect(typeof corrections[0]?.fromVersion).toBe("string");
    expect(lineage[1]?.supersedes).toBe(corrections[0]?.fromVersion);
  });

  it("a first merge of an unknown key has no prior version", () => {
    const log = makeEventLog(makePrngTree(88));
    const clock = makeManualClock(0);
    mergeClaim(log, "brand-voice", { value: "plain", trust: "community-claim", provenance: "forum" }, "first write", clock);
    const correction = log.all().find((event) => event.type === MEMORY_CORRECTED);
    expect(correction?.fromVersion).toBeNull();
    expect(memoryLineage(log, "brand-voice")).toHaveLength(1);
  });

  it("a stale high-stakes claim gates 'stale' until a fresh merge; other keys and absent claims never gate", () => {
    const log = makeEventLog(makePrngTree(89));
    const clock = makeManualClock(0);
    writeMemory(log, { key: "risk-tolerance", value: "low", trust: "owner-stated", provenance: "owner chat" }, clock.now());
    writeMemory(log, { key: "brand-voice", value: "plain", trust: "community-claim", provenance: "forum" }, clock.now());
    expect(revalidationGate(log, "risk-tolerance", 500, policy)).toBe("ok");
    expect(revalidationGate(log, "risk-tolerance", 1_001, policy)).toBe("stale");
    expect(needsRevalidation(log, "brand-voice", 5_000, policy)).toBe(false);
    expect(revalidationGate(log, "unknown-key", 5_000, policy)).toBe("ok");
    clock.set(2_000);
    mergeClaim(log, "risk-tolerance", { value: "low", trust: "owner-stated", provenance: "owner re-confirmed" }, "re-validated", clock);
    expect(revalidationGate(log, "risk-tolerance", 2_500, policy)).toBe("ok");
    expect(freshnessMs(readMemory(log, "risk-tolerance") as never, 2_500)).toBe(500);
    expect(freshnessMs(readMemory(log, "risk-tolerance") as never, 1_000)).toBe(0);
  });
});

import type { Clock } from "../kernel/clock";
