/** V10: the honest unknowns this frontier incurs; each gates an action until an expert resolves it. */
export interface DebtV3 extends DebtItem {
  owner: string;
  forcingTrigger: string;
  expertReviewNeeded: true;
}

export const V3_DEBTS: readonly DebtV3[] = [
  { id: "debt-sandbox-tier", topic: "Docker isolation is insufficient for untrusted AI-generated code (ASI05) — microVM tier needed", risk: "high", resolved: false, gatesAction: "network-touching-build", owner: "infra", forcingTrigger: "any !Klein run executing network-touching generated code", expertReviewNeeded: true },
  { id: "debt-agent-payments-legal", topic: "Autonomous agent spend: mandate legality and custody vary by jurisdiction", risk: "high", resolved: false, gatesAction: "live-payout", owner: "finance", forcingTrigger: "any live payout or spend", expertReviewNeeded: true },
  { id: "debt-benchmark-contamination", topic: "Promotion benchmarks may not predict the real workload (contamination, deprecated suites)", risk: "med", resolved: false, gatesAction: "brain-promotion-live", owner: "maintainer", forcingTrigger: "a live brain promotion", expertReviewNeeded: true },
  { id: "debt-deceptive-alignment", topic: "Behavioral safety is insufficient against trained deception; scalable oversight is research-stage", risk: "high", resolved: false, gatesAction: "raise-autonomy-tier", owner: "redteam", forcingTrigger: "raising any brain's autonomy tier", expertReviewNeeded: true },
  { id: "debt-one-person-liability", topic: "The owner is a single point of failure for liability, compliance and incidents", risk: "med", resolved: false, gatesAction: "new-legal-entity", owner: "pm", forcingTrigger: "any action creating legal exposure", expertReviewNeeded: true },
];

/** Raise every v3 debt that is not already on the ledger (idempotent). Returns the appended events. */
export function raiseV3Debts(log: EventLog, clock: Clock): DomainEvent[] {
  const known = foldDebts(log.all());
  const appended: DomainEvent[] = [];
  for (const debt of V3_DEBTS) {
    if (known.has(debt.id)) continue;
    appended.push(log.append({ type: DEBT_RAISED, at: clock.now(), debtId: debt.id, topic: debt.topic, risk: debt.risk, gatesAction: debt.gatesAction }));
  }
  return appended;
}

/** The v3 debt record (owner, trigger, expert flag) for a ledger id, or undefined for slice-1 debts. */
export function v3DebtById(id: string): DebtV3 | undefined {
  return V3_DEBTS.find((debt) => debt.id === id);
}

