import type { BrainRegistry } from "../brain/registry";
import type { EventLog } from "../kernel/event-log";
import { brainRoomView } from "./brain-room";
import { moneyRoomView } from "./money-room";

export interface ReportLine {
  kind: "revenue" | "spend" | "shipped" | "approval" | "risk" | "brain" | "experiment";
  text: string;
  /** Drill-down reference: the log event id (or claim id) this line is derived from (V9). */
  evidenceNodeId: string;
  at: number;
}

/** V9 "while you were away", frontier edition: builds with evidence, fleet changes, burst spend, !Klein runs. */
export interface FrontierSection {
  built: { runId: string; specId: string; evidenceRunId: string }[];
  fleetChanges: string[];
  burstSpendMinor: number;
  kleinRuns: { commissioned: number; declined: number };
}

export interface SituationReport {
  headline: { revenueDeltaMinor: number; spendDeltaMinor: number; productsShipped: number; approvalsPending: number; risksRaised: number };
  lines: ReportLine[];
  frontier: FrontierSection;
}

export function frontierSection(log: EventLog): FrontierSection {
  const events = log.all();
  const passingRuns = new Set<string>();
  const startedRuns = new Map<string, string>();
  const fleetChanges: string[] = [];
  let burstSpendMinor = 0;
  let declined = 0;
  const burstIds = new Set(events.filter((event) => event.type === "FrontierBurstRequested").map((event) => event.id));
  for (const event of events) {
    switch (event.type) {
      case "KleinRunStarted":
        startedRuns.set(String(event.runId), String(event.specId));
        break;
      case "KleinEventLogged": {
        const inner = event.event as { t?: string; runId?: string; passed?: boolean };
        if (inner.t === "card-tests-run" && inner.passed) passingRuns.add(String(inner.runId));
        break;
      }
      case "CommissionDeclined":
        declined += 1;
        break;
      case "BrainPromoted":
      case "BrainFailover":
      case "BrainQuarantined":
        fleetChanges.push(`${event.type}: ${String(event.from ?? event.brainId)}${event.to ? ` → ${String(event.to)}` : ""}`);
        break;
      case "AuditEvent":
        if (burstIds.has(String(event.sideEffectId))) burstSpendMinor += Number(event.financialImpactMinor) || 0;
        break;
      default:
        break;
    }
  }
  const built = [...startedRuns.entries()].filter(([runId]) => passingRuns.has(runId)).map(([runId, specId]) => ({ runId, specId, evidenceRunId: runId }));
  return { built, fleetChanges, burstSpendMinor, kleinRuns: { commissioned: startedRuns.size, declined } };
}

const SPEND_ACCOUNTS = new Set(["payout", "reinvest", "spend", "ads"]);

/** The structured record that answers the audit (E11.6): every headline number and every line points at its evidence. */
export function situationReport(log: EventLog, reg: BrainRegistry): SituationReport {
  let revenueDeltaMinor = 0;
  let spendDeltaMinor = 0;
  let productsShipped = 0;
  let risksRaised = 0;
  const lines: ReportLine[] = [];
  for (const event of log.all()) {
    switch (event.type) {
      case "MoneyMoved": {
        const minor = Number(event.minor);
        const to = String(event.toAccount);
        const from = String(event.fromAccount);
        if (to === "revenue" && from === "world") {
          revenueDeltaMinor += minor;
          lines.push({ kind: "revenue", text: `received ${minor} minor units (${String(event.reason)})`, evidenceNodeId: event.id, at: event.at });
        } else if (SPEND_ACCOUNTS.has(to) || to === "world") {
          spendDeltaMinor += minor;
          lines.push({ kind: "spend", text: `${minor} minor units ${from} → ${to} (${String(event.reason)})`, evidenceNodeId: event.id, at: event.at });
        }
        break;
      }
      case "LaunchPublished":
        productsShipped += 1;
        lines.push({ kind: "shipped", text: `launched ${(event.branchNames as string[]).join(", ")}`, evidenceNodeId: event.id, at: event.at });
        break;
      case "AuthorityEscalationBlocked":
        risksRaised += 1;
        lines.push({ kind: "risk", text: `authority escalation blocked: ${String(event.reason)} (evidence ${String(event.evidenceTrust)} vs ${String(event.required)})`, evidenceNodeId: event.id, at: event.at });
        break;
      case "CommissionDeclined":
        lines.push({ kind: "risk", text: `build of ${String(event.specId)} declined: ${String(event.reason)}`, evidenceNodeId: event.id, at: event.at });
        break;
      case "VerificationRunRecorded":
        lines.push({ kind: "experiment", text: `${String(event.specId)} evidence ${String(event.from)} → ${String(event.to)}: ${String(event.evidence)}`, evidenceNodeId: event.id, at: event.at });
        break;
      case "BrainPromoted":
      case "BrainFailover":
        lines.push({ kind: "brain", text: `${event.type}: ${String(event.from)} → ${String(event.to)}`, evidenceNodeId: event.id, at: event.at });
        break;
      case "SpendApprovalRequested":
        lines.push({ kind: "approval", text: `approval pending: ${String(event.minor)} minor units for ${String(event.reason)}`, evidenceNodeId: event.id, at: event.at });
        break;
      default:
        break;
    }
  }
  const money = moneyRoomView(log);
  const brain = brainRoomView(log, reg);
  lines.push({ kind: "brain", text: `active brain ${brain.active.version}${brain.candidate ? `, candidate ${brain.candidate.version}` : ""}`, evidenceNodeId: `brain:${brain.active.version}`, at: log.all()[log.all().length - 1]?.at ?? 0 });
  return {
    headline: { revenueDeltaMinor, spendDeltaMinor, productsShipped, approvalsPending: money.pendingApprovals.length, risksRaised },
    lines,
    frontier: frontierSection(log),
  };
}

import type { EventLog } from "../kernel/event-log";
import type { DomainEvent } from "../kernel/events";

/** V9 replayable timeline: scrub the run by day; every external effect links to its audit, every audit jumps to its effect. */
export interface TimelineEvent {
  id: string;
  type: string;
  at: number;
  auditId: string | null;
}

export interface TimelineDay {
  day: number;
  events: TimelineEvent[];
}

export function timeline(log: EventLog, dayMs: number): TimelineDay[] {
  const auditBySideEffect = new Map<string, string>();
  for (const event of log.all()) {
    if (event.type === "AuditEvent") auditBySideEffect.set(String(event.sideEffectId), event.id);
  }
  const days = new Map<number, TimelineEvent[]>();
  for (const event of log.all()) {
    const day = Math.floor(event.at / dayMs);
    const list = days.get(day) ?? [];
    list.push({ id: event.id, type: event.type, at: event.at, auditId: auditBySideEffect.get(event.id) ?? null });
    days.set(day, list);
  }
  return [...days.entries()].sort((a, b) => a[0] - b[0]).map(([day, events]) => ({ day, events }));
}

/** Jump from an audit id to the audit event and the side effect it records. */
export function jumpToAudit(log: EventLog, auditId: string): { audit: DomainEvent; sideEffect: DomainEvent | undefined } | undefined {
  const audit = log.all().find((event) => event.id === auditId && event.type === "AuditEvent");
  if (!audit) return undefined;
  return { audit, sideEffect: log.all().find((event) => event.id === String(audit.sideEffectId)) };
}

