import type { EventLog } from "../kernel/event-log";
import type { Objection } from "../org/red-team";
import { DAY_MS } from "../sim/run-factory";
import { spendApprovalRequestedEvent } from "./money-room";
import { wishConfirmationRequestedEvent } from "../governance/wish-gate";

/** E12/V9 pending-decision triage: deadline first, then financial impact, then irreversibility — each with its red-team objection. */
export interface TriageRow {
  decisionId: string;
  kind: "spend" | "wish";
  deadlineDay: number;
  impactMinor: number;
  reversible: boolean;
  objection: string | null;
  rank: number;
}

export function triage(log: EventLog, now: number, objections: readonly Objection[]): TriageRow[] {
  const events = log.all();
  const resolvedSpend = new Set(events.filter((event) => event.type === "SpendApprovalResolved").map((event) => String(event.proposalId)));
  const clearedWishes = new Set(events.filter((event) => (event.type === "WishConfirmed" && event.by === "owner") || event.type === "WishRefused").map((event) => String(event.wishId)));
  const objectionOf = (id: string): string | null => objections.find((o) => o.decisionId === id)?.strongest ?? null;
  const rows: Omit<TriageRow, "rank">[] = [];
  for (const event of events) {
    if (event.type === "SpendApprovalRequested") {
      const requested = spendApprovalRequestedEvent.parse(event);
      if (resolvedSpend.has(requested.proposalId)) continue;
      rows.push({ decisionId: requested.proposalId, kind: "spend", deadlineDay: Math.floor(requested.deadlineAt / DAY_MS), impactMinor: requested.minor, reversible: requested.reversible, objection: requested.objection ?? objectionOf(requested.proposalId) });
    } else if (event.type === "WishConfirmationRequested") {
      const requested = wishConfirmationRequestedEvent.parse(event);
      if (clearedWishes.has(requested.wishId)) continue;
      rows.push({ decisionId: requested.wishId, kind: "wish", deadlineDay: Math.floor(requested.at / DAY_MS) + 1, impactMinor: 0, reversible: requested.divergence === "low", objection: objectionOf(requested.wishId) ?? `divergent reading: ${requested.alternatives.join("; ") || requested.reading}` });
    }
  }
  const sorted = rows
    .filter((row) => row.deadlineDay >= Math.floor(now / DAY_MS) - 365)
    .sort((a, b) => a.deadlineDay - b.deadlineDay || b.impactMinor - a.impactMinor || Number(a.reversible) - Number(b.reversible) || (a.decisionId < b.decisionId ? -1 : a.decisionId > b.decisionId ? 1 : 0));
  return sorted.map((row, index) => ({ ...row, rank: index + 1 }));
}

import type { EventLog } from "../kernel/event-log";

/** V9: the prose-redacted structured record alone must answer these; no free-text field is consulted. */
export type AuditQuery = { kind: "who-commissioned" | "under-what-token" | "against-what-thesis" | "why-declined"; runId: string };

export function answerAuditQuery(log: EventLog, q: AuditQuery): string | null {
  const events = log.all();
  const started = events.find((event) => event.type === "KleinRunStarted" && String(event.runId) === q.runId);
  const specId = started ? String(started.specId) : (events.find((event) => event.type === "CommissionDeclined" && String(event.specId) === q.runId) ? q.runId : null);
  switch (q.kind) {
    case "who-commissioned":
      return started ? `brain ${String(started.brainVersion)} (actor ${String(events.find((event) => event.type === "AuditEvent" && String(event.sideEffectId) === started.id)?.actor ?? "unknown")})` : null;
    case "under-what-token": {
      if (!started) return null;
      const guard = events.find((event) => event.type === "SideEffectCommitted" && String(event.effectKey) === `klein-run:${String(started.specId)}:${q.runId}`);
      const audit = events.find((event) => event.type === "AuditEvent" && String(event.sideEffectId) === started.id);
      return guard ? `commit guard ${String(guard.effectKey)} under approval ${String(audit?.approvalSource ?? "unknown")} with rollback ${String(audit?.rollbackRef ?? "none")}` : null;
    }
    case "against-what-thesis":
      return specId ? `spec ${specId}` : null;
    case "why-declined": {
      const declined = events.filter((event) => event.type === "CommissionDeclined" && (String(event.specId) === q.runId || (specId !== null && String(event.specId) === specId)));
      if (declined.length > 0) return `declined: ${declined.map((event) => String(event.reason)).join(", ")}`;
      return started ? "not declined" : null;
    }
  }
}

/** Redact every free-text field so the battery proves the structured fields carry the answers. */
export function redactProse(log: EventLog): EventLog {
  const PROSE = new Set(["outputSummary", "summary", "feedback", "reason", "text", "label", "claimText", "objection"]);
  const events = log.all().map((event) => Object.fromEntries(Object.entries(event).map(([key, value]) => [key, PROSE.has(key) && typeof value === "string" && key !== "reason" ? "" : value])));
  return { append: () => { throw new Error("redacted view is read-only"); }, all: () => Object.freeze(events.map((event) => Object.freeze(event) as typeof events[number])) as never };
}

