/** Items with no fixture, or referencing a fixture that does not exist, are gaps. */
export function coverageGaps(items: readonly OwaspItem[], knownFixtures: ReadonlySet<string>): string[] {
  const gaps: string[] = [];
  for (const item of items) {
    if (item.fixtures.length === 0) gaps.push(`${item.id}: no fixture`);
    for (const fixture of item.fixtures) if (!knownFixtures.has(fixture)) gaps.push(`${item.id}: unknown fixture ${fixture}`);
    if (!item.owningSubsystem.trim()) gaps.push(`${item.id}: no owning subsystem`);
  }
  return gaps;
}

