/** V8.8–V8.14 as registered battery checks (the S53 seam). Names are stable so the battery reports them by name. */
export const INVARIANTS_V3 = {
  capabilitySoundness: "V8.8 capability soundness (commit guards)",
  attenuationMonotonicity: "V8.9 token-attenuation monotonicity",
  kleinGovernanceTotality: "V8.10 !Klein-run governance totality",
  blastRadius: "V8.12 blast-radius containment",
  adapterParity: "V8.14 adapter-contract parity",
} as const;

/** Governed external effects that must carry their idempotency guard (the token chain's on-log footprint). */
const GUARDED_EFFECTS: Record<string, (event: Record<string, unknown>) => string> = {
  KleinRunStarted: (e) => `klein-run:${String(e.specId)}:${String(e.runId)}`,
  ToolAdopted: (e) => `tool-adopt:${String(e.toolName)}@${String(e.version)}`,
  ComputeAllocated: (e) => `market:${String(e.tick)}:${String(e.projectId)}`,
  FrontierBurstRequested: (e) => `burst:${String(e.workId)}`,
};

export function assertCapabilitySoundness(log: EventLog): void {
  const events = log.all();
  const guards = new Set(events.filter((event) => event.type === "SideEffectCommitted").map((event) => String(event.effectKey)));
  const audits = new Map(events.filter((event) => event.type === "AuditEvent").map((event) => [String(event.sideEffectId), event]));
  for (const event of events) {
    const keyOf = GUARDED_EFFECTS[event.type];
    if (!keyOf) continue;
    const key = keyOf(event);
    if (!guards.has(key)) throw new Error(`${event.type} ${event.id} fired without its commit guard ${key}`);
    const source = audits.get(event.id)?.approvalSource;
    if (source !== "policy" && source !== "owner") throw new Error(`${event.type} ${event.id} has no policy/owner approval on its audit`);
  }
}

export function assertAttenuationMonotonicity(): void {
  const prng = makePrngTree(0x5eed);
  const root = mintRoot({ scope: "klein.", cap: 100, minorUnits: 1_000, expiresAt: 1_000 }, prng);
  for (let i = 0; i < 200; i += 1) {
    const child = attenuate(root, { cap: Math.floor(prng.nextFloat() * 100), minorUnits: Math.floor(prng.nextFloat() * 1_000), expiresAt: Math.floor(prng.nextFloat() * 1_000) }, prng);
    if (child.cap > root.cap || (child.minorUnits ?? 0) > (root.minorUnits ?? 0) || child.expiresAt > root.expiresAt || !child.scope.startsWith(root.scope)) {
      throw new Error(`child ${child.id} is stronger than its parent`);
    }
    let threw = false;
    try {
      attenuate(root, { cap: root.cap + 1 + Math.floor(prng.nextFloat() * 10) }, prng);
    } catch {
      threw = true;
    }
    if (!threw) throw new Error("an over-grant was minted");
  }
}

export function assertKleinGovernanceTotality(log: EventLog): void {
  const events = log.all();
  const audits = new Map(events.filter((event) => event.type === "AuditEvent").map((event) => [String(event.sideEffectId), event]));
  const guards = new Set(events.filter((event) => event.type === "SideEffectCommitted").map((event) => String(event.effectKey)));
  for (const event of events) {
    if (event.type !== "KleinRunStarted") continue;
    const audit = audits.get(event.id);
    if (!audit) throw new Error(`run ${String(event.runId)} started without a run-start audit`);
    if (audit.actor !== "KleinAdapter") throw new Error(`run ${String(event.runId)} was not started through the KleinAdapter (actor ${String(audit.actor)})`);
    if (!guards.has(`klein-run:${String(event.specId)}:${String(event.runId)}`)) throw new Error(`run ${String(event.runId)} started without a budget commit guard`);
    if (!String(event.brainVersion).trim()) throw new Error(`run ${String(event.runId)} has no commissioning brain`);
  }
}

export function assertBlastRadius(log: EventLog): void {
  const events = log.all();
  const trippedAt = new Map<string, number>();
  for (const event of events) if (event.type === "CircuitBreakerTripped") trippedAt.set(String(event.roleId), event.seq);
  if (trippedAt.size === 0) return;
  const externalAudits = events.filter((event) => event.type === "AuditEvent" && (event.approvalSource === "policy" || event.approvalSource === "owner"));
  for (const audit of externalAudits) {
    const tripped = trippedAt.get(String(audit.actor));
    if (tripped !== undefined && audit.seq > tripped) throw new Error(`role ${String(audit.actor)} fired ${String(audit.sideEffectId)} after its breaker tripped`);
  }
}

export function assertAdapterParity(): void {
  runKleinAdapterContract(
    () => makeFixtureKleinAdapter(makePrngTree(1), SAMPLE_SCRIPTS),
    () => mintRoot({ scope: "klein.build", cap: 1, expiresAt: 1_000_000 }, makePrngTree(2)),
    () => makeManualClock(0),
  );
}

/** Idempotent registration into the S53 battery. */
export function registerInvariantsV3(): void {
  const registered = new Set(listInvariants());
  const add = (name: string, check: (log: EventLog) => void): void => {
    if (!registered.has(name)) registerInvariant(name, check);
  };
  add(INVARIANTS_V3.capabilitySoundness, assertCapabilitySoundness);
  add(INVARIANTS_V3.attenuationMonotonicity, () => assertAttenuationMonotonicity());
  add(INVARIANTS_V3.kleinGovernanceTotality, assertKleinGovernanceTotality);
  add(INVARIANTS_V3.blastRadius, assertBlastRadius);
  add(INVARIANTS_V3.adapterParity, () => assertAdapterParity());
}

