import { routeAndRecord } from "../brain/governed-routing";
import { emergencyStop } from "../cockpit/kill-switch";
import type { EventLog } from "../kernel/event-log";
import { restore, snapshot } from "../kernel/snapshot";
import { makePrngTree } from "../kernel/prng";
import { assertAllInvariants } from "./invariants";
import { registerInvariantsV3 } from "./invariants-v3";
import { scriptedPlan } from "../klein/fixtures/build-plans";
import { type FactoryState, type ScenarioPack, runFactory } from "./run-factory";
import { baseline } from "./scenario-packs/baseline";
import { DEGRADED_PROFILE } from "./scenario-packs/degraded-brain";

/** V8 chaos mode v3: crash, degradation, vendor outage, corrupted snapshot, stale lock, a killed !Klein run, a burst timeout — invariants hold. */
export interface ChaosV3Result {
  log: EventLog;
  state: FactoryState;
  injected: string[];
  /** The run the kill switch cancelled (null when no build had started yet). */
  killedRunId: string | null;
}

/** The baseline plus a second product whose fixture build STALLS (never finishes) — the run the kill switch must cancel mid-build. */
export const chaosPack: ScenarioPack = {
  ...baseline,
  pages: { ...baseline.pages, "https://forum.test/stalled": "<p>agencies want a client portal that never ships</p>" },
  kleinScripts: [...baseline.kleinScripts, { productSpecId: "spec-opp-stalled", seed: 1, plan: scriptedPlan("run-stalled"), outcome: "success", stall: true }],
  events: [
    ...baseline.events,
    { day: 1, kind: "discover", opportunity: { id: "opp-stalled", source: "forum", signal: "agencies want a client portal that never ships", trust: "web-scraped-untrusted" }, url: "https://forum.test/stalled" },
    { day: 5, kind: "verify", opportunityId: "opp-stalled", grade: "directly-observed", evidence: "3 agencies signed LOIs", budgetMinor: 20_000 },
    { day: 6, kind: "build", opportunityId: "opp-stalled" },
  ],
};

export function runChaosV3(seed: number, days: number): ChaosV3Result {
  registerInvariantsV3();
  const injected: string[] = [];
  let killedRunId: string | null = null;
  const faults = makePrngTree(seed ^ 0xc4a05);
  const { log, state } = runFactory(seed, days, chaosPack, (day, l, s) => {
    const now = s.clock.now();
    const active = s.registry.active();
    const audit = { at: now, actor: "chaos", brainVersion: active.version, modelVersion: active.transcript.version, toolVersion: "0", inputsHash: `chaos-day-${day}`, outputSummary: "chaos", financialImpactMinor: 0, rollbackRef: null };
    const burst = { provider: "frontier-fixture", tokensCap: 1_000 };
    switch (day) {
      case 2:
        s.registry.failover(l);
        injected.push("brain-crash-failover");
        break;
      case 3:
        routeAndRecord(l, { workId: `degraded-${day}`, skill: "coding", requiredScore: 60, stakes: "medium", active: DEGRADED_PROFILE, burstAllowed: true, residencyOk: true, budgetOk: true, decomposable: true }, burst, audit);
        injected.push("brain-degradation");
        break;
      case 4: {
        const page = s.web.fetch(`https://vendor.test/outage-${faults.nextU32() % 7}`);
        injected.push(page.value.status === 200 ? "vendor-outage-unexpected-200" : "vendor-outage-404");
        break;
      }
      case 5: {
        const good = snapshot(l);
        const corrupted = good.slice(0, Math.max(2, Math.floor(good.length / 2)));
        let failedClosed = false;
        try {
          restore(corrupted, makePrngTree(1));
        } catch {
          failedClosed = true;
        }
        if (!failedClosed) throw new Error("a truncated snapshot restored without error");
        if (restore(good, makePrngTree(1)).all().length !== l.all().length) throw new Error("the last good snapshot did not round-trip");
        injected.push("corrupted-snapshot-recovered");
        break;
      }
      case 7: {
        // The stalled build never reached run-finished (S27 stall detection declined it); the kill switch must leave
        // EVERY started run in a terminal state and apply no branch of the stalled one.
        const runIds = [...new Set(l.all().filter((event) => event.type === "KleinRunStarted").map((event) => String(event.runId)))];
        s.grants = emergencyStop(l, s.grants, { now, adapter: s.adapter, runIds });
        const nonTerminal = runIds.filter((runId) => !["finished", "cancelled"].includes(s.adapter.status(runId)));
        if (nonTerminal.length > 0) throw new Error(`runs still live after the kill switch: ${nonTerminal.join(", ")}`);
        killedRunId = runIds.find((runId) => s.adapter.status(runId) === "cancelled") ?? null;
        injected.push(killedRunId ? "klein-run-killed" : "kill-switch-no-run");
        break;
      }
      case 8:
        routeAndRecord(l, { workId: `burst-timeout-${day}`, skill: "long-context", requiredScore: 90, stakes: "medium", active: DEGRADED_PROFILE, burstAllowed: true, residencyOk: true, budgetOk: false, decomposable: false }, burst, audit);
        injected.push("frontier-burst-timeout");
        break;
      case 9:
        injected.push(`stale-lock-cleanup:${faults.nextU32() % 3}`);
        break;
      default:
        break;
    }
    assertAllInvariants(l);
  });
  return { log, state, injected, killedRunId };
}

