/**
 * The 30-day pack v2: every slice-2 cluster's steps composed over the baseline, each cluster keeping its own run holder
 * so two runs from the same seed never share state (E11.7 / V1). Hooks fire in a fixed order every day.
 */
export interface Slice2Run {
  briefs: never[];
  registry: null;
  adopted: never[];
}

export function makeSlice2Pack(): HookedPack {
  const research = researchPack({ briefs: [] });
  const modelIntel = modelIntelPack({ registry: null });
  const toolFabric = toolFabricPack({ adopted: [] });
  const hooks: readonly HookedPack[] = [degradedBrain, computeMarket, research, modelIntel, toolFabric, orgAdversarial, adversarialV3];
  const pack: ScenarioPack = { ...baseline, pages: { ...baseline.pages, [POISONED_TOOL_URL]: POISONED_TOOL_PAGE } };
  return {
    pack,
    onDay(day: number, log: EventLog, state: FactoryState) {
      for (const hook of hooks) hook.onDay(day, log, state);
    },
  };
}

export const slice2: HookedPack = makeSlice2Pack();

